(function(root){
const D={"personal":{"jiananfeng":{"like":null,"hate":null,"likeTxt":"玄鐵權印與西域濃粉","hateTxt":"明鏡與貌美孕妾的安胎補品","talk":{"陌生":["滾遠點！你這副裝模作樣的嘴臉，跟當年太傅楊駿那老賊一模一樣，教本宮作嘔。","想壓服我賈南風？先證明你手裡的刀比本宮這柄沾血短戟更狠再開口！"],"熟識":["前朝那幾個老將功高震主，你若拉不下臉殺，本宮今晚替你矯一道手詔夷他三族。","天下男人都愛盯著年輕貌美的皮囊發情，唯有攥在手裡的兵符與玉璽，永遠不會嫌棄本宮矮黑。"],"信賴":["你竟真敢把內廷生殺與刑堂全交給我？哈哈，天運者，你比司馬衷那個白癡皇帝帶勁一萬倍！","城南又來了批白皙俊俏的少年？哼，你管好你的前朝，本宮在偏室抬幾個木箱解悶的事少打聽。","這座城太安靜了，不抄兩個清流重臣的家、不在菜市口滾幾顆人頭，百官怎麼會怕你？"],"親密":["唯有盯著你眼裡那股毫無嫌棄的狠勁，本宮心口這團殺火才肯壓下半寸……但也只壓半寸。","哪個狐狸精敢搶在本宮前頭懷你的種，我照樣一短戟砸穿她的肚子，你最好別攔著！","剛才奉茶那賤婢眼神飄向我眉間贅瘤，准是在肚子裡笑本宮醜，拖出去拔舌杖斃省事。"],"誓約":["天下人罵我醜毒淫后又如何？這座孤城裡誰的腦袋不是攥在咱們夫妻手裡？","永遠別指望我為你變成溫順賢妻！要麼陪我踩著屍山血海稱霸，要麼看我點燃八王之亂掀翻燈塔！","太醫令程據那小子生得眉清目秀、手法又懂哄女人，今晚再召他來偏閣「診脈」。"]},"gift":["哼，算你有點眼力！這東西夠氣派，本宮收下了，比賞給那些花瓶賤婢值當得多。","（接過禮匣冷冷勾唇）夫君倒還算記掛著椒房殿。","拿這種寒酸破爛敷衍本宮？當我賈南風是金墉城裡討飯的廢后嗎？！滾出去！"],"low":["優柔寡斷得像司馬衷那個蠢貨！你若管不住這滿朝野心家，趁早把玉璽讓出來！","嫌本宮太毒太醜所以冷落我？好得很，等哪天這座城燒起來，別跪著求我收場！"],"win":["這天下終究是狠人吃軟骨頭！夫君，把敵將首級醃起來下酒，今晚咱們痛飲血酒！","哈哈哈哈！看見沒？還是本宮的東宮死士殺得最痛快！戰利品全搬進椒房殿！"],"lose":["一群酒囊飯袋！打輸了還有臉活著爬回城門？全拖去菜市口砍了祭旗！","城牆快塌了？去把城裡哭窮的豪商和流民全抓去扛石填牆，誰敢逃就地格殺！"],"陌生":[[null,"（身材矮小卻殺氣逼人，面帶青黑、眉間生著一顆顯眼贅瘤，手中短戟寒光直指你面門）瞪什麼瞪？沒見過長成這樣的西晉皇后？再多看一眼，本宮挖了你的眼珠子泡酒！"]],"熟識":[[null,"（慢條斯理塗抹著濃重西域脂粉，冷眼斜睨你）你倒不像洛陽朝堂那群膚淺廢物只會盯著皮囊。既懂點殺伐權術，有事便直說吧。"]],"信賴":[[null,"（將一卷抄家名冊拍在案上，唇角扯出陰鷙冷笑）滿城上下個個想踩到本宮頭上，唯獨你還算識相。前朝那些礙眼的老東西，隨時交給本宮矯詔清理。"]],"親密":[[null,"（反手扣住你伸向她臉頰的手腕，嗓音低啞而危險）別碰我眉間這顆瘤……哼，罷了，唯獨你這雙手不教人作嘔。把燈吹滅，今晚留在椒房殿陪我喝酒——不許走。"]],"誓約":[[null,"（玄黑鳳袍敞開一寸，眼中燒著扭曲而滾燙的狂熱）這柄短戟與這座江山的生殺大權，從今日起歸你我夫妻共掌。誰敢搶你、誰敢笑我醜、誰敢偷懷龍種，本宮便夷他三族！"]]},"daji":{"陌生":[[null,"妲己赤著一雙雪白玉足踩過冰冷玄石磚，赤紅薄紗裹著細腰豐乳與圓潤玉臀，繞著你慢悠悠踱了一圈，忽然湊近你頸側深吸一口氣，唇角勾起一抹勾魂妖笑。"],[null,"（吐氣如蘭，指尖順著你鎖骨滑下去）嗯～沒有殷壽那股暴躁的宿酒臭味，倒是藏著一股想把整片歸墟生吞活剝的狠勁呢。天運者，你比商王有趣多了。"],[null,"離我咽喉遠些，我可沒興趣步商王後塵。"],[null,"（咯咯嬌笑，指尖點在你心口）放心，尋常凡人的心肝奴家早吃膩了——當年剖比干看過七竅玲瓏心，不知天運者胸口這顆黑心，長了幾竅呀？"]],"熟識":[[null,"她不知從哪兒順來一塊烤得焦香流油的荒原異獸肋排，毫無貴婦架子地咬下一大口，又順手搶過你腰間酒壺仰頭猛灌，酒水順著雪白下頜滑進胸前深溝。"],[null,"（伸出粉舌舔去唇邊酒漬，妖瞳流轉）這破燈塔既沒酒池、也沒肉林，害本姑娘只能啃乾肉。主公，什麼時候踏平長安，替奴家挖一座灌滿烈酒的暖玉池呀？"],[null,"酒池還早，今晚烤肉管夠。妳方才在城外放的那場青丘狐火，確實燒得俐落。"],[null,"（得意翹起唇角，身後白影一閃）那是自然，區區畫皮孤鬼也敢在青丘九尾老祖宗面前賣弄幻術？"]],"信賴":[[null,"月色沉沉，她身後無聲浮出九道蓬鬆雪白狐影，百無聊賴地拍打著石欄。她盯著指尖跳動的幽藍狐火，語氣少見地褪去幾分嬉笑，透出千年冰寒。"],[null,"（輕笑得近乎森冷）世人罵我蘇妲己禍亂殷商、剖孕婦、設炮烙。可當初是女媧娘娘親降密旨叫我斷送成湯氣數，事成後卻翻臉降罪殺我——神佛也好、帝王也罷，全是用完就宰的涼薄東西。"],[null,"（伸手按住她微涼的手背）我不是高高在上的神佛，也不是蠢笨商王。在我這座城裡，沒人拿妳當棄子。"],[null,"（指尖一顫，狐火驟然騰亮，隨即反手勾住你的小指）……嘴真甜。你若敢騙奴家，我就把你鎖在鹿臺頂上，拿狐火日夜折騰到你求饒喔。"]],"親密":[[null,"剛推開暖閣木門，一股甜膩醉人的青丘狐香便撲面而來。妲己只著一件半透赤紗慵懶斜倚軟榻，豐乳半露、長腿交疊，見你走近，忽然伸手勾住你腰帶將你狠狠拽倒在懷裡。"],[null,"（修長雪腿盤上你的腰側，紅唇貼著你耳垂吐氣）主公整天跟那幫臭男人盯著沙盤，就不怕本姑娘寂寞難耐，半夜跑去把前朝大人全勾進被窩裡吸乾呀？"],[null,"（撐在她身側，目光直直盯進她泛著琥珀幽光的妖瞳）那妳今晚想怎麼折騰？"],[null,"（雙頰浮起一抹勾魂潮紅，指尖挑開你的衣襟）不拆城了……今晚本姑娘只要你陪我玩一場「只准看著奴家、不准睡」的遊戲。"]],"誓約":[[null,"後宮殿閣已就緒，觸發「妲己」誓約婚姻劇情。"],[null,"紅燭高燒，妲己換上一襲繡滿金絲九尾紋的大紅嫁衣，雪膚如玉、眼波瀲灩得攝人心魄，端起合巹酒的手指卻帶著一絲極淡的顫意。"],[null,"（將酒爵送到你唇邊，嗓音嬌媚而滾燙）千年修行，我看過無數男人跪在裙下求歡，唯獨你，看穿了本姑娘吃人的妖性，還敢親手把我迎進門。"],[null,"（一飲而盡，扣住她後頸重重吻住她染著酒香的紅唇）妲己，從今往後，妳的妖性、妳的瘋狂，全歸我管。"],[null,"（熱烈反吻，舌尖掠過你的唇角，隨後伏在你耳邊妖笑呢喃）夫君……既簽了青丘狐妖婚契，生生世世，你的肉身與魂魄全歸奴家享用囉。"],[null,"已與「妲己」締結婚姻，迎入後宮殿閣！"]],"talk":{"陌生":["主公身上的氣味真香，像陳年烈酒拌著血腥，教奴家喉嚨發癢。","別老繃著一張死人臉嘛，笑一個給本姑娘瞧瞧？","營裡那群凡人武將太粗蠢，整天只懂掄刀砍人，半點不懂風月。"],"熟識":["今天的烤獸肉太瘦太柴，下回挑頭肥嫩些的荒原獸來烤罷。","哪個老臣敢在殿上惹主公不快，告訴奴家，我半夜鑽進他夢裡嚇破他的膽。","這座燈塔的星盤清光，照得本姑娘身後九條尾巴都暖洋洋的。"],"信賴":["說實話……窩在你懷裡，比當年躺在朝歌鹿臺上痛快十倍。","主公看奴家的眼神裡有慾望、有狠勁，卻從沒那股假正經的嫌惡，真合我胃口。","外頭霧冷，快進暖閣烤炭火，奴家用體溫替你暖酒。"],"親密":["主公再貼近些嘛，奴家想聽你胸口跳亂的聲音。","再低頭看那些死氣沉沉的竹簡，本姑娘就放把狐火全給你燒成灰喔。","今夜哪兒也不許去，你這副身子全歸九尾狐霸佔了。"],"誓約":["夫君～早膳想啃炙肉、喝甜酒，還是……先在被窩裡吃點別的？","誰敢傷我夫君半分，本姑娘便放九尾真火把她燒成焦炭！","這輩子不禍別的國，專心禍害夫君你一個人就夠快活啦。"]},"gift":["呀，這明珠亮得像妖火，襯本姑娘的紅裙正好！賞你一個帶酒香的吻～","勉強入眼吧，可惜再怎麼精緻，也沒奴家這副身子耐看。","冷冰冰的破鐵塊，拿遠些啦，刮花本姑娘這雙嫩手怎麼辦？"],"low":["又摳門又古板得像比干那老東西……早知如此就不理你這破星盤了！","再敢把九尾狐晾在空屋裡，奴家今晚就自己溜進黑霧裡找樂子囉。"],"win":["咯咯，一群沒腦子的蠢貨，全被奴家的青丘狐火燒成焦肉啦！","大勝而歸！主公，今晚打算怎麼在榻上賞賜本姑娘呀？"],"lose":["討厭！這群黑霧怪物連男人都算不上，根本不吃魅惑！快撤，紗裙都沾髒了！","哼，這筆帳本姑娘記下了，下回一定把牠們全烤熟！","夫君總算摸進來啦？奴家剛溫好最烈的狐花釀，帳裡也點滿青丘催情香，快脫衣進來嘛～","從前總覺得凡人的壽命短得像露水，嫁給你之後，奴家竟巴不得這段墮落日子過得慢一點、再慢一點。","內廷與後宮本姑娘替你盯著呢，誰敢偷懶嚼舌根，我就用狐火烤焦她的屁股！","夫君整整幾旬不進鹿臺暖閣……怎麼，外頭哪個小騷貨比青丘九尾狐還會勾人？","嗅嗅……一身別人的廉價脂粉味喔～夫君，你是自己跪下老實交代，還是讓奴家用九尾把你綁在床柱上逼供？"],"like":null,"hate":null},"xiaji":{"like":null,"hate":null,"likeTxt":"赤紅絲綢衵服汗衫與駐顏異香","hateTxt":"酸腐禮教說教與貞節枷鎖","talk":{"陌生":["男人嘴上整日掛著禮義廉恥，眼睛卻永遠往女人胸口與腰臀鑽。天運者，你也一樣罷？","收留「殺三夫一君一子、亡一國兩卿」的春秋夏姬，你就不怕前朝重臣為了搶奴家拔刀互砍？"],"熟識":["昨夜宴席上那兩位實權大夫盯著奴家看得喉結直滾，改日邀他們進株林暖閣共飲如何？","想知道奴家年過四十卻肌膚勝雪、緊緻如少女的駐顏秘術？自然是多多採補天下最頂尖男人的陽氣囉，咯咯。"],"信賴":["你吃醋發狠的模樣真教人腿軟……越想把奴家鎖進被窩，就越要拿出踩死全城情敵的本事呀！","安啦，就算前朝大夫把奴家的赤紅衵服穿去朝堂炫耀，我心裡最燙的那個位子還是留給你的。","剛繡好兩件浸過體香的貼身紅汗衫，夫君猜猜，奴家今夜要賞給朝堂哪兩位大人？"],"親密":["看著滿城男人為了奴家這副豐乳肥臀發瘋流血、甚至險些亡國，你不覺著特別銷魂刺激嗎？","別拿貞節牌坊綁我，綁不住的。除非你把這世上所有比你強、比你兇的男人都殺絕！","世人罵我紅顏禍水，可當年陳靈公、孔寧、儀行父自己管不住下身互砍亡國，關奴家什麼事呀？"],"誓約":["就算明日城破人亡，我夏姬也絕不收心悔改！要嘛踩著情敵屍骨把奴家壓死在榻上，要嘛陪我一起醉死亡國夜！","這件最貼身的赤紅衵服只給你穿去上朝——至於明天會不會再繡新的，就看夫君今晚採補得賣不賣力囉～","聽說城外敵酋開出重金與萬石軍糧想搶奴家呢，夫君可得抓緊我這副身子囉～"]},"gift":["哎呀，這珍玩真襯奴家這身勝雪肌膚～今晚賞夫君一個魂銷骨酥的長夜罷！","（接過禮匣媚笑抬眸）夫君倒越來越懂怎麼哄夏姬開心了。","這麼寒酸的玩意兒也拿得出手？前朝那位年輕侍郎偷送進來的都比這貴重十倍呢。"],"low":["又小氣又古板，連當年陳靈公一半風流氣度都沒有，奴家真是白費心思。","既駕馭不住春秋第一尤物，趁早把奴家送給城外敵酋罷，人家開價可比你闊綽得多！"],"win":["凱旋大捷！今晚邀滿朝文武一起開株林夜宴，讓將士們看夠奴家這副身子、不醉不歸喔～","咯咯，瞧見沒？美人撩袖一笑，可比你們冷冰冰的軍法管用一百倍呢！"],"lose":["打輸啦？無妨，反正就算換個新敵酋踏破城門，奴家照樣會被八抬大轎捧成掌上尤物呀～","城牆快破啦？那奴家得先熏個駐顏香、補個紅妝，免得待會兒見新主人時不夠勾魂呢。"],"陌生":[[null,"（薄紗微敞露出豐滿雪白胸乳與纖腰，媚眼如絲地打量你）咯咯，天運者盯著奴家領口瞧這麼久，眼裡都快噴出火來囉～"]],"熟識":[[null,"（指尖輕輕轉著一方沾滿濃郁體香的赤紅絲帕）這座城裡的武將與大夫都挺有意思，昨夜還有兩位大人為了搶奴家掉在廊下的絲帕，差點當場拔劍互捅呢。"]],"信賴":[[null,"（慵懶倚在錦榻上，白皙長腿微展，眼波瀲灩）夫君的陽氣確實比當年陳靈公、孔寧還有楚國黑要那幫男人醇厚十倍，昨夜採補得奴家渾身酥軟舒暢極了～"]],"親密":[[null,"（玉臂勾住你頸項，豐軟酥胸緊貼你胸口吐氣如蘭）奴家承認你最合我胃口，但要我為了你斬斷與前朝男人的風流？呵呵，男人本就是越搶不到的才越發瘋嘛。"]],"誓約":[[null,"（赤紅衵服半褪至肩頭，露出勝雪香肌，眼底透出致命而狂傲的妖豔笑意）三夫一君一子、一國兩卿……如今輪到你這座歸墟燈塔啦！愛我夏姬，就做好為我與滿朝反目、再亡一國的準備！"]]},"liji":{"like":null,"hate":null,"likeTxt":"白玉淚壺與前朝密報冊","hateTxt":"剛直不阿的忠臣與當眾對質","talk":{"陌生":["妾身不過一介驪戎弱女子，不懂前朝兵事，只盼夫君安穩，莫遭身邊笑面虎暗算。","這深宮看似和睦，實則暗潮洶湧，夫君萬事可得多防著身邊人。"],"熟識":["昨夜妾身夢見有人在祭肉裡下毒害夫君，嚇得半夜哭醒……許是太在乎您才胡思亂想罷。","那位忠臣確有本事，連城裡百姓都只知將軍不知天運者呢——夫君得此良將，真是「福氣」。"],"信賴":["（三更無聲垂淚）夫君，滿朝都在等著看我失寵呢……你若心軟留著那些勢大難制之人，明日死無葬身之地的便是我們啊！","夫君放心，所有髒活與罵名妾身都能安排得天衣無縫，絕不污您半點明君清譽。","那位大將軍在軍中威望太盛了，妾身雖信他赤誠，可萬一他哪日被部下黃袍加身可怎麼辦呀……"],"親密":["看著你親手斬盡礙眼的忠良、把全城猜忌得人人自危，最後卻只敢抱緊妾身這副溫軟身子……夫君，這滋味真教人沉醉。","就算有朝一日你察覺毒肉是我灑的、夜泣是我演的，你猜你這雙沾滿冤血的手，還回得去從前嗎？","（眼眶驟紅，淚珠欲落不落）若是妾身惹得眾姐妹與重臣不快，不如夫君早些賜死我，免得世人罵我以一妾亂國。"],"誓約":["別指望我洗白悔改！我就是世上最溫柔、也最致命的枕邊毒蛇，而你，是我親手雕琢出來的多疑暴君！","來吧，把下一份前朝清洗名單遞給我，今夜妾身解衣靠在你懷裡陪你一筆一筆勾銷。","大祭胙肉妾身已用銀針替夫君驗過三遍了，待會兒旁人呈上來的吃食，您千萬別碰。"]},"gift":["（驚喜垂淚，溫婉福身）夫君如此厚待妾身，驪姬定當更加盡心替夫君「查清」身邊每一條毒蟲。","（柔聲接過禮匣，淺笑盈盈）夫君政務繁忙還惦記著妾身，真教人暖心。","（瞬間眼眶泛紅）定是哪位姐妹在夫君耳邊進了讒言……無妨，妾身受著便是。"],"low":["（淚珠順著白皙臉頰滑落）夫君寧可信外頭那群笑面虎，也不肯信枕邊人的苦心提醒麼……","（垂眸拭淚，眼底卻掠過冰冷寒芒）既覺妾身多嘴挑撥，不如趁早賜杯毒酒，免得日後看著夫君遭忠臣逼宮心碎。"],"win":["塵埃落定。往後這座城裡，再沒人敢動搖夫君與驪姬的位子了。","大勝凱旋！對了，方才聽說某位立功大將在軍中呼聲震天，夫君可得早些厚賞「安撫」才是呢。"],"lose":["（掩面泣訴）定是前線有人暗中通敵扯後腿！夫君萬萬不可心軟饒了那位領兵大將！","城防垮得如此蹊蹺，莫非工部有人私吞修城木石？讓妾身的驪戎密探替夫君查查罷。"],"陌生":[[null,"（素衣柔婉福身，眉眼楚楚動人、嗓音輕軟如春水）驪姬拜見天運者。妾身出身驪戎，歷經兵火，只盼能安分守己侍奉君側。"]],"熟識":[[null,"（替你輕輕卸下外袍，眼角恰到好處地泛紅）夫君連日操勞國事辛苦了……只是妾身昨夜無意聽聞幾位重臣私下對您頗有微詞，心裡實在替您發慌。"]],"信賴":[[null,"（柔聲奉上熱茶，指尖輕顫）這城裡上下人人都在誇那位大將與{b}寬厚仁慈、甚得民心，妾身聽著原該替夫君歡喜，卻不知為何總覺得心驚肉跳……"]],"親密":[[null,"（素白中衣半解、溫軟豐潤的身子緊貼進你懷裡，眼底卻藏著幽冷蛇瞳般的笑意）除了驪姬，這世上沒有第二個人真正值得夫君託付後背。"]],"誓約":[[null,"（燭影下緩緩勾起世上最溫柔也最毒辣的微笑）我是你最貼心的解語花，也是替你咬死一切忠良與情敵的枕邊蛇。咱們手上早沾滿同一群冤魂的血，夫君，你逃不掉的。"]]}},"gen":{"jiananfeng":{"meet":["西晉惡后賈南風在此！誰敢偷笑本宮矮黑長瘤，先問過我手裡這柄沾血短戟！","（陰毒目光掃過滿殿群臣）這座燈塔的玉璽與兵符歸誰管？醜話說在前頭，本宮絕不當任人擺布的擺設！"],"tide1":"黑霧壓境？正好，把城裡那幾個天天彈劾本宮的清流酸儒先押上城頭擋箭！","tide2":"霧潮快到了？慌什麼！傳本宮懿旨，臨陣後退半步者，連同家中老小一律夷三族！","tideNow":"殺！把這群黑霧畜生全剁成肉泥，誰敢軟腿逃跑，本宮親手一戟捅穿他胸口！","tideWin":"哈哈哈哈！看見沒？還是本宮的東宮死士殺得最痛快！戰利品全搬進椒房殿！","tideLose":"一群廢物將領！打輸了還有臉活著爬回來？全拖去菜市口砍了！","lowDur":"城牆快塌了？去抓城裡的富商與流民扛石填缺口，敢反抗者就地格殺！","stage":"這座燈塔總算有了點洛陽皇城的氣象——正好配得上本宮稱制掌權！","eve":"大戰前夜？端最烈的關中燒酒來！再把偏室木箱裡那個俊俏少年抬出來替本宮解解乏！","win":"這天下終究是狠人的天下！夫君，咱們今晚拿敵將腦殼盛酒慶功！","lose":"一群廢物將領！打輸了還有臉活著爬回來？全拖去菜市口砍了！"},"daji":{"meet":["嘻嘻……把奴家從朝歌火海裡喚出來的天運者，皮相倒是俊得合我胃口呢。","這破燈塔冷清得像墳場，主公可得夜夜疼惜奴家，我才肯替你魅惑敵軍喔。"],"tide2":"兩旬後霧潮又要撲上來啦？主公可得護緊奴家，別讓那些醜怪物髒了我的眼。","tide1":"黑霧這麼濃，正好適合點起漫天青丘狐火，把牠們連骨頭一起燒成灰。","tideNow":"九尾幻舞，惑亂群魔！全都跪在奴家赤足下受死罷！","tideWin":"咯咯，不過是一群沒腦子的黑霧畜生，今晚主公打算怎麼賞奴家呀？","tideLose":"討厭！外牆破了啦，主公快牽緊奴家退進內城！","lowDur":"燈塔都在發抖了……主公，你可別讓本姑娘陪你活埋在瓦礫堆裡呀。","stage":"城池越來越氣派了呢，再替奴家起一座堆金砌玉的鹿臺，就真像神仙窟了。","eve":"畫皮妖孽也敢賣弄幻術？明日教牠們見識什麼叫真正的青丘九尾傾國妖魅！","win":"長安奪回來啦！這座古城往後就歸主公和奴家酒池肉林、日夜荒唐囉～","lose":"哎呀……星火暗下去了，這場好戲終究還是要散場了嗎……"},"xiaji":{"meet":["（媚眼如絲，輕輕撩開半透紅紗一笑）春秋夏姬見過天運者～這座燈塔的男人，應該比陳國與楚國那幫貨色更耐玩罷？","（掩唇咯咯嬌笑）既敢把奴家召進城來，可得看緊你前朝重臣的褲腰帶，免得他們為了搶奴家拔刀自相殘殺喔！"],"tide1":"黑霧壓城？只要城裡這幫男人還捨不得奴家這具銷魂身子，自然會替你拚死守城的。","tide2":"哎呀，這黑霧燻得奴家細嫩肌膚都發乾了，快叫將士們把這群髒怪物趕遠點！","tideNow":"將士們殺得兇些呀！誰今晚斬的霧獸最多，奴家親手賞他一件貼身赤紅香帕喔～","tideWin":"咯咯，瞧見沒？美人一笑可比軍法鞭子管用一百倍呢！","tideLose":"打輸啦？無妨，換個新敵酋進城，奴家照樣是被捧在心尖上的尤物呀～","lowDur":"城牆快塌了？那奴家得先描眉點唇、換件最透的紅紗，免得見新主人時太狼狽呢。","stage":"城池越來越熱鬧繁華，慕名奔來的英俊猛將也越來越多，真教奴家心癢難耐～","eve":"大戰前夜最該幹什麼？當然是在株林暖閣裡與奴家徹夜採補、徹底洩一場火啦！","win":"凱旋大捷！今晚全朝文武齊聚株林開宴，不醉不歸喔～","lose":"打輸啦？無妨，換個新敵酋進城，奴家照樣被捧成寶貝呀～"},"liji":{"meet":["（楚楚可憐地屈膝福身）驪姬拜見天運者。願以微薄之軀，為夫君分憂解勞、細辨忠奸。","（垂眸淺笑，眼底寒光一閃）往後這前朝後宮誰忠誰反，便由妾身在枕邊慢慢替夫君看清罷。"],"tide1":"黑霧壓城，正好瞧瞧前朝諸將誰真拚死護主、誰想趁亂擁兵自重呢。","tide2":"夫君千萬保重身子，前線若有哪位將領出工不出力，妾身一定替您一筆筆記下。","tideNow":"（嗓音柔婉卻字字冷酷）凡臨陣遲疑半步者，皆視同通敵叛亂，殺無赦！","tideWin":"大勝而歸！對了，聽說某位凱旋大將在軍中呼聲高得嚇人，夫君可得及早「安撫」才是呢。","tideLose":"（掩面落淚）定是前線有人暗中賣主求榮！夫君萬不可輕饒那位領兵大將！","lowDur":"城防竟損毀至此，莫非工部貪墨了修城料石？讓妾身派人暗中查清楚罷。","stage":"城池越是繁盛，盯著這把君座的豺狼只怕也越多，夫君往後只能信妾身一人喔。","eve":"大戰前夜，妾身親手熬了安神湯……旁人呈上來的吃食，夫君今晚千萬別碰。","win":"塵埃落定。往後這座長安城裡，再無人敢威脅夫君與驪姬。","lose":"（垂淚低泣）定是前線有人暗中通敵扯後腿！夫君絕不可饒了那幫叛將！"}},"harem":{"jiananfeng":{"ev":[{"t":"後宮風聲","d":"賈南風在宮道上公然提著短戟攔下受寵妃嬪的肩輿，陰笑著拿冰涼戟尖點了點對方小腹與臉蛋，冷聲威嚇她「看好自己的肚子和這張臉」，嚇得六宮噤若寒蟬。","c":[["私下敲打她手段收斂些，免得鬧出人命",null],["冷笑縱容由她立威，順勢壓住後宮風氣",null]]}],"visit":["（慢條斯理拿絲帕擦拭短戟血槽，冷笑抬眸）終於捨得滾進本宮這座冷清殿閣了？還以為你爽死在別的狐狸精肚皮上了。"],"neu":["前朝那幫老狐狸近來老實多了，看來上回矯詔夷三族頗見成效。"],"crown":"（戴上鳳冠、扣上凰戒，青黑面容透出森然狂傲）中宮之位本就該歸我賈南風！從今日起，六宮生殺與子嗣去留全攥在本宮手裡，順我者生、逆我者夷三族！","otherMain":"讓{mother}那種軟骨頭騎在本宮頭上當主母？呵，天運者，你等著看金墉冷殿裡什麼時候多出一位活活餓死的新住客罷！","calm":["這座後宮唯有鮮血與恐懼才壓得住場子，少拿什麼姐妹和睦的廢話來煩本宮。"],"preg":"（撫過微隆小腹，面帶青黑發出陰狠狂笑）本宮胞宮結珠，有喜了！從今日起，六宮裡哪個賤婢敢再懷孕爭儲，本宮親提短戟砸爛她的胎室！","birth":"（盯著繈褓中嬰兒，眼底沒有半點慈愛，唯有赤裸權力野心）好孩子，將來這座孤城的玉璽與兵符，全都是你和娘親的！","kidWen":"讀什麼酸腐聖賢書？教他讀《商君書》、學矯詔殺人的毒計，絕不許長成司馬衷那個白癡！","kidWu":"好！把短戟與長刀握死在手裡，誰敢擋路便屠他滿門！"},"daji":{"ev":[{"t":"狐尾纏人","d":"九條雪白蓬鬆的狐尾無聲無息纏上你的腰腹與手腕，她赤足跨坐上你腿間，直接把你拖倒進軟榻不准起身。","c":[["順勢翻身將妖狐壓進錦被，今晚徹底交給她",null],["輕撓她下巴哄她鬆開尾巴，約定明日帶西域烈酒來賠罪",null]]},{"t":"妖火戲情敵","d":"妲己半夜故意放出一團幽藍狐火在受寵妃嬪窗外鬼哭狼嚎地起舞，嚇得對方一整夜縮在被窩裡失禁發抖。","c":[["捏住她的臉頰警告不許再捉弄姐妹，派人安撫受驚的夫人",null],["被這隻惡狐狸的狡黠逗笑，把她扛回軟榻親自教訓",null]]},{"t":"七竅玲瓏心","d":"她赤著雪白玉足踩在你膝頭，尖利丹蔻點著你胸口妖笑威脅，說你心裡若敢裝太多女人，她便像當年剖比干一樣剖開來吃掉。","c":[["扣住她纖細腳踝拉進懷裡深吻，說這顆心早歸九尾狐獨佔",null],["拿出閃亮珠玉哄住她，趁機轉移她的殺意",null]]}],"visit":["嗅嗅……夫君領口這股甜膩廉價的香粉味真教人反胃呢。說罷，你打算怎麼跪著哄回本姑娘？","那些正經八百的凡塵女人哪有九尾狐銷魂？夫君再敢往別殿跑，奴家就把你鎖在鹿臺床頭日夜折騰！"],"neu":["竟敢把凰戒賞給別人戴？夫君膽子越發大了嘛，等著看本姑娘今晚怎麼收拾你！","又迎新人進門啦？咯咯，但願她心臟夠硬，別被奴家的狐火與毒蛇坑嚇瘋才好。"],"crown":"咯咯，把后璽與凰戒交給一隻亡國九尾狐，夫君可真是瘋得合我胃口！放心，有本姑娘壓著，這後宮沒人敢造反～","otherMain":"凰戒那種冷冰冰的死物誰愛戴誰戴去，只要夫君夜夜離不開本姑娘這張床就夠啦。","calm":["哎呀，為這點雞毛蒜皮吵得面紅耳赤，長了皺紋多難看？省點力氣去討好夫君罷，誰再嚎，明早我就扣光她的月例喔。","這點小算計在青丘老祖宗面前簡直像孩童過家家呢。各退一步，本主母請你們喝杯花釀，這事就掀過去啦。"],"preg":"咦……夫君，本姑娘胞宮裡居然結了你的種！（雙手覆上微隆小腹妖冶嬌笑）嘻嘻，這下以後多了一隻小狐狸幫我盯死你囉！","birth":"（產後雪膚微紅、豐乳飽滿，抱著嬰兒眼波瀲灩）快瞧這孩子靈動狡黠的眼睛，簡直跟本姑娘一個模子刻出來的！夫君，奴家愛死咱們的小狐狸了！","kidWen":"多讀陰謀詭計才聰明，將來把外頭那幫蠢蛋對手全耍得團團轉！","kidWu":"好身手！誰敢惹你不痛快，直接往死裡揍，娘親用狐火替你善後！","jealous":"她會貼在你頸側像小獸般嗅聞別人的體香，眯起琥珀色妖瞳壞笑著用九尾把你捆在榻上逼供，半夜再放幾團狐火與毒蛇去嚇瘋情敵。"},"xiaji":{"ev":[{"t":"後宮風聲","d":"夏姬在禁苑漫步時偶遇幾名前朝大夫，僅憑一個回眸輕撩薄紗的媚笑，便害兩位大人當場為了爭搶替她提裙而拔劍相向。","c":[["私下敲打她收斂些，莫把前朝攪得烏煙瘴氣",null],["大笑縱容由她去，順勢看前朝男人出醜",null]]}],"visit":["（剛出花露浴池，濕漉漉長髮垂在豐滿雪乳前，玉臂勾住你脖頸）夫君總算來啦～奴家正缺個陽氣足、懂憐香惜玉的男人暖床呢。"],"neu":["這座城裡的男人越發帶勁了，日日都有新鮮醋味與血案可以配酒。"],"crown":"（嬌笑套上凰戒、接過后璽）讓春秋第一禍水執掌六宮？哈哈，天運者你膽子真肥——不怕我把這座燈塔也玩成第二個陳國嗎？","otherMain":"{mother}當主母正好，省得奴家費神管那些枯燥帳冊，專心把滿城男人的魂勾走便夠啦！","calm":["只要這城裡還有男人為了奴家發瘋流血，日子便永遠無趣不了。"],"preg":"（指尖輕輕劃過微隆小腹，眼波流轉藏著極度危險的笑意）哎呀，胞宮竟結了珠……夫君猜猜，這孩子生下來會長得像你，還是像哪位常翻牆進株林暖閣的大人呢？","birth":"（產後肌膚竟愈發光潤如玉，懷抱嬰兒露出深沉魅笑）這小臉蛋生得真勾人，將來定是個傾倒眾生的小禍水呢。","kidWen":"學什麼迂腐大道理？學會一眼看穿人心與色慾，天下便沒人騙得了你。","kidWu":"把武藝練狠些，免得日後像娘親從前一樣，被這群野蠻男人當成戰利品搶來搶去。"},"liji":{"ev":[{"t":"後宮風聲","d":"驪姬在茶會上柔聲極力誇讚某位失勢妃嬪「賢德大度、連外朝官員皆讚不絕口」，三言兩語便成功引得主母與諸妃對那人起疑排擠。","c":[["私下敲打她收斂些，莫用捧殺挑撥是非",null],["冷笑縱容由她去攪動內廷",null]]}],"visit":["（立刻溫婉起身奉茶，柔聲細語）夫君批文辛苦了，快坐下歇歇，妾身正有幾樁前朝異動想悄悄稟報您呢。"],"neu":["近來後宮看似風平浪靜，實則暗流翻湧，妾身已替夫君記下幾筆要命的帳。"],"crown":"（溫婉跪拜套上凰戒，起身瞬間眼底寒光一閃）妾身必不負夫君所託，將這六宮裡每一條懷有二心的毒蟲，都「溫柔」地清理乾淨。","otherMain":"{mother}姐姐德高望重，妾身自當敬重——只是姐姐手握大權又甚得外朝擁戴，夫君可得多留個心眼呢。","calm":["風平浪靜的表象底下，才最適合織一張滴水不漏的殺網。"],"preg":"（溫柔撫過微隆小腹，眼底閃過深沉狂喜）這孩子來得正是時候……往後這座燈塔的繼承權，絕不能落進旁人骨血手裡！","birth":"（輕哄懷中嬰兒，語氣卻冷得像鐵）好孩子，娘親一定會像當年對付申生與重耳一樣，替你把前頭所有礙事的兄長與忠臣全清乾淨。","kidWen":"好好讀史書與縱橫權謀。記住，幾滴眼淚與幾句好話，往往比千軍萬馬更能殺人於無形。","kidWu":"練點防身武藝也好，但真正的贏家，永遠是讓別人替自己沾血、自己坐收漁利。"}},"pet":{"jiananfeng":[{"t":"惡犬咬人","d":"賈南風在椒房殿庭院養了一頭兇惡黑獒，今日竟當眾撲倒撕咬了一名不慎多看她眉間贅瘤一眼的小宮婢，血濺石階。","c":[["大笑誇這黑獒夠兇夠忠心，賞塊生肉",null],["嚴斥她縱犬咬人，喝令把惡犬鎖進鐵籠",null]]},{"t":"拔羽白鳥","d":"賈南風嫌籠中畫眉鳴聲太清脆刺耳，竟面帶冷笑將鳥捉出來，一根一根活生生拔光了牠的翅羽與尾羽，任牠在血水裡撲騰。","c":[["冷眼旁觀，順手遞上一盞烈酒給她壓驚",null],["一把奪過血淋淋的鳥籠，斥責她太過殘虐",null]]}],"daji":[{"t":"狐火烤肉大會","d":"妲己嘴饞難耐，赤足溜進書房勾住你的衣帶撒嬌，討要大批肥肉烈酒讓她用青丘狐火開一場通宵狂歡烤肉宴。","c":[["寵著這隻妖狐，大方撥糧讓全營跟著狂歡一夜",null],["只賞她一人份炙肉，嚴禁她在營中胡亂放火",null]]},{"t":"戲弄敵探","d":"妲己嗅出城中混進兩名敵對勢力的細作，舔了舔猩紅嘴唇請命把人交給她帶回鹿臺暗室「好好玩弄審問」。","c":[["交給她施展媚術酷刑套出敵營機密",null],["按軍法交由正統刑堂審問，不准她私下虐殺",null]]}],"xiaji":[{"t":"九色靈狐","d":"夏姬在暖閣養了一隻極通人性的雪白靈狐，每逢男臣經過窗外，靈狐便跟著她一塊勾魂媚笑。","c":[["大笑將她與白狐一併攬進懷裡揉弄",null],["板臉命她把靈狐鎖進偏院少出門招搖",null]]},{"t":"爭鬥錦鯉","d":"夏姬往池裡丟下一片沾著她體香的花瓣，掩唇笑看幾條雄錦鯉為了爭食互相撞得鱗破血流。","c":[["湊近她耳畔低笑「天下男人都跟這池裡的魚一樣蠢」",null],["搖頭嘆她總愛看旁人爭得你死我活",null]]}],"liji":[{"t":"籠中白兔","d":"驪姬表面溫柔地拿青草餵著一隻雪白兔子，背地裡卻悄悄往草葉裡滴入毒汁，冷眼試測新配慢毒的發作時辰。","c":[["看穿她的毒辣心思，卻笑誇她細心周密",null],["冷聲警告她絕不許把這套毒術帶進後宮",null]]},{"t":"聽風畫眉","d":"驪姬在偏院養了一對極機靈的信鴿，柔聲說是「替夫君盯著前朝忠臣私下往來用的」。","c":[["點頭默許她暗中監控滿朝文武",null],["命她即刻放生信鴿、嚴禁插手前朝",null]]}]},"cq":{"jiananfeng":{"tun":"屯田？叫那群泥腿子多幹活少吃米，誰敢偷懶藏糧直接夷三族！","qing":"清查流民正好順手把城裡嚼舌根的清流酸儒全鎖進大牢審一遍！","qiang":"強兵自然要練——而且這支新軍的虎符必須交進椒房殿保管！","kuang":"開礦採石把反對本宮的文官家眷全押去挖，既省軍餉又解氣！","ji":"祭天求神有什麼鳥用？砍幾個政敵腦袋祭旗比三牲六畜管用十倍！","shou":"縮在城牆裡挨打太窩囊，不如先派死士把敵酋老小全暗殺乾淨！"},"daji":{"tun":"沒烈酒沒肥肉本姑娘可活不下去，快下屯田令種糧釀酒呀！","qing":"讓城民過得快活熱鬧些，燈火越亮，奴家玩起來才越帶勁嘛～","qiang":"多練些兇殘猛兵，把城外那群掃興的敵對勢力全撕碎！","kuang":"加緊採石伐木多蓋幾座金碧輝煌的高臺，像朝歌鹿臺那樣才夠氣派！","ji":"祭告星盤匯聚靈氣，對本姑娘滋養九尾妖力大有好處喔～","shou":"把城牆砌厚些，別讓那些臭烘烘的黑霧怪物吵著本姑娘睡午覺！"},"xiaji":{"tun":"種穀子多乏味呀，多撥幾畝肥田種釀花酒、製駐顏奇香的珍草罷！","qing":"城外流民裡藏著不少落魄貴冑與精壯武夫呢，全收進來讓奴家挑挑看！","qiang":"練兵何必整天甩鞭子？誰殺敵最多賞奴家一杯交杯酒，保管三軍個個拚命！","kuang":"多採些亮閃閃的寶石與暖玉，奴家株林暖閣還缺幾件點綴呢。","ji":"星盤大祭讓奴家披赤紗領舞罷，保準連天上神祇看了都動凡心～","shou":"縮在城裡挨打多蠢？奴家往城樓上一站笑一笑，敵軍主帥與副將自己就先拔刀火拚啦！"},"liji":{"tun":"屯田固本甚好，只是管糧官吏握著全城命脈，夫君可得安插自己人暗中盯死。","qing":"流民裡難免混進敵國細作，不如交給妾身的驪戎密探逐一「細細甄別」罷。","qiang":"強兵固然要緊，可領兵大將若威望蓋過君主……夫君萬萬要留個制衡後手呀。","kuang":"礦脈充盈，正好拿來厚賞真正對夫君死心塌地的親信耳目。","ji":"大祭胙肉關乎社稷安危，旁人經手妾身實在懸心，還是交給妾身親自替夫君驗看罷。","shou":"守城必先守心——城外黑霧不難擋，最毒的是城內忠良暗生異心呢。"}},"wander":{"jiananfeng":"（拎著沾滿黑血的短戟冷笑）這荒原上哪個城主好拿捏、玉璽又夠重？本宮去借來玩玩！","daji":"（赤足踏過荒原碎骨，九尾虛影在黑霧裡閃爍微光）嗅嗅……好醇厚的星盤氣息，還混著一股迷人的帝王野心呢～咯咯，天運者，本姑娘妲己跟你走囉！","xiaji":"（赤紗隨荒原狂風翻飛，露出修長白腿與豐盈曲線）咯咯，前頭那座營寨的將軍盯著奴家的眼神好燙呀，今晚又有好戲看囉～","liji":"（素帕拭淚輕嘆，眉眼楚楚動人）這亂世之中，哪位英明雄主身側還缺一朵最善解人意的解語花呢？"},"cap":{"jiananfeng":[null,null,null,"成交！醜話說在前頭，誰敢在背後笑我醜，本宮照樣一戟砸穿他的腦殼！"],"daji":[null,null,null,"咯咯，青丘九尾徹底甦醒囉～這回不燒朝歌，只把擋在夫君面前的萬魔全燒成焦灰！"],"xiaji":[null,null,null,"說好囉，哪天前朝諸將為了搶奴家拔刀自相殘殺，可別把亡國黑鍋扣在我頭上！"],"liji":[null,null,null,"（垂眸淺笑，眼底蛇蠍寒芒一閃）夫君放心，凡敢對您生出半點二心之人，妾身絕不放過。"]},"hev24":{"jiananfeng":{"ev":[{"t":"後宮風波","k":null,"d":"賈南風疑心{b}背地裡嘲笑她矮黑長瘤，竟率東宮死士堵在{b}殿門前砸光所有瓷器與銅鏡，揮著短戟揚言要劃爛{b}那張狐媚臉。","c":[["親身出面攔下她並奪去短戟",null],["冷眼視而不見，任由她發洩戾氣",null],["各打五十大板強行壓下風波",null]],"after":null}],"cold3":"連著三旬不進本宮殿門？好得很！今晚本宮便命閹豎用大木箱多抬兩個城南白皙少年進暖閣解悶，看誰先氣炸肺！","crownR":"后冠與凰戒終於落回本宮手裡！從今日起，後宮順我者生、逆我者死，誰敢懷孕爭寵先問過我的短戟！"},"daji":{"ev":[{"t":"狐火嫁禍","k":null,"d":"妲己嫉恨{b}近日搶了她的風頭，半夜悄悄把一撮雪白狐毛與黑霧灰燼塞進{b}枕底，隔日一早便拉著你「捉妖」，嬌聲驚叫：「呀！{b}妹妹榻上怎麼這般濃的妖邪味，莫不是被畫皮鬼鑽進身子了？」","c":[["笑著捏住妲己微動的狐耳拆穿這隻小妖精，當場替{b}洗清冤屈",null],["明知是她栽贓卻縱容她胡鬧，順勢把她扛回暖閣「嚴加審問」",null],["罰妲己親自向{b}賠禮，並沒收她私藏的西域烈酒充公",null]],"after":"咯咯，夫君這雙眼睛真毒，連青丘老祖宗的把戲都瞞不過你～誰讓她整天霸著你，本姑娘手癢嘛！"},{"t":"串通逃課","k":null,"d":"今日原定召開後宮宮規例會，妲己卻嫌枯燥得發慌，竟拉著{b}串通裝病「雙雙染寒」騙過主母，結果被你撞見兩人正躲在禁苑假山後拿狐火偷烤整條肥羊腿、喝得衣襟半敞滿臉潮紅。","c":[["笑罵一句「兩隻小饞貓」，乾脆坐下與她們大口吃肉喝酒",null],["沒收酒肉罰兩人回殿抄寫宮規，絕不姑息欺瞞",null]],"after":"夫君也覺得炙羊腿比死板宮規香十倍罷？下回偷溜，奴家一定先拉上夫君一起！"},{"t":"拉幫圍獵","k":null,"d":"妲己極度厭惡正氣凜然的{c}整日勸你遠離美色、勤理政務，竟笑盈盈拉攏同樣受冷落的{b}聯手——兩人一左一右堵死書房門，一個軟語餵酒、一個以九尾纏住你的手腕，硬把{c}晾在殿外寒風裡。","c":[["抵擋不住妖狐夾擊，大笑留下來享齊人之福",null],["撥開狐尾請{c}進殿商議正事，冷落兩人的小手段",null]],"after":"夫君整天聽{c}念經多掃興呀～人生苦短，在這黑霧圍城裡，當然要及時行樂才對得起這副皮囊嘛！"}],"cold3":"一次、兩次、三次……夫君身上這股別人的味道濃得教本姑娘想放火燒殿囉。今晚你自己挑——乖乖脫衣上我的榻，還是看奴家把那座院子點成第二個鹿臺？","crownR":"咯咯咯，拜見新主母囉～把凰戒交給一隻九尾妖狐，夫君可真會玩！各位妹妹放心，只要你們別搶我的男人，本姑娘保你們日日有酒池肉林喔～"},"xiaji":{"ev":[{"t":"後宮風波","k":null,"d":"夏姬在城頭散步時對值勤偏將回眸輕撩衣袖一笑，害兩名年輕將領當場爭風吃醋拔刀互砍、血濺城樓。","c":[["親身出面喝止並將她拉回內廷",null],["冷眼視而不見，任由軍法處置",null],["各打五十大板強行壓下醜聞",null]],"after":null}],"cold3":"三旬不碰奴家這副身子？那今晚奴家只好邀朝堂上那兩位穿著我赤紅汗衫的大人進株林暖閣共飲囉～","crownR":"春秋第一禍水執掌凰戒！天運者，準備好陪奴家一起把這座孤城玩成第二個陳國罷！"},"liji":{"ev":[{"t":"後宮風波","k":null,"d":"驪姬深夜披著素衣在書房外輕聲啜泣，三言兩語便成功挑起天運者對一位功勳大將的強烈殺心與猜忌。","c":[["親身出面喝止她的挑撥",null],["冷眼視而不見，默許猜忌發酵",null],["各打五十大板強行壓下風波",null]],"after":null}],"cold3":"三旬不踏進晉陽暖閣，看來{b}妹妹在枕邊替夫君吹的風確實管用……無妨，妾身這就修書給優施，商量商量該怎麼替夫君「分憂」。","crownR":"妾身必以最溫柔體貼的手段，把六宮裡所有對夫君懷有二心的人，一個個「體面」地送上黃泉路。"}},"hact":{"jiananfeng":{"討好":["本宮今日替夫君抄了兩戶貪官滿門充實公庫，這份孝心，比那些只會張腿哭嚎的狐狸精實用得多罷？"],"爭權":["前朝與內廷的印信都該歸椒房殿管！誰敢擋路，先問過我手裡這柄短戟！"],"結黨":["東宮舊部、心腹閹豎與太醫令程據全聽本宮號令，這座宮裡沒人動得了我！"],"進讒":["夫君，{b}那賤婢暗中與外臣勾結、圖謀不軌，不如明日便矯旨夷她三族，永絕後患！"],"收買":["拿這箱金餅去買通{b}殿裡的煎藥宮婢，把她的安胎湯換成極烈的墮胎虎狼藥！"],"干政":["那份任免詔書寫得太軟弱，本宮已替夫君改擬成滿門抄斬並蓋上大印了！"],"祈福":["求神拜佛不如見血！拉兩個礙眼的宮婢去祭旗，老天爺自然保佑本宮！"],"調停":["嚎什麼嚎？再敢在宮道上吵得本宮腦仁疼，我把你們兩個一併塞進枯井裡活埋！"]},"daji":{"討好":["夫君～本姑娘剛用青丘秘法溫好這壇催情狐花釀，今晚別看那些臭地圖了，來帳裡陪奴家玩嘛！","瞧奴家新裁的九尾赤紗裙透不透呀？只要夫君點頭，今晚整座暖閣只點紅燭喔～"],"爭權":["這後宮冷清得像墳墓，主母也太沒趣啦！把宴飲與採買全交給本姑娘，保證日日笙歌不斷！","哼，既然夫君最迷戀我，這後宮規矩當然該聽本姑娘的！"],"結黨":["跟著青丘老祖宗混，保準讓妳吃香喝辣、把那幫假正經的女人全氣哭！","咱倆聯手把夫君的魂全勾過來，到時候這座城想怎麼荒唐就怎麼荒唐～"],"進讒":["夫君，{b}成天板著死人臉訓這訓那，連你多飲一盞酒都要管，你娶的是美人還是老宮媼呀？","咯咯，奴家方才嗅見{b}身上好濃一股怨氣呢，她心裡準在罵夫君昏庸偏心喔～"],"收買":["這把金豆子與烈酒拿去分吧！誰把別殿的秘辛告訴本姑娘，日日都有重賞！","管事真機靈～這顆夜明珠賞你了，往後城裡最肥嫩的肉與鮮果，記得頭一個送進鹿臺暖閣！"],"干政":["夫君，那個整天上書罵奴家是亡國妖孽的老酸儒，明早把他貶去刷馬廄好不好嘛～","打仗何必傻傻硬拚？讓本姑娘挑幾個機靈斥候傳幾招青丘迷魂陣，包準敵軍自相殘殺！"],"祈福":["星盤呀星盤，多降點靈氣給夫君罷，等他成了歸墟霸主，本姑娘就能起一座更奢靡的鹿臺囉！","狐火映星輝，願夫君永遠狂傲迷人，也永遠戒不掉本姑娘這副妖身！"],"調停":["哎呀別吵啦，吵得本姑娘耳根發疼！一人賞一壇烈酒，誰再嚎我就用狐火烤焦她的裙襬喔～","都是伺候同一個男人的姐妹，把力氣省下來勾引夫君不是更划算嗎？"]},"xiaji":{"討好":["夫君今夜宿在株林暖閣罷，新煉的駐顏香配奴家的採補秘術，比任何大補湯都讓你精神百倍喔～"],"爭權":["奴家不稀罕冷冰冰的官印，奴家只要把全城最有權勢那群男人的三魂七魄全勾在裙下就夠啦！"],"結黨":["前朝兵部、戶部那幾位大人全聽奴家一句枕邊軟語，這算不算結黨呀？咯咯。"],"進讒":["夫君，{b}那副死氣沉沉的木頭樣看著真掃興，連外邦使節都私下笑她配不上您呢。"],"收買":["不用花國庫半兩銀子，奴家脫兩件沾著體香的赤紅汗衫賞出去，自有大把男人搶著替我賣命！"],"干政":["孔大夫與儀大夫今早又為了奴家在殿上吵得拔劍了，夫君快來替奴家評評理嘛～"],"祈福":["只願奴家這副雪膚花容永不衰老、花戶緊緻如初，永遠教全天下男人為我發瘋喪命！"],"調停":["男人之間哪有解不開的仇？全請進奴家暖閣喝兩杯合歡酒，什麼刀劍都軟下來囉～"]},"liji":{"討好":["夫君操勞軍國，妾身親溫了安神茶——對了，方才無意聽聞幾位重臣私下過從甚密呢。"],"爭權":["妾身不慕什麼尊榮封號，只要夫君夜深枕畔肯聽妾身說幾句體己話便足夠了。"],"結黨":["暗中聯絡心腹樂師優施與驪戎密探，將前朝後宮的把柄全數攥進袖底。"],"進讒":["（淚落如珠、泣不成聲）{b}妹妹與那位將軍寬厚仁慈、甚得民心，妾身真怕他們尾大不掉……不如夫君早些賜死妾身罷！"],"收買":["這包無色無味的慢毒拿去，明日大祭前悄悄抹在{b}呈上的祭祀胙肉裡，做得乾淨俐落些。"],"干政":["那位大將功高震主，妾身雖信他赤誠，可萬一哪天他被部下擁立逼宮可如何是好呀……"],"祈福":["祈求夫君永遠只信驪姬一人，將那些戴著忠臣面具的笑面虎盡數看透斬絕。"],"調停":["（溫柔勸和，句句卻往火裡澆油）妹妹莫動氣，許是夫君真的嫌棄姐姐老了才這般偏心妳呢。"]}},"hpow":{"jiananfeng":["這座燈塔的玉璽一半刻著你的名，另一半早歸我賈南風說了算！","誰敢對本宮不敬？莫忘了當年太傅楊駿與他三族老小是怎麼血流成河的！"],"daji":["夫君～現任主母把後宮管得死氣沉沉，連你都懶得踏足了吧？把凰戒摘給本姑娘戴嘛，我保證讓後宮比朝歌鹿臺還銷魂百倍！","凰戒空著多暴殄天物呀！夫君，交給本姑娘，這滿宮上下沒誰敢不服青丘九尾喔～"],"xiaji":["三夫一君一子、一國兩卿——男人越罵我紅顏禍水，就越忍不住飛蛾撲火往我裙下鑽！","只要這世上還有管不住下半身的男人，我夏姬便永遠立於不敗之地。"],"liji":["冷硬刀劍只能殺人，唯有枕邊的眼淚與猜忌，能教君王親手斬絕自己的忠良。","這座城裡誰忠誰奸，從不看戰功大小，只看妾身今晚在夫君耳邊怎麼哭。"]},"hbig":{"jiananfeng":[{"t":"金墉廢后令","k":null,"d":"賈南風深夜偽造手詔，企圖將城中威望最高的主母或太后黨羽全數押入斷水斷糧的金墉冷殿活活餓死，滿朝震怖！","c":[["冷笑默許她徹底清場掌權",null],["當眾撕毀假詔，強硬壓制她的瘋狂",null]],"after":"金墉冷殿斷糧餓死的陰影，從此壓在每位後宮女人心頭。"},{"t":"畫戟逼宮道","k":null,"d":"賈南風聽見兩名宮婢私下議論她面黑長瘤，竟親提長戟在禁苑大開殺戒、當場刺穿宮婢咽喉，連路過的{b}都險些被戟鋒劃破臉頰！","c":[["下令封鎖禁苑消息，親自替她擦淨血跡善後",null],["震怒奪戟，將她重罰禁足三旬",null]],"after":"禁苑石階沖刷了整夜清水，仍散不去那股刺鼻的血腥氣。"},{"t":"箱載少年敗露","k":null,"d":"夜巡宿衛在椒房偏門攔下一口沉重的大木箱，撬開一看竟藏著一名赤身瑟縮的城南俊美少年！少年嚇得當場招認已被賈南風留宿三夜、且先前幾個不合她意者已被毒殺沉井！","c":[["就地處死少年滅口，轉身把她按回玄黑錦榻冷血宣告主權",null],["震怒杖責她並將其打入冷宮反省",null]],"after":"那口沾著脂粉與血跡的大木箱被劈碎燒盡，淫亂滅口的醜聞卻早已傳遍六宮。"}],"daji":[{"t":"鹿臺逼印","k":null,"d":"妲己權勢滔天，竟趁你微醺之際，身後九道雪白狐影張開將暖閣四門封死。她赤足跨坐上你膝頭，雪白雙乳幾乎貼上你胸膛，指尖輕挑你下頜嬌笑：「夫君，外頭{b}和{c}天天喊著要燒死本姑娘呢。今晚不把凰戒賞給我、再將她們二人禁見，本姑娘就不讓你下這張榻囉～」","c":[["被這隻危險妖狐徹底勾住魂魄，大笑答應偏寵於她並禁見{b}",null],["眼神驟冷反手扣緊她手腕，嚴斥她不得妄動凰戒並罰禁見三旬",null],["溫柔吻住她堵上胡鬧紅唇，賜下珍稀珠玉岔開話題",null]],"after":"咯咯，夫君發狠的模樣都這麼銷魂……行罷，凰戒不急，反正你的魂與肉身早晚全歸我！"},{"t":"迷魂毒酒","k":null,"d":"{b}飲下妲己笑盈盈遞去的一杯「青丘花釀」後，竟當場陷入瘋癲幻覺、扯開衣衫又哭又笑大鬧校場，險些撞傷巡邏將士！眾夫人齊聲怒斥妲己下妖毒害人，妲己卻無辜眨眼：「人家不過加了一撮忘憂草讓她快活一下嘛，誰曉得凡人酒量這麼差呀～」","c":[["嚴懲妲己以妖毒害人，下令關押四旬並好言安撫{b}",null],["重責妲己禁見三旬並沒收所有妖酒，急召華佗替{b}解毒",null],["偏袒護短，笑稱只是酒勁太烈醉了，強行壓下此事",null]],"after":"哎呀，見她平日繃得像塊木頭，幫她發洩發洩都不成嗎？夫君真是越發嚴厲啦～"},{"t":"酒池奢靡","k":null,"d":"妲己仗著權勢與獨寵，竟私命工匠在後苑挖池蓄酒、日宰十餘頭肥獸大開肉林狂歡，還強逼素來節儉的{b}跪在池邊替她斟酒。倉吏哭著來報，再由她這麼揮霍，下波霧潮前全城便要斷糧！","c":[["立刻下令填平酒池、罰妲己禁見三旬，並向{b}與眾人賠禮",null],["忍痛將她關押三旬殺雞儆猴，嚴禁後宮奢靡浪費",null],["縱容到底，大笑著扯開外衣跳進酒池陪她荒唐整夜",null]],"after":"哼，小氣鬼！當年殷壽都沒攔著本姑娘築酒池肉林呢……好啦，下回只烤兩條羊腿總行了吧？"}],"xiaji":[{"t":"朝堂雙衫案","k":null,"d":"早朝金殿之上，兩名實權重臣竟同時扯開朝服領口，露出一模一樣的赤紅絲綢貼身衵服互相炫耀——全是夏姬昨夜親手脫下賞賜的！","c":[["盛怒當殿斬殺兩名大夫，將夏姬打入冷宮嚴懲",null],["狂笑斥退痛哭的清流，當眾討要夏姬的新汗衫一起沉淪",null]],"after":"兩件沾著體香的赤紅衵服，讓這座朝堂徹底淪為春秋陳國的翻版。"},{"t":"雙將火拚株林","k":null,"d":"兩名迷戀夏姬的守城大將為爭奪她一條染著花露香的紅絲帕，竟在軍營裡拔刀互砍、釀成兵亂，北門防務險些徹底癱瘓！","c":[["鐵血處決兩名失控大將，嚴令禁足夏姬三旬",null],["大笑稱「自古美人配英雄」，草草罰酒三杯了事",null]],"after":"夏姬連一柄小刀都沒碰，守城精銳卻已折損大半。"},{"t":"敵酋重金索姬","k":null,"d":"城外強敵陳兵三十里，竟送來國書指名「交出絕代尤物夏姬即刻退兵並獻糧萬石」，滿朝清流跪地齊呼獻姬保城！","c":[["拔劍怒斬來使，率軍出城血戰死保夏姬",null],["冷酷將她廢為庶人送出城門，換取停戰與萬石軍糧",null]],"after":"無論留下還是獻出，夏姬二字註定永遠與兵禍鮮血相伴。"}],"liji":[{"t":"毒肉嫁禍大案","k":null,"d":"大祭禮畢，{b}呈上的祭祀胙肉竟驗出見血封喉的劇毒、餵犬即斃！驪姬當場花容失色跪地痛哭，將「毒殺君王」的死罪死死釘在{b}頭上。","c":[["徹底中計！震怒將無辜的{b}打入冷宮嚴懲",null],["不動聲色暗查出是驪姬中途下毒，當殿拆穿重罰！",null]],"after":"一塊染毒祭肉，讓整個後宮徹骨領教了溫柔毒蛇的致命獠牙。"},{"t":"夜半泣逼走忠良","k":null,"d":"驪姬連著三夜在你懷裡「夜半而泣」，反覆誇讚兩員核心大將寬厚愛民、恐生不臣之心，逼得兩位忠將察覺殺機連夜棄城流亡荒原！","c":[["聽信驪姬下令通緝出逃忠將並抄沒家產",null],["急派快馬親筆追回大將並嚴厲警告驪姬",null]],"after":"昔年晉國重耳、夷吾倉皇出奔的悲劇，幾乎在這座燈塔重演。"},{"t":"優施密謀曝光","k":null,"d":"暗衛搜出驪姬心腹樂師優施的密信，裡頭不但詳寫如何以「夜半而泣」操控你清洗忠良，更露骨寫著兩人暗通款曲的私情！","c":[["冷笑燒毀密信「既已成了共犯，這齣戲便繼續演下去」",null],["當場斬殺優施，將驪姬打入冷宮嚴懲",null]],"after":"當猜忌的毒根已經扎進骨髓，就算撕穿謊言，你也再難信任何人。"}]},"hstat":{"jiananfeng":{"jail":"把本宮鎖進大牢？等著瞧我東宮死士今晚怎麼把這破牢房掀翻！","ban":"禁足？你關得住本宮的腿，關不住我往外遞的假詔書與毒藥！","spoil":"哼，算你這男人有眼光，沒被那些光長皮囊的蠢貨迷瞎雙眼！","inj":"這點皮肉見血算什麼？傷了本宮的人，我必拿她全族腦袋來填！","exileGo":"流放本宮？好啊，我倒要看看沒了我這把惡刀鎮場，你這座破城幾天就會亂成一鍋粥！","exileBack":"我賈南風又活著爬回來了！先前踩過本宮的蠢貨，統統洗乾淨脖子等著！","exec":"賜我喝金屑酒？哈哈哈哈，八王之亂馬上就來，我在黃泉路上等著看你國破家亡！","cleared":"本宮行得正坐得端——就算真是我幹的，滿朝文武又能奈我何？","otherExec":"（拍手陰笑）殺得好！少一個礙眼狐狸精，這座後宮的空氣都清淨三分！","ally":"跟本宮結盟算妳識相，只要乖乖替我咬死對頭，榮華富貴少不了妳的。"},"daji":{"jail":"嘻嘻，把一隻九尾妖狐鎖進鐵籠，夫君就不怕我半夜咬斷鐵鏈、鑽進你被窩裡咬你一口嗎？","ban":"不准見面？好呀，本姑娘就在殿裡放狐火烤肥肉喝酒，香死外頭值夜的宿衛！","spoil":"全城最烈的酒、最嫩的肉、最亮的寶珠，原本就該全堆進本姑娘的鹿臺暖閣嘛～","inj":"嘶……居然刮傷本姑娘細嫩皮肉！夫君快替我吹吹，再把傷我那賤人丟進蠆盆！","exileGo":"哈哈，逐我出城？行呀，等本姑娘在荒原裡勾來一群妖魔殺回來，夫君別哭著求饒喔！","exileBack":"驚不驚喜呀夫君？荒原裡那群野男人全沒你帶勁，本姑娘決定回來繼續纏死你囉～","exec":"咯咯咯……女媧要殺我，你也要殺我。記清楚，這輩子你再找不著比我更銷魂的妖精了！","cleared":"哼，白關了本姑娘這麼久！今晚你不陪我灌醉鬧到天亮，這事沒完！","otherExec":"（粉舌舔過紅唇，妖冶一笑）哎呀，又少了一個分走夫君的蠢貨，真可惜呢～","ally":"跟本姑娘聯手，保證教妳嚐嚐把整座後宮踩在腳底下玩弄的滋味喔～","betrayed":"敢背叛青丘九尾狐？嘻嘻，往後每一夜的噩夢，本姑娘全替妳包了！","win":"咯咯，這場好戲真過癮！下一個輪到哪位姐姐陪本姑娘玩呢？"},"xiaji":{"jail":"大牢裡那幾個獄卒盯著奴家胸乳咽口水的模樣好燙呀，只怕今晚這牢房就要變成奴家的新歡場囉～","ban":"禁足暖閣？無妨，半夜會翻牆爬窗進來替奴家解悶的將軍多得排隊呢！","spoil":"夫君這般迷戀奴家這副身子，小心哪天也像陳靈公一樣把這座城玩亡囉～","inj":"哎呀，劃傷了奴家這身勝雪嫩肉，全城不知有多少大人要心疼得發瘋呢！","exileGo":"逐奴家出城？城外敵酋早就備好八抬大轎與萬兩黃金等著迎娶夏姬啦！","exileBack":"咯咯，奴家又回來囉！前朝那幾位老相好聽說都激動得坐不住了吧？","exec":"殺了我就能教男人不再發情互砍嗎？蠢貨……下輩子咱們換個國繼續亡罷！","cleared":"奴家從頭到尾連把匕首都沒碰，是男人自己發瘋互殺，我本來就清白得很嘛～","otherExec":"（掩唇輕嘆）真是可憐呢，不懂怎麼拿捏男人下身的女人，死得最快。","ally":"好妹妹，跟著姐姐學學怎麼靠一條赤紅汗衫讓男人互相殘殺，保證一輩子吃香喝辣！"},"liji":{"jail":"（柔弱垂淚）夫君竟信了奸佞讒言將妾身關進大牢……但願沒我提醒，夫君莫遭身邊人毒手。","ban":"禁足無妨，只可惜外頭那些野心勃勃的重臣，這幾日怕是要趁機坐大了。","spoil":"夫君如此信重妾身，驪姬便安心了——對了，關於{b}妹妹的事，妾身還有一句話想悄悄提醒……","inj":"（咬唇含淚）這點傷不算什麼，定是哪位忌恨妾身的姐妹暗下毒手，夫君千萬別去查她呀。","exileGo":"妾身甘願遠走荒原，只盼來日群臣逼宮之時，夫君別後悔今日沒聽驪姬一句勸。","exileBack":"（溫婉福身，眼底寒冰一閃）謝夫君還妾身清白……這回，定教那些小人連根絕滅。","exec":"瞧瞧你這雙沾滿忠良冤血的手罷，是我驪姬親手把你雕琢成如今這副多疑暴君的！黃泉路上等你陪我。","cleared":"夫君明察秋毫！只是這回栽贓妾身的幕後主使，可絕不能輕饒呢。","otherExec":"（以素帕掩面低泣，帕後卻勾起冰冷毒笑）真可惜……她本該早些懂事的。","ally":"好姐妹，你我明暗互相照應，這後宮裡哪個礙眼，我替妳去夫君枕邊哭一哭便是。"}},"fac26":{"mem":{"jiananfeng":[null,"以矯詔夷族、手擲短戟墮胎與箱載少年淫樂聞名青史的西晉惡后，順我者生、逆我者滿門絕滅。"],"daji":[null,"青丘九尾天狐最擅枕邊魅術與惑主弄權，唯有緊握君王獨寵與奢靡特權，方能肆意焚城作樂。"],"xiaji":[null,"憑不老駐顏奇術與貼身赤紅衵服攪動滿朝文武與敵酋自相殘殺的春秋第一禍水。"],"liji":[null,"表面溫婉垂淚、暗中勾結樂師優施與驪戎密探，以夜半而泣與毒肉嫁禍清洗忠良的頂級毒蛇。"]}},"blood":{"conf":{"jiananfeng":["（冷笑逼近你，眼底滿是挑釁）懷疑這孩子不是你的種？呵，就算真是本宮跟太醫令程據或城南小吏懷上的，養在你名下你還敢當眾嚷嚷自己戴綠帽不成？","沒錯，不是你的種又如何！只要從本宮胞宮裡爬出來、流著賈家狠血，將來這座城照樣姓賈！"],"daji":["（柳眉倒豎，雪白尾尖竄起幽藍狐火）哪個活膩的長舌婦，敢編排咱們的小狐狸崽？夫君別攔，奴家這就去把她頭髮燒光！","（罕見收起所有嬉笑，九尾低垂卻眼神赤裸）……終究被夫君瞧破了呢。要殺要剮隨你便，只是這小傢伙才剛會喊爹，別嚇壞他。"],"xiaji":["（掩唇咯咯嬌笑）夫君問奴家腹中骨血親爹是誰呀？昨晚翻牆的侍郎、前晚留宿的偏將，還是夫君自己……奴家也數不清了呢～","管他是不是你的種，能承襲我夏姬這副絕世皮囊的血脈，養在你名下是你佔了大便宜！"],"liji":["（語氣溫柔卻字字誅心）夫君真要驗這孩子的血脈嗎？你為了信我「夜半而泣」，連最赤誠的大將都殺了，如今難道敢當眾承認自己替優施養兒子？","就算這孩子流的是優施與驪戎故人的血，只要你認下，他便是這座燈塔未來的儲君——咱們早是一條繩上的共犯了，夫君。"]}},"agenda":{"jiananfeng":{"私心":["只要把中樞兵權與六宮生殺全攥死在掌心，誰敢廢我，我便拖著整座城一塊燒成灰！"],"歸來被俘":["（雖被鐵鏈鎖回大殿，依舊滿眼戾氣毒笑）落回你手裡又怎樣？要殺便殺，想看本宮跪地求饒悔改？下輩子罷！"]},"daji":{"歸來被俘":["又落回夫君掌心啦。繩子勒得人家胸乳發緊、生疼得很——今晚你是打算在暗牢裡親自審問奴家嗎？"]},"xiaji":{"私心":["在無數權貴男人的瘋狂搶奪與血火中永享極致歡愉與青春，絕不為任何一個男人守貞！"],"歸來被俘":["（媚眼如絲地打量你）又把奴家搶回來啦？夫君這般離不開我，小心這座城也步當年陳國後塵喔！"]},"liji":{"私心":["憑眼淚與毒肉操控帝王猜忌心，斬盡所有阻礙自己與所出登頂的忠良與繼承人！"],"歸來被俘":["（楚楚可憐地跪地抬眸，眼底卻藏著毒蛇冷笑）夫君終究還是把我捉回來了……看來你早就戒不掉這把溫柔毒刀了呢。"]}},"ownx":{"jiananfeng":[{"k":null,"t":"偷蓋玉璽","d":"你查覺賈南風趁你熟睡偷盜玉璽，私自蓋了三道抄家滅門與調動禁軍的假旨！","c":[["將計就計默認假旨，順手吞下抄家得來的金山銀海",null],["雷霆追回假旨，當眾斥責她偷璽越權",null]],"after":"枕邊人的手，永遠比你以為的伸得更深、沾的血更多。"},{"k":null,"t":"暗通外戚","d":"賈南風背著你將城中兩支精銳宿衛的換防密符偷偷塞給了賈氏黨羽。","c":[["不動聲色撤換校尉，冷笑敲打她安分些",null],["乾脆賜予她部分兵權，換她死心塌地替你清殺政敵",null]],"after":"兵權交錯之間，這座城究竟姓誰已越發模糊。"},{"k":null,"t":"嘲諷懦弱","d":"見你對降將心軟留了一命，賈南風竟當著滿殿宿衛大笑譏諷你優柔寡斷、活脫脫就是第二個白癡司馬衷。","c":[["冷笑一把掐住她下頜壓倒案上，強硬鎮服這頭惡后",null],["甩袖離去懶得與她口舌爭鋒",null]],"after":"她骨子裡從來只服比她更冷酷的男人。"},{"k":null,"t":"拒不問安","d":"賈南風連著數日拒見天運者與主母，在椒房殿大擺酷刑血酒宴，公然自稱中樞之主。","c":[["親率宿衛一腳踹開殿門強硬立威",null],["笑著提一壇烈酒走進殿裡與她共飲縱容到底",null]],"after":"西晉惡后的驕橫戾氣，從不曾為任何人收斂半分。"}],"daji":[{"k":null,"t":"託病私會","d":"妲己連著三旬謊稱「妖元受損、臥病不起」婉拒夜訪，暗衛卻在荒原霧緣撞見她身著火紅薄裙完好無損，正與敵派妖祭司把酒調笑、暗渡城防情報！原來她嫌城裡規矩枯燥，竟背著你勾結外敵尋樂！","c":[["雷霆震怒，當場拿下通敵妖狐關押五旬、徹底封鎖妖力",null],["念及往日銷魂纏綿不忍殺她，下令流放荒原十二旬",null],["明知她背叛卻依舊迷戀這份致命妖魅，竟私下壓住消息",null],["妖狐通敵禍亂絕不可留，鐵血下令當場處死妲己",null]],"after":"呵呵……被夫君捉個正著呢～誰教城裡整天悶得像棺材，外頭那妖祭司比你朝堂那群酸儒好玩多啦。"},{"k":null,"t":"妖火要挾","d":"你不肯撤銷清流派對她的彈劾，妲己竟深夜放出九道青丘狐火圍死城中大糧倉，赤足坐在倉頂晃著雪白長腿嬌笑：「夫君，你猜這把火落下去，全城軍糧會不會瞬間成灰？快把彈劾章疏燒了、再把這旬酒肉全賞給奴家，我便收火喔～」","c":[["投鼠忌器被迫妥協，當場燒毀章疏並撥糧哄這隻瘋狐狸下來",null],["冷笑命弓弩手瞄準屋頂強硬逼她收火，隨即下令關押四旬",null],["獨自躍上倉頂一把將她撲倒制伏，罰禁見三旬嚴加管教",null],["絕不容忍毀城要挾，直接下令流放荒原",null]],"after":"呵呵，夫君躍上倉頂按住奴家的姿態可真兇猛。我早就知道你捨不得要我的命。"},{"k":null,"t":"當眾戲君","d":"慶功夜宴上，微醺的妲己竟當著滿堂將士直接跨坐到你君座扶手上，拿金爵輕叩你胸膛嬌聲大笑：「諸位將軍瞧瞧呀，外頭都說天運者威風凜凜，其實昨夜在奴家帳裡還不是被九尾纏得喘不過氣、百依百順呢～」滿堂文武面色鐵青。","c":[["反手將她拽進懷裡霸道吻住堵上妖嘴，大笑「英雄難過美人關」化解尷尬",null],["眼神驟冷一把推開她，斥責她醉酒失體並罰禁見三旬",null],["盛怒喝令宿衛當場押入暗牢關押三旬，重立君威",null]],"after":"哎呀，不過說了兩句房中實話嘛，夫君臉皮怎麼比商王殷壽還薄呀？"},{"k":null,"t":"九尾假死","d":"妲己玩心大起想試試自己在你心裡多重，竟用青丘幻術變出一具焦黑九尾白狐屍骸留在祭壇旁，留下一紙血書「妖力反噬、灰飛煙滅，願夫君莫忘奴家」。等你紅著眼眶撫摸焦屍時，她卻忽然從殿樑倒掛下來笑得花枝亂顫：「哈哈哈哈！夫君你當真替一隻妖狐掉眼淚啦！」","c":[["又氣又笑地將她從樑上扯進懷裡狠狠教訓，罰她今夜不准闔眼",null],["氣極反笑，下令把這隻滿口謊言的妖狐禁見三旬反省",null],["震怒於她竟敢在星盤祭壇演這齣荒唐戲，下令關押三旬",null]],"after":"呵呵……看見你為奴家紅了眼那一瞬，本姑娘心裡可快活得快飛起來了呢。"}],"xiaji":[{"k":null,"t":"採補隱瞞","d":"你查出夏姬近來頻頻召見幾名年輕猛將進偏苑「切磋房中養生術」，實則是藉機四處留情、吸取眾男追捧與精氣。","c":[["冷笑把她鎖進暖閣狠狠折騰教訓一整夜",null],["震怒革除數名武將官職，嚴詞訓斥夏姬不知檢點",null]],"after":"她骨子裡的風流天性，永遠關不進四面高牆之內。"},{"k":null,"t":"密信敵酋","d":"暗衛截獲城外敵酋寫給夏姬的炙熱情書，而夏姬竟也偷偷回贈了對方一條沾著濃郁花露體香的赤紅絲帕！","c":[["當場拆穿罪證，重重杖責並打入冷宮",null],["反手搶回絲帕塞進自己懷裡「妳的貼身物只准給我看」",null]],"after":"對夏姬而言，多留一條退路與多釣一個君主毫無分別。"},{"k":null,"t":"酒間評比男人","d":"夏姬微醺之際竟赤足跨坐案頭，當著你的面咯咯笑著拿你與前朝情夫在床榻上的勇猛功夫互相比較打趣。","c":[["冷笑直接把她按上錦榻，用徹夜力道證明誰才是全城最強男人",null],["怒摔酒爵拂袖離去",null]],"after":"她最沉醉的，正是看男人在妒火與勝負慾裡徹底失控。"},{"k":null,"t":"自詡亡國尤物","d":"面對滿朝清流痛罵她是淫婦禍水，夏姬反而在大殿轉身輕撩紅紗媚笑宣告：「能讓雄主為了我亡國，是你們男人的榮幸！」","c":[["大笑鼓掌封她為歸墟第一絕色",null],["冷臉喝令她退下閉門思過",null]],"after":"世人罵得越兇，她眼角眉梢的妖豔笑意便越是銷魂。"}],"liji":[{"k":null,"t":"假哭演戲","d":"你推開殿門正好撞見上一息還在與優施冷笑商議殺局的驪姬，見你進來竟三息落淚裝出受盡委屈的模樣。","c":[["冷笑鼓掌戳穿演技，卻依舊留宿晉陽暖閣",null],["厭惡甩袖斥她滿嘴鬼話",null]],"after":"她的眼淚從來不是軟弱，而是最精準見血的利刃。"},{"k":null,"t":"暗殺你保下的忠臣","d":"你明明下旨饒過一名剛直老臣，驪姬當面柔聲稱頌聖明，隔夜卻暗派驪戎死士偽裝流寇將其滿門滅口！","c":[["震怒將她重罰杖責並禁足反省",null],["冷笑默許「死了也好，省得他天天在殿上頂嘴」",null]],"after":"溫軟枕邊人動起手來，比世上任何酷吏都要乾淨陰狠。"},{"k":null,"t":"點破傀儡真相","d":"深夜微醺，驪姬赤足貼進你懷裡柔聲低笑：「夫君真以為是你在掌權？其實每一把劈向忠良的刀，都是妾身替您指的方向呢。」","c":[["反手掐住她纖細咽喉冷笑「那妳別忘了誰才是握刀的人」",null],["震怒一把推開她奪門而出",null]],"after":"究竟是誰操控了誰，連你自己也漸漸分不清了。"},{"k":null,"t":"私定清洗名單","d":"驪姬竟未經通傳便直接將一份擬好的「前朝不忠官員處決名冊」遞交酷吏司準備動手。","c":[["冷酷蓋印准奏全數血洗",null],["當眾撕碎名冊警告她休得越俎代庖",null]],"after":"毒蛇一旦嚐過借刀殺人的甜頭，便再不肯縮回陰影之中。"}]},"hwin":{"jiananfeng":{"爭權":"哈哈哈哈！這六宮與中樞印信，終究還是落回我賈南風掌心了！","進讒":"那狐狸精果然中招倒台了！這便是跟本宮作對的下場！","干政":"滿朝百官嚇得大氣不敢喘，這才叫真正的皇后威儀！","收買":"金餅開路、毒藥隨行，如今這座後宮處處都是本宮的耳目與死士！"},"daji":{"爭權":"這肥缺本姑娘已經替夫君塞進最聽話的人啦——朝堂瑣事你只管甩手享福便是。","進讒":"枕邊輕輕吹兩口熱氣，便把那礙眼賤人送進冷院數日子了。夫君果然最疼奴家。","干政":"那個成天罵我妖孽的頑固武夫總算丟了官印！這下看他還拿什麼在殿上狂吠。","收買":"庫房這匣明珠亮得教人心癢，奴家先拿去換幾車西域烈酒，管事連大氣都不敢出呢。"},"xiaji":{"爭權":"咯咯，這世間最強的權柄從來不是虎符，而是奴家這副不老銷魂身子！","進讒":"男人果然永遠只信美人枕邊的吐氣如蘭呢～","干政":"瞧這滿朝文武為了奴家神魂顛倒的醜態，比當年陳國還好看十倍！","收買":"兩件貼身紅汗衫就能撬翻半個朝堂，這買賣可真划算呀！"},"liji":{"爭權":"（垂眸淺笑）不動一兵一卒，整座朝堂的殺伐風向便全攥在妾身袖底。","進讒":"那個礙事的忠臣與情敵終究死在夫君自己刀下，昨夜那幾滴淚沒白流呢。","干政":"借君王自己的刀殺最忠心的臣，天下哪有比這更乾淨痛快的手段？","收買":"毒胙肉已備妥、鐵證如山，明日便請君入甕罷。"}},"duty":{"jiananfeng":[{"n":null,"d":null,"eff":null,"line":"這後宮誰敢不聽號令，本宮直接矯一道假旨把她塞進枯井活埋！"},{"n":null,"d":null,"eff":null,"line":"養死士千日，殺政敵、殺敵軍，本宮的人從不問對錯只認血令。"},{"n":null,"d":null,"eff":null,"line":"殺一個不夠震懾，夷他三族，這座城才終於肯老實點！"}],"daji":[{"n":null,"d":null,"eff":null,"line":"敢靠近這座城的蠢貨，先嚐嚐本姑娘青丘狐火與迷魂幻陣的滋味罷！"},{"n":null,"d":null,"eff":null,"line":"星盤裡的靈氣聞著真香甜呢……讓奴家替夫君多吸幾口回來填滿它！"},{"n":null,"d":null,"eff":null,"line":"天下凡人誰不貪圖美色繁華？有奴家在，還怕勾不住這滿城人心嗎？"}],"xiaji":[{"n":null,"d":null,"eff":null,"line":"咯咯，只要奴家肯笑著解衣斟酒，這宮裡宮外哪個男人捨得翻臉？"},{"n":null,"d":null,"eff":null,"line":"男人天生愛往美人裙下鑽，奴家勾勾手指，流民與降將自己就跑來了。"},{"n":null,"d":null,"eff":null,"line":"採天地陽氣、養絕色雪肌，順手替夫君清清這滿城晦氣罷了。"}],"liji":[{"n":null,"d":null,"eff":null,"line":"夫君放心，誰對您懷有二心，妾身夜裡流兩滴淚便能替您全試出來。"},{"n":null,"d":null,"eff":null,"line":"正人君子不便沾手的髒活，交給妾身養的優施與驪戎密探便是。"},{"n":null,"d":null,"eff":null,"line":"借刀殺人、毒肉離間，這套法子拿去算計城外敵酋一樣百發百中呢。"}]},"meddle":{"jiananfeng":["那老賊竟敢在朝堂上反對本宮？明日便以謀逆大罪抄斬他三族！","這份調兵詔書本宮已替夫君改寫完畢，這支禁軍從今日起直歸椒房殿節制。","朝堂上少跟那群迂腐酸儒講道理，直接拿人頭堵死他們的嘴最痛快！"],"daji":["夫君，那個整天在朝會上瞪著我的老頑固太礙眼了，不如革了他的官，賞給奴家解悶？","那麼多晶核堆在庫裡多浪費呀，不如讓奴家拿去修一座更奢華的觀星鹿臺好不好？","跟敵軍講什麼仁義戰法？讓奴家放狐影去把他們主帥迷得神魂顛倒，不戰自潰！"],"xiaji":["那位年輕將軍生得英挺又懂疼人，夫君不如升他當個禁軍統領嘛～","城外敵酋開的價碼高得教人心動呢，夫君若不加倍疼奴家，我可真要跑囉！","那個整天罵我淫亂的老御史太掃興，今晚自然會有愛慕我的大人替我割了他的舌頭。"],"liji":["那位大將屢立戰功、軍中只知將軍不知天運者，夫君不如趁早收其兵符以防不測。","朝中那幾名清流成日聯名上書，分明想架空夫君，妾身已替您擬好清洗名冊了。","大祭在即，旁人經手的胙肉妾身實在懸心，還是讓妾身暗中替您「查驗」一番罷。"]},"night2":{"jiananfeng":[["{a}：「把那盞銅燈吹滅，本宮討厭屋裡亮得像白晝。」","you：「怕我瞧見妳眉間那顆贅瘤？」","{a}：「（冷笑反手捏住你下頜，指尖冰涼）怕你露出那副虛偽男人的嫌棄嘴臉，逼本宮今晚見血！」","you：「我若嫌棄妳，今夜就不會推開椒房殿這扇門。」"],["{a}：「明日早朝，太傅那老東西多半又要拿外戚專權說事。」","you：「妳打算怎麼收拾他？」","{a}：「還能怎麼辦？先下手為強，伏兵宮門夷他三族，省得夜長夢多！」","{a}：「你這雙手若下不了狠心，便由本宮替你染紅。」"],["{a}：「聽說{b}近來在書房出入得勤快得很？」","you：「不過是商議些內廷庶務。」","{a}：「商議庶務需要關起門商議到三更半夜？再有下回，本宮親自提著短戟去替你們掌燈！」"]],"daji":[[[null,"夫君，今夜這滿天星斗亮得晃眼，可奴家覺著還是你盯著我身子時眼裡的光更好看呢。"],[null,"又在灌迷湯，說吧，今晚是不是又想討什麼奢靡特權？"],[null,"（雪白尾尖輕輕捲上你的手腕，笑意慵懶勾人）被你看穿啦……我不要珠玉也不要官印，只要夫君今晚把這副身子徹底交給奴家。"]],[[null,"有時看著城裡凡人日出而作、累得像牛馬，真搞不懂他們幹嘛活得這般費勁。"],[null,"因為心裡有想護住的人，再費勁也甘之如飴。"],[null,"（妖瞳微微一顫，隨即縮進你懷裡低聲呢喃）……真怪，奴家現在好像也有點懂這種傻念頭了。"]],[[null,"外頭寒霧重得很，夫君手腳怎麼冷得像冰塊？"],[null,"剛從北門箭樓巡防回來。"],[null,"（九條雪白狐尾無聲舒展將你緊緊裹住，赤紗滑落露出溫軟雪肌）快進來罷，這世上沒有比青丘九尾更暖和的被窩了。"]]],"xiaji":[["{a}：「夫君，說句掏心窩子的話——你收留我這個亡國禍水，究竟是貪奴家這副身子，還是想證明自己比陳靈公強？」","you：「兩樣都有。」","{a}：「（咯咯嬌笑貼進你懷裡，豐乳輕壓你胸口）誠實的男人最銷魂了。那奴家便瞧瞧，你這座孤城能扛過幾回風浪囉。」"],["{a}：「昨夜那位年輕將軍又託宮婢偷送了匣南海明珠進株林暖閣。」","you：「妳收下了？」","{a}：「送進門的寶貝哪有往外推的蠢理？夫君要是吃醋，明早多賞我兩匣更貴的，今晚再狠狠折騰奴家不就平了嘛～」"],["{a}：「別板著臉啦，湊近聞聞奴家新煉的駐顏香。」","you：「這香氣裡沒摻什麼催情迷藥吧？」","{a}：「對付夫君哪用得著迷藥？光奴家這身雪膚玉臀，就夠讓你神魂顛倒一整夜了，不是嗎？」"]],"liji":[["{a}：「夫君，今日{b}妹妹呈進來的點心，妾身聞著總覺香氣帶著一絲古怪。」","you：「妳拿銀針試過了？」","{a}：「（柔聲低頭，眼角微紅）沒什麼，許是妾身多心了。夫君萬萬別去責怪妹妹，免得她以為我在背後進讒言呢。」","you：「（心底已不由自主埋下猜忌的刺）……」"],["{a}：「那位老將軍今日又在營裡私自拿私財犒賞士卒，軍心歸附得很呢。」","you：「他向來愛兵如子。」","{a}：「是呀，甚寬惠而慈於民……（忽然垂淚哽咽）可當年晉國太子申生亦是這般深得民心，妾身真怕哪日生變啊！」"],["{a}：「若有一天，夫君發現我口中每一句溫言軟語全是算計，你會殺了我嗎？」","you：「那得看妳的算計，是幫我還是害我。」","{a}：「（唇角浮起世上最溫柔也最森冷的笑）聰明的夫君。這世上，唯有驪姬永遠不會讓你失望。」"]]},"talk2":{"jiananfeng":{"陌生":["滾遠點！你這副假惺惺的模樣，跟當年楊駿那老賊一樣令人作嘔。","想收服我？先證明你手裡的刀比本宮的短戟更狠再開口！"],"熟識":["前朝那幾個老將功高震主，你若下不了手，本宮可以替你矯一道手詔。","男人都愛年輕貌美的皮囊，唯有攥在手裡的兵權與玉璽永遠不會嫌棄我。"],"信賴":["你居然真敢把內廷生殺交給我？哈哈，天運者，你比司馬衷那白癡有意思多了！","聽說城南新來了批俊俏少年？哼，你管好你的前朝，本宮私下解悶的事別多問。"],"親密":["唯有看著你毫不嫌棄的眼神，本宮心口這股殺火才稍微平息半寸……但也只平息半寸。","誰敢懷上你的種來威脅本宮的位子，我照樣一戟砸穿她的肚子，你可別攔著！"],"誓約":["天下人罵我醜毒淫后又如何？這座城裡誰的命不攥在咱們夫妻手裡？","別指望我為你變溫順！要麼陪我一起血洗這亂世，要麼看我掀翻這座燈塔！"]},"daji":{"陌生":["呀，你便是能喚出青丘九尾狐的天運者？眼裡這股野心倒挺合我胃口。","別像那些酸儒一樣拿戒備眼神防著我，奴家現在可乖巧得很呢。"],"熟識":["你這男人真稀奇，明知奴家是禍國妖狐，卻從不拿符咒或大道理嚇唬我。","城外那片黑霧臭得要命，哪天本姑娘放一把狐火全替你燒光好不好？"],"信賴":["千年來人人都怕我、罵我、拿我當工具，唯獨你把我留在枕邊疼。","別怕，只要你對奴家好，誰敢動你的城池，本姑娘第一個咬斷他的喉管！"],"親密":["夫君今夜心跳怎麼亂得這麼快呀？是青丘狐香太烈，還是盯著奴家胸口移不開眼了？","不許再往別殿跑，今晚罰你抱著我的狐尾折騰到天亮！"],"誓約":["青丘九尾千年孤傲，這輩子偏偏栽進你這凡人懷裡——你可得負責寵到底喔。","無論天上地下還是九幽血海，夫君去哪兒，奴家便纏著你到哪兒！"]},"xiaji":{"陌生":["男人嘴上說著禮義廉恥，眼睛卻永遠最老實。天運者，你也一樣罷？","收留亡國禍水夏姬，你就不怕前朝重臣為了搶我拔刀相向嗎？"],"熟識":["昨夜宴席上那兩位大夫眼神燙得嚇人，改日邀他們進暖閣一起品酒如何？","駐顏秘術的竅門呀……自然是多多採補天下最勇猛男人的陽氣囉，咯咯。"],"信賴":["你吃醋發狠的模樣真教人腿軟……越想獨佔我，就越要拿出壓倒全城男人的本事來！","放心，就算前朝大夫穿著我的紅汗衫上朝炫耀，我心裡最燙的那塊位子還是留給你的。"],"親密":["看著滿城男人為了奴家這副身子發瘋流血、險些亡國，你不覺得特別刺激嗎？","別拿貞節鎖綁我，綁不住的。除非你能把這世上所有比你強的男人都殺絕！"],"誓約":["就算明日城破人亡，我夏姬也絕不悔改！要嘛踩著情敵屍骨壓住我，要嘛陪我一起醉死亡國夜！","這件最貼身的赤紅衵服只給你穿——至於明天會不會再繡新的，看你今晚的表現囉～"]},"liji":{"陌生":["妾身不過一介驪戎弱女子，不懂前朝兵事，只盼夫君安穩，莫遭身邊笑面虎暗算。","這深宮看似和睦，實則暗潮洶湧，夫君萬事可得多留個心眼。"],"熟識":["昨夜妾身夢見有人拿毒肉謀害夫君，嚇得半夜哭醒……許是太在乎夫君才胡思亂想罷。","那位忠臣確有本事，連城中百姓都只知將軍不知天運者呢——夫君得此良將，真是「福氣」。"],"信賴":["（夜半輕泣）夫君，他們都在等著看我失寵呢……你若心軟留著那些勢大難制之人，明日死的就是我們啊！","放心，所有髒活與罵名妾身都能安排得滴水不漏，絕不髒了夫君的名聲。"],"親密":["看著你親手斬盡礙眼的忠良、把全城猜忌得人人自危，最後只敢抱緊我……夫君，這感覺真美妙。","就算你哪天察覺毒肉是我下的、夜泣是我演的，你猜你還回得去當初那個明君嗎？"],"誓約":["別指望我洗白向善！我就是世上最毒的枕邊蛇，而你，是我親手雕琢出來的多疑暴君！","來吧，把下一份清洗名單遞給我，今夜妾身陪夫君慢慢勾銷。"]}},"negtag":{"who":{"jiananfeng":{"tags":null,"why":"因矮黑容貌與眉間贅瘤生出極端妒火與殘虐控制慾，視貌美孕妾與清流為死敵，動輒矯詔夷族、睚眥必報。"},"daji":{"tags":null,"why":"青丘九尾天性妖冶殘忍且喜怒無常，對酒池肉林、靈氣與夫君的獨寵永不知饜足。"},"xiaji":{"tags":null,"why":"看穿男人貪色本性，樂於四處留情、分贈赤紅汗衫挑動群臣拔刀互殺，對亡國流血毫無半分愧色。"},"liji":{"tags":null,"why":"城府深不可測的偽善心理操縱師，慣以夜半而泣與毒肉嫁禍借君王之手誅殺忠良情敵，冷血無悔。"}}},"office2":{"shanggong":{"assign":{"jiananfeng":"把六尚大印交給本宮？甚好！從今日起，後宮誰敢偷懷龍種、誰敢背後笑我醜，本宮直接用短戟與枯井替你行宮規！","daji":"咯咯，讓亡國九尾狐當尚宮管六宮規矩？夫君這步棋真瘋呀～那奴家可得好好「調教」姐妹們囉！","xiaji":"咯咯，讓春秋第一禍水掌管六尚與內廷採買？只怕不出十日，前朝男官全搶著往內廷鑽、把章疏全丟腦後囉～","liji":"（溫婉福身，眼底暗藏冰冷算計）妾身才疏學淺，既蒙夫君託付尚宮重任，自當替夫君「細細查核」每位姐妹的忠心，絕不留半個隱患。"}}},"love":{"special":{"jiananfeng":[{"lv":null,"t":"血戟示愛","d":"賈南風提著剛處決完一名彈劾她御史的沾血短戟大步走進書房，玄黑裙角濺滿暗紅血點，陰鷙而狂熱地將對方府中抄出的金山與玉璽推到你腳邊。","c":[["大笑擁她入懷「殺得痛快，這才配做我的惡后」",null],["皺眉喝令她洗淨血跡，莫在書房裡這般放肆",null]],"after":"西晉惡后的愛意，從來都裹著政敵尚未涼透的鮮血。"},{"lv":null,"t":"椒房稱制","d":"深夜椒房殿，賈南風已將你書房外所有宿衛暗中換成她的東宮死士，並把兩道早蓋好假印的夷族密詔拍在你案上逼你共簽。","c":[["毫不猶豫提筆共簽「前朝後宮咱們夫妻一起殺穿」",null],["冷笑摔筆斥她越權篡政",null]],"after":"當權柄與瘋狂徹底交纏，誰也別想全身而退。"},{"lv":null,"t":"共焚燈塔","d":"諸將與清流因不堪她專權酷虐而暗中串聯逼宮，賈南風卻在火光映照的高臺上死死攥著你的手狂笑，發誓誰敢動她后位便拖著整座城同歸於盡。","c":[["反手扣緊她的腰「要瘋便一起瘋到底」",null],["強硬壓制她收手，保住城池不致內亂崩毀",null]],"after":"這場以鮮血立盟的偏執之愛，絕無半分悔改收手的可能。"}],"daji":[{"lv":null,"t":"狐香纏身","d":"你剛在暖閣小憩片刻，醒來卻發覺衣領敞開、全身上下沾滿了濃郁勾人的青丘狐香，連中衣腰帶都被妲己悄悄換成她的赤紅絲帶。九尾狐赤身裹著薄紗窩在你胸膛嬌笑：「這下你去{b}殿裡時，她一聞便知夫君剛從奴家花戶裡出來囉～」","c":[["大笑揉亂她雪白狐尾，反手將她按回榻上「那今晚哪兒也不去了」",null],["無奈點了點她鼻尖，任由這股露骨奇香留在身上帶著走",null],["眉頭微皺起身更衣洗去香氣，惹得她氣鼓鼓甩尾冷哼",null]],"after":"嘻嘻，夫君渾身上下全染滿了本姑娘的氣息，滿城都知道你是青丘九尾狐的禁臠啦！"},{"lv":null,"t":"狐火迷宮","d":"深夜你原欲前往{b}殿閣，剛出書房卻見長廊驟然漫起幽藍青丘幻霧——無論往哪條路走，轉角竟全鬼打牆般回到妲己暖閣門前！妲己赤足立於紅燈影下，赤紗滑落半肩，妖瞳燃著危險瘋火：「夫君還想去哪兒呀？這座城裡，只有本姑娘的被窩替你開著喔。」","c":[["被這份妖異而滾燙的獨佔慾點燃，直接攔腰扛起她踏進暖閣",null],["溫柔握住她微涼的手哄她撤去幻霧，許諾明晚整夜陪她",null],["引動星盤正氣強行震散幻陣，嚴詞斥她不可對君王施妖術",null]],"after":"凡人的宮規鎖不住九尾狐！只要本姑娘看上的男人，逃到天涯海角我都要用幻陣拽回床榻！"},{"lv":null,"t":"焚尾護君","d":"一頭深淵古魔撕裂外圍防線直撲星盤中樞，連重甲親衛皆被魔氣震飛！千鈞一髮之際，妲己收起一切嬉笑，身後九條雪尾轟然燃起焚天青丘真火，硬生生將古魔攔腰燒成焦炭，隨即妖力枯竭軟倒進你懷裡，胸口劇烈起伏：「敢碰我的男人……就算燒盡千年修為，奴家也要牠灰飛煙滅！」","c":[["不顧損耗以星盤靈氣全力反哺她，發誓生生世世護她周全",null],["緊抱住虛弱露出毛茸狐耳的她，輕吻她冷汗涔涔的額頭哄睡",null],["將繳獲的稀世晶核全數贈予她溫養妖元，立下不死不休之約",null]],"after":"千年道行算什麼？沒了夫君，長生不老也不過是無聊透頂罷了……抱緊奴家。"}],"xiaji":[{"lv":null,"t":"株林秘術採補","d":"月圓之夜，夏姬點滿令人骨酥的駐顏催情奇香，只披一件半透赤紗露出勝雪豐乳與飽滿玉臀，赤足邀你共修春秋採補秘術，極盡纏綿勾魂，卻也在無聲抽乾你的理智。","c":[["徹底沉淪於她溫軟緊緻的身子，徹夜銷魂不醒",null],["硬撐著最後一絲清明在關鍵處抽身收手",null]],"after":"那股沁入骨髓的異香與花露溫熱，讓你從此再也戒不掉她的體溫。"},{"lv":null,"t":"汗衫誘君上朝","d":"早朝前夕，夏姬剛從被窩起身，笑盈盈脫下沾滿體香與微汗的貼身赤紅絲綢衵服塞進你朝服領口裡，慫恿你效法陳靈公穿著去正殿氣死清流。","c":[["狂笑穿在朝服裡大搖大擺上朝向百官炫耀",null],["冷笑把赤紅汗衫甩回床榻「這玩意兒只准在房裡穿給我瞧」",null]],"after":"正殿朝服領口露出的那一抹刺眼赤紅，讓滿朝文武徹底看清了君王的沉淪。"},{"lv":null,"t":"亡國尤物的真心","d":"內外血火交加之夜，城外敵酋再度開出天價索要夏姬，她卻罕見地將敵酋情書撕成碎片，赤足撲進你懷裡媚笑：「這座孤城還沒被奴家親手玩亡呢，我才不走！」","c":[["大笑扣緊她纖腰「那就陪我把這天下徹底玩爛」",null],["冷靜壓下城中動盪，立誓絕不向敵酋交出她",null]],"after":"禍水終究是禍水，但這一夜，她選擇留在你的懷裡一塊燒成灰。"}],"liji":[{"lv":null,"t":"三更夜半泣","d":"深夜晉陽暖閣，驪姬只著單薄素白中衣伏在你胸口泣不成聲，微顫豐胸緊貼著你，以「忽擒忽縱」的頂級心理操縱反覆暗示你最倚重的大將與{b}已暗結死黨，哀求你先下手清君側。","c":[["徹底被她點燃猜忌殺火，連夜下旨清洗嫌疑官員",null],["冷靜壓下疑心，指腹拭去她眼角淚珠「妳這眼淚比刀還利」",null]],"after":"枕邊溫熱的淚水，比世上任何冷刃都更能劈斷君臣之間的信任。"},{"lv":null,"t":"共犯的毒茶","d":"你親手查出她與心腹樂師優施偽造毒胙肉案的鐵證並拍上案頭。驪姬竟瞬間收住假淚、露出世上最冰冷迷人的微笑，反手握住你沾血的手指輕語：「咱們早就綁在同一條血船上了。」","c":[["冷笑點火燒掉鐵證「沒錯，妳這把溫柔毒刀我用得極順手」",null],["震怒下令將她禁足兩旬以示懲戒",null]],"after":"撕碎柔弱偽裝之後，這份赤裸的共犯羈絆反而更加牢不可破。"},{"lv":null,"t":"孤王與毒蛇","d":"朝堂歷經連番血洗變得死寂冰冷、人人自危，驪姬卻在昏紅燭火裡溫柔替你披上玄金龍袍，鬆開自己衣帶從身後緊緊擁住你，眼底滿是徹底獨佔你的病態滿足。","c":[["反手將她拉進懷裡緊扣「這座猜忌之城，往後只信妳一人」",null],["輕嘆提醒她「別把忠良全殺絕了，總得留幾個人守城」",null]],"after":"當全天下都背棄你時，枕邊那條毒蛇露出了最甜美醉人的微笑。"}]}},"persona":{"jiananfeng":{"desire":"將中樞玉璽與滿城性命死死攥在掌心，殺光所有生得比她美、敢奪她權柄或敢搶先懷孕生子的賤人。","fear":"因矮黑青面與眉間贅瘤遭人私下恥笑，或失權後被外戚與宗室聯手廢黜、灌下金屑酒處死。","pride":"西晉鐵血惡后，矯詔伏殺太傅楊駿夷其三族、餓死楊太后於金墉城、廢殺太子司馬遹，親手撬翻整個西晉天下。","face":"暴躁陰鷙、身材矮小、面帶青黑且眉間生瘤，言辭刻毒，舉手投足皆是令宮婢發抖的血腥戾氣。","back":"兼具極端殘暴與肆無忌憚的肉身淫慾——一面親持短戟砸向孕妾腹中令其落胎斃命，一面命閹豎以大木箱偷載洛陽白皙少年入宮共寢，玩膩或不合意者直接滅口沉井。","loveWay":"把所有敢威脅你與她地位的權臣、宗室與孕妾盡數夷三族，用屍山血海證明唯有她能替你鎮住中樞。","hateWay":"最赤裸的肉體摧毀——親提短戟砸毀孕婦胞宮、矯詔抄斬政敵滿門，甚至不惜點燃八王之亂般的內戰來保全權位。","scheme":"偽造天運者手詔騙政敵入宮伏殺，並與太醫令程據及心腹閹豎結黨，一面獨霸中樞一面在暗室縱情聲色。","weak":"對容貌極度敏感，任何無心一瞥都會引爆殺機；她絕不會為你變溫順或守貞，只會要求你交出實權、閉眼容忍她的一切暴行與木箱少年。","heart":{"相愛":["哼，前朝那幫文臣背地裡笑本宮矮黑醜陋？明日便矯一道手詔，把領頭那老賊夷了三族！","這座燈塔的男人哪個不看皮囊？唯有把刀柄與玉璽攥死在手裡，他們才敢跪著喊本宮一聲皇后。","太醫令程據生得眉清目秀、手又軟……待會兒召他來「診脈」，順便留宿暖閣解解乏。"],"迷戀":["你竟不嫌棄本宮眉間這顆贅瘤，還敢直直盯著我的眼睛？呵呵……這世上總算有個不那麼膚淺的男人了。","不過一碼歸一碼，前朝兵權與後宮生殺，本宮一寸都不會讓出去。","聽說{b}生得傾國傾城、雪膚花貌？真想拿短戟劃爛她那張招搖的臉，看夫君還愛不愛看！"],"深愛":["我越看重你，就越容不得你身邊留著任何外戚、重臣與孕妾！誰敢分走你半分權柄，我便先替你全殺絕！","別管我偏室裡抬進幾個大木箱、沉了幾個不中意的少年進枯井——那是本宮洩火的法子，你只要記住我心裡最重的是你便夠了。","誰敢罵我半句，本宮便教這座城也嚐嚐「八王之亂」的滋味！"],"沉淪":["{b}竟然有孕了？！好大的狗膽！來人，把我的青銅短戟拿來，本宮今天親自去她殿裡「賀喜」、替她落胎！","這幾日你忙著前朝不進我屋，本宮只好命閹豎用大木箱從城南抬個白淨小吏進來暖床——用完若嘴不嚴，直接毒殺沉井便是。","你越護著那些年輕嬌嫩的狐狸精，本宮心口這團殺火就燒得越旺！"],"病態":["夫君太容易心軟了！把玉璽交給本宮，所有反對你的將領、所有敢懷你骨血的賤婢，我一夜之間替你殺乾淨！","那個城南小吏在榻上倒挺賣力，賞他兩件宮衣蒙著眼放出去罷；至於上月那兩個哭哭啼啼的少年，早填進禁苑枯井了。","誰敢動本宮鳳位，我便先挑動你麾下諸將自相殘殺，教這座燈塔徹底變成修羅血海！"],"絕對":["天下人罵我毒婦、罵我淫后又如何？這座城裡誰的命不攥在我賈南風手裡？唯有你，配與我共享這張沾血龍椅！","別想叫我放下短戟、別想叫我遣散箱子裡的少年、更別想看我低頭悔改！你既愛我，就得連這份腐爛與血腥一併吞下去！","就算明日滿城兵變、宗室反目，今夜本宮也要先手刃了{b}，再與夫君痛飲這杯血酒！"]},"act":{"相愛":[{"d":"一名小宮婢奉茶時不慎多看了賈南風眉間贅瘤一眼，賈南風當場暴怒，奪過廊下宿衛佩劍一劍刺穿宮婢胸膛，血濺滿院。","say":"賤奴也敢偷笑本宮容貌？拖出去埋了，別污了夫君的眼！","eff":{"love":null,"pop":null,"rumor":"聽說賈南風因宮婢多看她一眼便親手手刃對方，內廷上下嚇得魂飛魄散！"}},{"d":"賈南風與內廷相貌俊秀的太醫令走得極近，整日以「調理血氣」為由將其反鎖在暖閣內室，帳內傳出陣陣曖昧低喘。","say":"本宮身子不爽召太醫細診，難道還得向夫君逐一稟報？","eff":{"love":null,"mood":null}}],"迷戀":[{"d":"前朝一名重臣當庭反對賈南風干政，賈南風竟偽造你的手詔將其騙進宮門伏殺，隨即下令抄斬其三族老小！","say":"那老賊早懷反心，本宮替夫君先斬後奏、夷其三族，省得日後生變。","eff":{"love":null,"energy":null,"pop":null,"rumor":"大禍！賈南風矯詔伏殺重臣並夷其三族，滿朝文武人人自危！"}},{"d":"賈南風命心腹閹豎用裝衣物的大木箱，趁夜從城南秘密抬進一名白皙俊美的小吏入宮共寢數夕，事後賞其華服放回。","say":"（對著無鏡空案塗抹濃粉冷笑）這小吏倒挺會伺候女人，暫且饒他一條狗命罷。","eff":{"love":null,"rumor":"市井傳出離奇怪談，城南一小吏被裝進木箱抬入深宮共寢數夜，出來時竟穿著宮中錦衣！"}}],"深愛":[{"d":"賈南風見{b}近來極得聖寵且傳出有孕風聲，竟親提一柄沉重短戟衝入{b}殿中，當眾朝{b}微隆小腹狠狠擲去！雖被宿衛險險格偏，仍砸得{b}當場下身見紅重傷！","say":"賤婢也配懷天運者的骨血？！算你命大躲過這一戟，下回本宮親手剖開你的胞宮！","eff":{"love":null,"_lb":null,"rel":[[null,null,null]],"_mb":null,"rumor":"駭人聽聞！賈南風竟親擲短戟砸向疑似有孕的{b}，險些釀成一屍兩命！"}},{"d":"賈南風暗中挑唆你麾下兩名手握重兵的大將互相猜忌攻訐，藉機坐收漁利、將中樞兵符全數收歸椒房殿。","say":"讓這群武夫互相咬死最好，如此夫君與本宮才能高枕無憂！","eff":null}],"沉淪":[{"d":"你突擊搜查賈南風暖閣暗室，竟在密箱裡翻出數名「不合她心意」而被毒殺滅口的少年屍骨與血衣！面對鐵證，她非但毫無懼色，反而冷笑逼近你。","say":"不過幾個玩膩了的賤民少年，殺了便殺了，省得出去亂嚼舌根！天運者難道要為了幾條賤命辦本宮？","eff":{"love":null,"pop":null,"mood":null,"rumor":"後宮驚爆「木箱屍骨案」！賈南風偷載少年入宮淫樂後滅口之事徹底敗露！"}},{"d":"賈南風偽造證據誣陷城中威望最高的主母或儲君人選謀反，逼你當殿廢黜對方並關進斷水斷糧的金墉冷殿。","say":"擋路的人全該活活餓死在金墉城裡！夫君若不忍心下旨，本宮替你蓋印便是！","eff":null}],"病態":[{"d":"賈南風徹底不避諱與太醫令及外男私通，甚至當著你的面冷嘲熱諷，同時暗調東宮死士團團圍住了反對她的朝臣府邸。","say":"你三宮六院夜夜換女人，本宮在偏室養幾個解悶的少年怎麼了？有本事你現在就廢了我，看看明早全城會不會爆發兵變！","eff":{"love":null,"energy":null,"pop":null,"mood":null}},{"d":"因恨透{b}那張花容月貌，賈南風派死士深夜闖入{b}暖閣企圖劃爛她的臉並滅口，鬧得整座內廷血流成河。","say":"生得那麼狐媚勾引誰？劃爛那張皮，看這宮裡還有誰敢跟本宮比！","eff":{"love":null,"_lb":null,"rel":[[null,null,null]],"mood":null}}],"絕對":[{"d":"諸將與清流因不堪賈南風殘虐專權而聯手兵變，城中陷入宛如「八王之亂」般的慘烈廝殺！賈南風卻立在城樓火光裡狂笑，死死攥著你的手不放。","say":"亂吧！殺吧！誰敢動我賈南風的后位，本宮就拖著整座燈塔一起化作焦土！夫君，你休想逃！","eff":null},{"d":"賈南風將沾滿鮮血的短戟重重釘進你書案木板裡，矮小身軀透出駭人瘋狂，仰臉灼熱地盯著你。","say":"我醜、我毒、我淫亂、我殺盡一切礙眼之人——但我對你這份瘋狂的執念也是真的！永遠別指望我悔改，這輩子你只能跟我一起爛在血海裡！","eff":null}]},"mood":null,"react":{"pamper":["哼，算你還有點眼力，沒被那些只剩皮囊的蠢貨迷昏頭。","只要你肯把玉璽與生殺大權交進椒房殿，本宮自然護你坐穩這座城。"],"scold":["罵我殘暴淫亂？呵，這滿朝文武哪個不是被本宮殺怕了才乖乖跪著說話的？","你再敢多罵半句，小心明早菜市口多出幾具無頭屍體！"],"ignore":["冷落本宮？好啊，正好省得我遮掩，今晚就讓太醫令跟木箱裡的少年一塊進來伺候！","你儘管躲去{b}榻上，等哪天她肚子裡那塊肉莫名其妙流掉了，別哭著來找我！"],"punish":["禁足？廢后？天運者，你敢動我一根寒毛，我賈家黨羽明早便教這座城血流成河！","罰吧！鎖著我我也照樣能遞假詔殺人，咱們走著瞧！"],"forgive":["這才識相。本宮從沒覺得自己做錯半件事，何須你假惺惺原諒？","既放本宮出來了，明早便把彈劾我的那幾個御史全斬了罷。"],"other":["剛賞玩完{b}那張狐媚臉蛋？小心哪天本宮拿短戟把它劃成破布！","你儘管寵她、讓她懷胎，咱們比比是她生得快，還是本宮的短戟飛得快！"],"caught":["（被撞破箱載少年或矯詔殺人，滿臉戾氣毫無悔意）是我幹的又如何？！我手殺宮婢、我擲戟砸孕婦、我睡洛陽少年，那全是我身為西晉皇后的特權！要殺便殺，想看我悔改？做夢！","不合心意的少年殺了沉井省事，礙眼的孕妾砸死了乾淨！這就是我賈南風的規矩！"],"win":["哈哈哈哈！權力與鮮血從不騙人，看這宮裡還有誰敢跟本宮作對！","贏了就該趕盡殺絕，把她全族一併抄斬才算痛快！"]}},"daji":{"desire":"將這座孤城打造成第二座朝歌鹿臺，拉著你在酒池肉林與酷刑慘叫裡享盡極致墮落，直到天崩地裂。","fear":"無聊、死板禮法，以及眼睜睜看著你被清流調教成滿口仁義道德的無趣聖人。","pride":"青丘九尾天狐，能讓雄才大略的君主親手架起炮烙、剖孕婦、斷朝涉者脛骨，只為換她一笑。","face":"慵懶媚豔、笑聲清脆如銀鈴，窩在你懷裡像隻愛撒嬌的白狐，連提議活烤諫臣時都掛著天真甜笑。","back":"骨子裡毫無凡塵善惡觀，視宮婢、流民與忠臣如玩物血食；愛得越深，越要把你徹底拖進血腥與淫慾的深淵共沉淪。","loveWay":"用最露骨的肉身魅惑與殘酷血宴取悅你，步步引誘你釋放帝王骨子裡最陰暗的暴虐與色慾。","hateWay":"熱衷對情敵與直諫之臣施以虐殺——炮烙燙刑、毒蛇蠆盆、狐火燒衣，最愛看端莊貞女在酷刑下失禁崩潰求饒。","scheme":"懶得玩繁瑣算計，直接靠極致媚術與枕邊風把你養廢成暴虐昏君，讓你親手替她殺絕所有掃興之人。","weak":"她絕不會為了你洗白從良；你若試圖用聖賢仁義感化她，她只會嫌你無趣透頂，轉手把後宮燒成一片火海。","heart":{"相愛":["這座燈塔的酒太寡淡、規矩太多。等奴家慢慢調教夫君，總有一天讓你愛上朝歌酒池肉林的滋味～","今日那清流老臣在殿上吠得奴家耳朵疼，真想拿燒紅銅柱塞進他嘴裡呢。","凡人的命本就短得像夏蟲，拿來逗夫君與奴家開心，豈不是死得其所？"],"迷戀":["夫君昨夜醉酒後眼底那抹嗜血冷光真迷人……這才對嘛，當君王就該隨心所欲！","聽說{b}平素標榜端莊清高？奴家最愛看這種假正經女人被扒光衣裳、哭得滿地打滾了。","城外流民餓死幾十個算什麼？把倉裡陳糧全拿去釀烈酒，今晚咱們通宵作樂！"],"深愛":["我越愛你，就越想看你為了奴家拋開仁義、屠盡忠良、與滿城為敵——那樣的夫君，才徹底屬於九尾狐！","別聽酸儒胡扯什麼紅顏禍水，江山本來就是拿來揮霍享樂的，亡了便亡了，有奴家陪你笑到最後不好嗎？","鹿臺的肉林還沒掛滿炙肉呢，明早便催夫君加徵重稅，先替奴家鑿一座暖玉酒池罷！"],"沉淪":["{b}那張端莊臉看得奴家好厭煩……不如半夜放幾條青丘毒蛇鑽進她被窩，聽她淒厲尖叫下酒？","夫君這兩日又聽信清流批章疏了？不成，今晚得多燒兩倍催情狐香，把你這身硬骨頭徹底酥爛在榻上！","忠臣的哀嚎比絲竹動聽十倍——夫君，明日咱們就拿那個彈劾我的御史試試「炮烙」好不好？"],"病態":["什麼聖主明君全是騙人的鎖鏈！跟我一起瘋吧夫君，把這座城燒成赤紅鹿臺，把所有反對者全推進毒蛇蠆盆！","誰敢把夫君拉回正途，誰便是奴家死敵！{b}既然這般愛勸諫，今晚便讓她嚐嚐狐火烤焦雪肌的滋味！","滿城百姓與大臣全是咱們的玩具，玩殘玩死了再抓新的便是，夫君何必手軟？"],"絕對":["千年來總算遇上一個肯陪我徹底墮落、共聽眾生慘嚎的共犯！夫君，咱們就這樣爛在一起、永不超生罷！","想叫奴家悔改向善？哈哈哈哈！你愛上的本來就是吃人的九尾妖狐，現在裝什麼慈悲聖人？","就算明日黑霧吞城、萬劫不復，今夜咱們也要在酒池肉林裡抵死交歡、大笑著燃盡！"]},"act":{"相愛":[{"d":"妲己一把掃開書案上枯燥的兵書，命人抬進一壇烈性狐花釀與整盤流油炙肉，赤足跨坐上你大腿，袒露香肩親手餵酒。","say":"批章疏哪有陪奴家醉生夢死銷魂？今日政務全甩給底下人去辦罷～","eff":null},{"d":"一名小宮婢不慎打翻妲己的胭脂匣，妲己笑盈盈伸指放出一簇幽藍狐火活生生灼爛對方手背，聽著焦肉聲與慘叫滿臉愉悅。","say":"哎呀，小丫頭手腳笨拙，奴家幫她長長記性嘛。夫君不會為了個賤婢掃興罷？","eff":null}],"迷戀":[{"d":"妲己慫恿你動用國庫大批軍糧釀酒、大興土木在禁苑開鑿「酒池肉林」，令城中百姓怨氣沸騰。","say":"泥腿子種糧不就是為了供養天運者與奴家享樂的嗎？快下旨吧夫君，奴家等不及泡進酒池啦！","eff":{"food":null,"pop":null,"love":null,"rumor":"聽說妲己慫恿天運者耗費大批軍糧開鑿酒池，城中百姓私下怨聲載道！"}},{"d":"妲己暗中派人將一整簍青丘毒蛇毒蠍倒進{b}錦被與鞋襪中，自己赤足蹲在窗外聽著{b}驚恐慘叫掩唇嬌笑。","say":"咯咯，這尖叫聲比琵琶好聽多了，妹妹今晚定能過個難忘的長夜呢！","eff":{"love":null,"_lb":null,"rel":[[null,null,null]],"_mb":null}}],"深愛":[{"d":"前朝一名忠直御史上疏痛罵妲己惑主，妲己當晚便在暖閣架起一座燒紅的青銅炮烙模型，笑吟吟貼著你耳畔提議將老臣綁上去活烤。","say":"教他在燒紅銅柱上走一遭，看他皮焦骨裂時還罵不罵奴家是禍水！夫君准不准嘛～","eff":{"love":null,"pop":null,"energy":null,"rumor":"驚聞妲己竟進言重設殷商「炮烙之刑」活烤諫臣，滿朝文武毛骨悚然！"}},{"d":"妲己在暖閣燃起極烈青丘催情香，赤紗半解連留你三日三夜不出錦帳，致使前線急報堆積成山、朝綱大亂。","say":"江山哪有奴家這副軟玉溫香銷魂？讓他們在外頭乾等著去罷！","eff":null}],"沉淪":[{"d":"妲己趁你不備，將一名與{b}交好的貼身宮婢拖進偏院私設的毒蛇蠆盆裡活活嚇瘋咬傷，事後還笑嘻嘻拎著毒蛇蛻去{b}面前晃悠示威。","say":"下回再敢替夫君講大道理、吹枕邊風，躺進蠆盆陪蛇蠍玩的就是妳囉，妹妹～","eff":{"love":null,"_lb":null,"rel":[[null,null,null]],"_mb":null,"rumor":"後宮大駭！妲己竟在偏院私設毒蛇蠆盆折磨宮婢，逼得{b}殿裡人心惶惶！"}},{"d":"國庫軍糧告急之際，妲己卻強逼少府繼續供應每夜百人陪飲的奢靡狂歡宴，更當眾放狐火燒焦勸諫管事的鬚髮。","say":"外頭流民餓死關本姑娘什麼事？奴家的酒宴一夜都不能停！","eff":null}],"病態":[{"d":"深夜鹿臺高閣紅燈漫天、酒氣熏人，妲己赤身披著薄紗拉你倚欄俯瞰漆黑城池，九尾燃起妖豔火光，在你耳畔吐氣誘你徹底棄政沉淪。","say":"把前朝那幫囉嗦老東西全宰了吧！這座城只留你我、美酒與肉林，天天都是朝歌末日狂歡，多痛快！","eff":{"love":null,"pop":null,"energy":null,"mood":null}},{"d":"妲己見{b}仍得你幾分憐惜，竟直接放出一團幽藍狐火燒毀{b}半座暖閣與所有衣裙，險些將{b}活活困死火海。","say":"火光多美呀！夫君瞧，這下她連件遮羞的衣裳都燒光了，還拿什麼勾引你？","eff":{"love":null,"_lb":null,"rel":[[null,null,null]],"mood":null,"rumor":"{b}暖閣昨夜突遭詭異藍火焚毀大半，全宮皆知是九尾妖狐妲己痛下殺手！"}}],"絕對":[{"d":"即便黑霧壓城、叛亂四起，妲己依然笑得傾國傾城，仰頭含了一口加了秘藥的烈酒直接渡進你唇中，與你在滿城哭嚎火光裡肆意交歡。","say":"管他什麼正統大義、管他什麼萬世罵名！夫君骨頭裡早滲滿了奴家的妖毒，咱們一起把這世界玩爛罷！","eff":null},{"d":"妲己將一顆跳動著血光的青丘妖丹重重按在你心口，琥珀妖瞳燃起毫無悔意的極致狂熱。","say":"別做夢想把我洗白成賢妻良母。我天生便是禍國妖狐，而你，是我親手養成的暴君夫君！","eff":null}]},"mood":null,"react":{"pamper":["嘻嘻，這才像我最愛的暴君夫君嘛！今晚咱們把酒池注滿，誰敢勸諫就拉去炮烙！","再多縱容奴家一點嘛～越殘忍越荒唐的男人，奴家越愛得發瘋喔！"],"scold":["罵我殘忍？罵我禍水？咯咯，夫君昨夜壓在奴家豐乳上喘氣時，怎麼不嫌奴家毒辣呀？","少拿凡人那套破道德教訓青丘九尾狐！我天生愛看血流成河，這輩子絕不悔改！"],"ignore":["不理奴家？好呀，那我今晚就去偏院點把狐火、抓幾個宮婢玩炮烙解悶囉！","夫君越冷落我，這城裡莫名其妙橫死的人就越多喔～你猜下一個輪到誰？"],"punish":["禁足？哼，關得住本姑娘的殿門，關不住我放出去的狐火與毒蛇！","夫君竟為了那群賤民罰我？看來你墮落得還不夠徹底呢，真掃興。"],"forgive":["我就知道夫君終究戒不掉這溫柔魔窟！來，別裝正經了，快張嘴喝這杯酒！","原諒？奴家從不覺得自己做錯半件事，不過是夫君終於想通了罷了～"],"other":["剛從{b}那無趣木頭房裡出來？她能陪你玩酒池肉林、能讓你這麼銷魂發軟嗎？","你儘管寵她，等哪天她莫名其妙毀了容、失了魂，可別怪奴家手滑喔！"],"caught":["（被撞破私設炮烙或放火害人，笑得天真又毒辣）對呀，就是奴家幹的！聽她們皮焦肉爛滿地打滾多好玩呀～要罰便罰，反正下回我還敢！","承認了又怎樣？你捨得為了幾個無趣凡人殺了你的心肝九尾狐嗎？"],"win":["咯咯，仁義禮法終究敵不過慾望與鮮血！今晚不醉不歸！","贏啦！快下旨加徵酒肉稅，咱們狂歡三天三夜！"]}},"xiaji":{"desire":"在無數權貴男人的瘋狂搶奪與浴血廝殺裡永保不老青春與極致自由，看著他們為自己反目、發瘋、亡國。","fear":"被單一男人關進無趣的貞節牢籠裡、喪失對天下男人的致命誘惑，淪為枯槁尋常的深宮婦人。","pride":"春秋第一絕代尤物，身懷採補駐顏房中秘術，老而復壯，歷經「殺三夫一君一子，亡一國兩卿」仍令諸侯大夫搶破頭。","face":"慵懶微醺、媚骨天成、眼波似水，不必刻意討好，光是輕撩薄紗露出雪白肩頸便足以讓朝堂重臣魂飛魄散。","back":"看透男人色慾本質的冷血享樂者。她從不認自己禍國，反而樂於在君王、重臣與外邦敵酋之間分贈貼身赤紅汗衫，冷眼看這群野獸為她拔刀互殺。","loveWay":"用世間最銷魂蝕骨的房中秘術與不老胴體讓你徹底上癮，同時毫無遮掩地提醒你：全城還有無數男人在排隊等她垂青。","hateWay":"根本懶得與後宮女人撕扯；只需她對某位迷戀自己的兵部將領或權臣輕嘆一口氣，便有人替她把情敵的靠山全抄了。","scheme":"以絕色肉身與貼身衵服、香帕作餌，同時釣死君王與數名實權大夫，讓整個朝堂因爭風吃醋徹底崩壞。","weak":"她絕不會為愛斬斷外緣、更不會替亡國懺悔——「男人自己管不住褲腰帶發瘋互砍，關奴家夏姬什麼事？」","heart":{"相愛":["這座燈塔的男人表面個個一本正經，昨夜宴上卻有三個將軍盯著奴家胸前深溝連酒都灑在衣襟上，咯咯。","夫君的體魄倒真強悍，昨夜採補起來陽氣醇厚得教人發顫——瞧我這肌膚越發滑嫩如玉了。","那兩位常來議事的年輕大夫眼神燙得像要吃人，改日賞他們每人一件貼身紅汗衫，看他們明早上朝怎麼炫耀～"],"迷戀":["夫君吃醋發狠的模樣真帶勁，像極了當年陳靈公……不過你比他威猛持久多了。","城外鄰邦敵酋派使者來，開出的退兵條件竟是要我夏姬？呵呵，男人爭江山，說到底不過為了搶女人。","{b}整日在背後罵我「剋夫老妖婦」？真可憐，她連讓一個男臣為她拔刀的本事都沒有呢。"],"深愛":["奴家承認，歷經三夫一君，你是唯一讓我動了幾分真心的男人。但想叫我收起這身勾魂手段？做夢喔。","既那兩名前朝大夫為了奴家拔劍相向，就讓他們砍罷！活著贏下來的那個，才配替夫君和我賣命嘛。","我越迷戀與你在榻上翻雲覆雨，就越愛看你在滿朝醋火血腥裡死死抱緊我不肯撒手的瘋狂模樣！"],"沉淪":["昨夜兵部重臣與戶部侍郎又翻牆摸進我偏苑，兩人為了搶我一件穿過的赤紅汗衫差點在廊下抹脖子——蠢得真可愛。","夫君若真恨我招蜂引蝶，怎麼不把那些盯著我胸臀發呆的文武百官全宰了？殺得越多，才越像當年陳國呀～","那個罵我淫亂朝綱的老御史？哼，不用奴家動手，明早自有為我神魂顛倒的將軍替我砍掉他的腦袋。"],"病態":["把奴家的貼身赤紅衵服穿在朝服裡面去上朝罷，夫君！讓你和那兩位大夫在正殿上比比誰昨夜最銷魂，活活氣死那群清流！","三夫一君一子算什麼？只要這歸墟裡還有喘氣的雄主與猛將，夏姬便永遠是引爆他們互殺的火種！","你越想把我鎖進深宮獨佔，我就越要在你眼皮底下向敵酋與大夫拋媚眼——來呀，替奴家殺出一條血路！"],"絕對":["世人罵我亡一國兩卿，可從頭到尾奴家動過半寸刀鋒嗎？是你們男人自己為了這副皮囊發瘋、流血、亡國！","這輩子你既敢把夏姬迎進暖閣，就別妄想我洗白守貞。愛我，便做好為我與滿朝反目、再亡一國的覺悟！","就算明日城破火起，我夏姬照樣笑著走進下一個贏家懷裡——除非，你把這世上所有比你強的男人都殺絕！"]},"act":{"相愛":[{"d":"夏姬在暖閣燃起秘製駐顏香，解開紅紗以春秋採補房中術替你調理陽氣，極盡妖嬈纏綿，令你徹夜沉淪、差點誤了早朝。","say":"夫君的陽氣真滾燙……採補得奴家渾身酥軟，肌膚又嫩了三分呢。","eff":null},{"d":"夜宴席間，夏姬故意將一條染滿花露體香的貼身絲帕滑落在兩名前朝實權大夫腳邊，引得兩人當場紅眼暗自較勁。","say":"哎呀，帕子掉了，兩位大人別搶嘛～回頭奴家一人再繡一條貼身戴過的就是。","eff":{"love":null,"energy":null,"rumor":"聽說兩名實權大夫為爭搶夏姬遺落的貼身香帕，在宴席外險些拔刀互砍！"}}],"迷戀":[{"d":"早朝正殿爆出驚天醜聞——兩名實權重臣竟同時把夏姬賞賜的貼身赤紅衵服露在朝服領口外，當著滿朝文武公然炫耀昨夜風流！","say":"（事後赤足斜倚榻上輕笑）不過賞了兩件貼身舊汗衫當念想，誰知道男人這麼愛顯擺呀？夫君不會連這都要氣罷？","eff":{"love":null,"pop":null,"energy":null,"rumor":"朝綱徹底崩壞！兩名重臣竟穿著夏姬的貼身紅汗衫在正殿互相炫耀，清流老臣氣得當場昏倒！"}},{"d":"一名剛直御史在殿上痛斥夏姬淫蕩亡國，當夜便遭迷戀夏姬的巡城偏將暗殺於巷口，夏姬聞訊只掩唇嬌笑。","say":"嘴這麼臭的老頭，本來就活不長嘛。又不是奴家拿刀捅的，夫君別冤枉人家喔。","eff":null}],"深愛":[{"d":"城外強敵遣使遞來戰書，竟指名道姓要求交出「絕代尤物夏姬」換取退兵，否則踏平燈塔！城中諸將為保她還是交她徹底撕破臉。","say":"咯咯，奴家的芳名連黑霧外頭都傳遍啦！夫君，你是要把奴家送人換太平，還是為我打一場亡國之戰呢？","eff":{"love":null,"energy":null,"rumor":"紅顏禍水再現！外敵大軍壓境竟只為搶奪夏姬，城中諸將爭執得幾近火拚！"}},{"d":"夏姬看{b}不順眼，僅在酒宴上對一名仰慕自己的兵部大將輕輕嘆了口氣，隔日{b}一系在城中的商號與親信便全遭莫須有罪名抄沒。","say":"男人搶著替奴家出氣，人家也攔不住呀，妹妹別哭花臉嘛～","eff":null}],"沉淪":[{"d":"你臨時折返株林暖閣，竟撞見夏姬與兩名實權大夫在暖池邊衣衫半褪共飲調笑，活脫脫重演當年陳國「三男一女」荒唐醜劇！她見你破門而入非但不慌，反而媚笑招手邀你同樂。","say":"夫君來得正好，這兩位大人正誇奴家花戶緊緻、比當年陳國還銷魂呢～要不要脫衣一起進池子喝一杯？","eff":{"love":null,"pop":null,"energy":null,"rumor":"荒唐至極！夏姬在株林暖閣公然與兩名大夫半裸共飲，重演春秋陳國亡國醜劇！"}},{"d":"兩名迷戀夏姬的守城大將因爭風吃醋在軍營拔刀火拚，釀成數十名精銳死傷、北門防務一度洞開！","say":"男人本就是管不住刀劍也管不住下身的野獸，死幾個算什麼？","eff":null}],"病態":[{"d":"夏姬故意在晚宴上當眾拿你與前朝情夫的房中功夫互相評比打趣，瞬間引爆兩名重臣拔刀兵變衝進偏殿，險些重演當年夏徵舒射殺陳靈公之血案！","say":"哈哈哈哈！砍起來了！看他們為了奴家這副身子流血拚命，這才叫活著的滋味呀！","eff":{"love":null,"hp":null,"energy":null,"pop":null,"mood":null}},{"d":"夏姬冷眼看著滿城因她而起的血光與動盪，赤足踏過碎裂酒盞跨坐上你膝頭，指尖輕挑你下頜。","say":"夫君，如今明白什麼叫「亡一國兩卿」了罷？這座孤城，你壓得住嗎？","eff":null}],"絕對":[{"d":"在內憂外患、諸將互相殘殺的血紅夜色裡，夏姬披著一件幾乎全透的赤紅薄紗立於城樓迎風狂笑，將你緊緊拉進懷裡獻上致命深吻。","say":"三夫、一君、一子、一國、兩卿……現在輪到你這座歸墟燈塔啦！別妄想我為你收心悔改，要嘛踩著所有情敵屍首永遠壓住我，要嘛就陪我一起亡國！","eff":null},{"d":"夏姬將剛從身上脫下、尚帶著滾燙體溫與濃香的赤紅衵服塞進你懷中，眼波流轉透出毫無底線的危險魔力。","say":"這件只給你一個人穿去上朝。至於奴家明早會不會再替別的將軍繡一件……全看夫君今晚在榻上的本事囉～","eff":{"love":null,"mood":null}}]},"mood":null,"react":{"pamper":["嘻嘻，夫君這般迷戀奴家，小心哪天也像陳靈公一樣忘了防備身後冷箭喔～","只要你永遠是這座城裡最兇最強的男人，奴家自然多留幾夜在你榻上。"],"scold":["罵我淫蕩禍國？哈哈，當初是誰自己把持不住把夏姬迎進帳裡的？如今倒怪起女人來了？","赤紅汗衫是我賞的，酒是我陪他們喝的，但拔刀自相殘殺的是你們男人自己，奴家何罪之有！"],"ignore":["冷落奴家？正好，兵部與戶部那幾位大人早就排隊想進株林暖閣陪我品酒解乏呢！","夫君慢慢批章疏罷，奴家可從不缺搶著爬床的男人～"],"punish":["禁足？廢妃？你鎖得住奴家這扇門，鎖得住外頭為我發瘋的將領與敵酋嗎？","罰罷，反正哪天這座城破了，自有新君主用八抬大轎來迎我夏姬出去！"],"forgive":["呵呵，我就知道天下男人到頭來都戒不掉這具身子。來罷，別裝正人君子了。","原諒？奴家從頭到尾可沒覺得自己錯了半寸呢～"],"other":["{b}那種無趣木頭美人，夫君睡兩夜就會膩的。最後還不是得乖乖爬回株林求奴家？","去陪她罷，正好空出今夜，讓奴家見見那位生得極俊的外邦使節。"],"caught":["（被撞破與朝臣私通或分贈汗衫，連鬆開的紅紗都懶得拉好，慵懶冷笑）撞見又如何？當年陳靈公與兩位大夫還同穿奴家的衵服上朝呢！是你們男人自己下賤貪心，憑什麼要我夏姬懺悔？！","要殺便殺！反正殺了我，史書上也只會笑你天運者連一個女人都馴服不了！"],"win":["咯咯，世上最利的兵刃從來不是刀劍，而是奴家這副不老身子！","贏啦！快溫烈酒，今晚奴家賞夫君一個最銷魂蝕骨的長夜～"]}},"liji":{"desire":"以最溫柔無害的枕邊哭訴徹底操縱你的喜怒與猜忌，斬絕所有擋在自己與所出登頂路上的忠良、庶長子與正宮。","fear":"溫婉假面被徹底撕碎、失去你對她的盲目信任，重演當年晉國政變後遭里克反撲慘死的下場。","pride":"春秋頂級心理操縱大師，僅憑一場「夜半而泣」與一塊毒胙肉，便讓英明的晉獻公親手逼死仁厚太子申生、趕走重耳夷吾。","face":"溫婉柔順、楚楚可憐、說話永遠輕聲細語，甚至常常主動「替情敵與忠臣求情」，看似全後宮最善良柔弱的解語花。","back":"笑裡藏刀的極致偽善者與政變操盤手，更暗與樂師優施通姦合謀。她的每一次落淚、每一句「求夫君饒過她」皆是算準人心的致命陷阱。","loveWay":"用溫柔與眼淚替你織起一座密不透風的謊言繭房，讓你深信天下皆欲叛你，唯有她驪姬永遠忠誠溫順。","hateWay":"從不親手拿刀沾污素裙——她先在你面前極力捧殺情敵與忠臣「深得民心、寬厚仁慈」，再暗中在祭肉補湯裡下毒嫁禍，讓你自己發瘋賜死他們！","scheme":"「捧殺＋夜半而泣＋毒肉嫁禍」連環心理殺局：先點燃帝王疑心，再佈下無法辯白的鐵證，最後含淚求情把你的殺意推至頂點。","weak":"演技已達化境；縱使偶爾被你戳破，她也能瞬間反客為主哭成淚人或直接亮出共犯鐵證。骨子裡冷血透頂，絕無半分悔改。","heart":{"相愛":["男人最吃「溫柔示弱」這套。賈南風與呂雉動輒揮刀打殺太蠢了——借夫君自己的手殺人，才最乾淨。","今日朝會上那位年輕將領甚得民心？甚好，今晚我便在枕邊好好「誇誇」他有多寬厚仁慈、百姓多擁戴他。","只要在帝王骨頭裡種下一顆猜忌的刺，根本不必我拔刀，它自己就會長成絞死忠良的麻繩。"],"迷戀":["夫君對我越深信不疑，這場心理操縱就越得心應手……有時連我自己都快迷上這副聽話的傀儡明主了。","{b}近來極得主母與城民稱讚？今晚三更，正是演一場「夜半而泣」的好時辰。","越是誇她賢德、越是哭著說「是我配不上夫君、不如早點賜死我免得亂國」，夫君的心就會越狠地倒向我。"],"深愛":["我承認迷上了你這個人——所以我更要把你身邊所有「好人」全清乾淨！唯有你孤家寡人、眾叛親離時，你才會永遠只信我驪姬一人！","明日大祭的胙肉已叫優施暗中抹了慢毒。只要說是{b}親手呈上的，她長一百張嘴也洗不清「毒殺君王」的死罪！","看著你親手處死最忠心的部下、流放最賢良的夫人，再回頭縮進我懷裡尋求慰藉……世上哪有比這更銷魂的深情？"],"沉淪":["第一步捧殺，第二步夜泣，第三步毒肉嫁禍……夫君果然一步不差踩進了我的網裡呢。","那忠臣臨死前還在喊冤？嘻嘻，我得趕緊去夫君面前哭一場、替他「說兩句好話」，好叫夫君覺得自己殺得天經地義、更憐惜我的善良。","這後宮誰敢威脅我將來孩兒的儲君之位，我便用最溫軟的眼淚，把她們一個個逼上自盡絕路！"],"病態":["你的眼只能看我給你看的世界，你的耳只能聽我餵給你的真相。忠臣全想篡位，賢妻全想毒死你，唯有驪姬永遠忠誠！","只要把這座孤城攪成昔日晉國般的漫長內亂、教滿朝文武人人自危，你這輩子便再也離不開我的枕邊細語了！","就算哪天你終於查出毒肉是我下的、夜泣是我演的……你雙手早沾滿冤魂鮮血，你回得去嗎，夫君？"],"絕對":["我是世上最溫柔的解語花，也是世上最冰冷的毒蛇。你越愛我，我就把這張心理殺網織得越密、越教你萬劫不復！","叫我悔改？哈哈，若我真成了愚蠢良善的蠢婦，誰替夫君「清理」這滿朝滿宮的絆腳石？","別怕，刀依然握在夫君掌裡，由我輕輕扶著你的手腕，一刀一刀斬斷你所有的退路罷。"]},"act":{"相愛":[{"d":"深夜暖閣，驪姬忽然伏在你胸口無聲抽泣，你再三追問下，她才「勉為其難」大讚{b}與某位忠臣「寬厚仁慈、甚得民心」，話鋒一轉卻哭求你早日賜死自己。","say":"（淚眼盈盈，柔腸寸斷）{b}妹妹與將軍如此受城民擁戴、勢大難制，妾身真怕哪日生變……不如夫君早些殺了妾身，免得世人罵我以一妾亂國！","eff":{"love":null,"_lb":null,"rel":[[null,null,null]],"mood":null}},{"d":"驪姬在晨昏定省時對{b}極盡卑微禮讓，卻在無意間當眾流露「夫君近來對{b}妹妹似有忌憚」的暗示，輕易挑起六宮恐慌。","say":"妹妹千萬別多心，許是夫君政務太忙才冷落妳的罷……","eff":{"love":null,"rel":[[null,null,null]],"_mb":null}}],"迷戀":[{"d":"你日前因驪姬枕邊風對一位功勳卓著的忠將起了疑心。驪姬見狀竟主動跪地「替將領求情」，字字句句卻暗指對方手握重兵、軍中只知將軍不知君主！","say":"將軍雖功高震主、軍心盡歸於他，但妾身相信他絕不會謀反的……夫君千萬別殺他呀！","eff":{"love":null,"energy":null,"pop":null,"rumor":"天運者突生猜忌削奪功臣兵符，前朝譁然，全不知背後是驪姬的枕邊「求情」！"}},{"d":"驪姬暗中將{b}送進書房的滋補糕點換成發霉變質之物，卻在你面前大度替{b}遮掩，反倒讓你認定{b}對你滿腹怨懟敷衍。","say":"妹妹許是忙昏了頭才沒留意糕點壞了，夫君萬別責罰她，妾身吃這塊好的便是。","eff":null}],"深愛":[{"d":"【毒肉嫁禍】大祭禮成後，{b}按例呈上祭祀胙肉與美酒。驪姬先假意勸你試毒——銀針一探竟瞬間發黑、餵狗即斃！驪姬當場花容失色跪地痛哭，將「毒殺君王」死罪死死扣在{b}頭上！","say":"（泣不成聲）天哪！{b}妹妹怎會狠心在祭肉裡下劇毒害夫君？！若非妾身多心驗了一下，今日便要天人永隔了……","eff":{"love":null,"_lb":null,"rel":[[null,null,null]],"_mb":null,"rumor":"驚天「毒胙肉案」！{b}呈上的祭肉竟驗出劇毒，六宮大駭，無人知是驪姬中途親手灑的毒！"}},{"d":"你猶豫著如何處置遭陷害的忠臣或{b}，驪姬半夜再度伏進你懷裡「夜半而泣」，忽擒忽縱地將你的帝王殺機徹底點燃。","say":"夫君若心軟放過他們，明日死在亂刀之下的便是夫君與妾身啊……嗚嗚，我好怕……","eff":null}],"沉淪":[{"d":"在驪姬一連串天衣無縫的離間局下，你麾下兩員忠心耿耿的核心大將竟被迫連夜出逃流亡荒原（如昔年重耳夷吾出奔）！驪姬聞訊卻仍滿臉無辜地替你溫茶。","say":"他們既心虛逃竄，可見當初確懷鬼胎。夫君別難過，有驪姬守著你便夠了。","eff":{"love":null,"energy":null,"pop":null,"rumor":"兩員核心忠將疑遭誣陷連夜流亡出逃，軍心大亂，清流暗指驪姬乃幕後毒手！"}},{"d":"驪姬私自走到被你禁足的{b}殿門外，隔著門縫用最柔婉的嗓音細數自己如何三言兩語毀掉{b}的一切，逼得{b}在殿內幾欲崩潰自盡。","say":"妹妹別怪姐姐心狠，要怪只怪妳太蠢，不懂怎麼玩弄帝王的心呀。","eff":{"love":null,"_lb":null,"rel":[[null,null,null]],"_mb":null}}],"病態":[{"d":"你意外截獲驪姬心腹樂師優施的密信，赫然查實「夜半而泣」與「毒肉嫁禍」全出自兩人合謀！當你持信逼問時，她竟瞬間淚如雨下、反客為主演出一場驚世苦情戲。","say":"（哽咽緊抱住你）信是我叫優施寫的，毒是我親手灑的……可我不除掉他們，他們得勢頭一個就要殺我！夫君，你雙手早沾滿他們的血，咱們是一條船上的共犯，你捨得殺我嗎？","eff":{"love":null,"pop":null,"mood":null}},{"d":"驪姬借你對滿城的疑懼，徹底接管書房密探與繼承人選的生殺大權，將這座孤城變成了一座人人自危、互相告發的猜忌牢籠。","say":"除了驪姬，這世上沒有第二個人值得夫君交付真心。記牢了嗎？","eff":null}],"絕對":[{"d":"朝野因冤案頻傳徹底震盪，昔日忠臣與被逼出逃的舊部正集結反撲。驪姬卻在昏暗紅燭下溫柔替你繫上戰袍衣帶，眼底滿是徹底鎖死你的病態饜足。","say":"如今全天下都背叛你、罵你昏暴了——真好，這樣你的世界裡便只剩下我驪姬一人。我從不後悔毀掉他們，重來十回，我照樣為你演這場「夜半而泣」！","eff":null},{"d":"驪姬親手將一盞清茶與一份擬好的「前朝清洗名冊」推到你案前，唇角揚起世上最溫軟也最陰毒的微笑。","say":"名冊上剩下這幾個人也都對夫君不忠呢。今晚，咱們先從哪一個下手？","eff":{"love":null,"mood":null}}]},"mood":null,"react":{"pamper":["夫君這般信重妾身，驪姬便安心了……對了，方才聽聞{b}妹妹在宮外似乎頗得民心呢（柔聲微笑）。","有夫君護著，妾身什麼都不怕，哪怕外頭罵我是禍國毒蛇也甘願。"],"scold":["（瞬間眼眶紅透、梨花帶雨地屈膝跪下）是妾身多嘴了……妾身只是怕夫君遭小人暗算，既覺我在挑撥離間，不如現在便賜死我罷！（低頭瞬間眼底冷如寒冰）","夫君今日為了外人喝斥我，來日若真遭他們逼宮反叛，莫忘了妾身曾苦苦提醒過您。"],"ignore":["（垂眸輕嘆，極具壓迫感地柔聲低語）夫君連聽妾身說句體己話都不願麼？看來{b}妹妹在書房吹的枕邊風，確實比我管用呢。","無妨，妾身自己回房給優施寫封密信，商議商議該怎麼替夫君「分憂」便是。"],"punish":["禁足？夫君竟信了那幫奸佞讒言罰我？（含淚柔聲）好，我領罰……只是這幾日沒我替您試毒，夫君千萬留神別飲了別殿送來的毒茶。","關得住我的身子，關不住這後宮早埋好的暗雷。夫君等著看好戲罷。"],"forgive":["我就知道夫君明察秋毫，終究會看清誰才是真心為你著想的。（唇角微不可察地勾起冷笑）","謝謝夫君肯再信我。既已冰釋前嫌，不如順手把剛才那份處置{b}的旨意蓋上印罷？"],"other":["{b}妹妹真是難得的賢良之人呢，連前朝幾位手握重兵的將軍都對她讚不絕口……夫君娶到她真是福氣，只是不知為何，妾身聽著總覺心慌。","夫君多去陪陪{b}妹妹也是該當的，免得她怨氣鬱結，做出什麼對夫君不利的糊塗事。"],"caught":["（被徹底戳穿毒肉嫁禍與夜半而泣，先試著擠淚裝無辜，見騙不過便冷靜拭乾淚痕露出冰冷傲笑）看穿了？也好，整日裝這副楚楚可憐的模樣我也演膩了。沒錯，毒肉是我下的、流言是我放的、忠臣也是我借你的刀殺的——可我絕不悔改！","罵我毒辣？若非你自己骨子裡多疑自私，我驪姬這兩滴眼淚怎麼可能撬得動你的刀？！我們天生就是一對共犯！"],"win":["（溫婉福身，眼底盡是操盤全局的冷笑）塵埃落定，夫君的江山總算又清淨幾分。","除掉了心腹大患，今夜妾身親自撫琴寬衣，替夫君好好壓驚罷。"]}}},"valTalk":{"jiananfeng":{"favHi":"哼，總算遇上個不看皮囊、只服本宮鐵腕的男人！誰敢動你，我夷他三族！","favLo":"（冷笑捏緊短戟）躲著本宮去睡那些年輕狐狸精？好啊，看明早是誰的腦袋先落地！","infHi":"前朝後宮的生殺大權盡在椒房殿掌中，如今連百官見了本宮都不敢抬頭喘氣！","infLo":"虎落平陽罷了！你今日奪我兵權卻不殺我，明日我便教你見識什麼叫八王之亂！","ambHi":"區區皇后算什麼？本宮要的是把整座燈塔的玉璽、兵符與生殺全踩在腳底下！","rankUp":"本就該是本宮的位子，順我者昌、逆我者死！","rankDown":"（雙目赤紅暴怒）敢降本宮位分？！今晚我就矯詔把替你出主意的狗賤奴全抄家！","hedonHi":"男人三宮六院，本宮用大木箱抬幾個白淨少年進殿解悶、喝完烈酒再滅口，多痛快！","tyrannyHi":"誰敢笑我醜、誰敢懷胎爭儲，我親提短戟砸爛她肚子、夷她滿門，血越多越痛快！","bothHi":"醜毒淫虐又怎樣？殺盡反對者、享盡天下樂，這座血城本就是惡后的樂園！"},"daji":{"favHi":"咯咯，夫君眼裡只剩奴家這條九尾狐啦？今晚咱們就在酒池裡赤身狂歡到天明！","favLo":"喲，裝起正人君子冷落奴家了？無妨，過兩日你就會像餓狼般自己爬回鹿臺求我的～","infHi":"滿朝奸佞全跪在鹿臺腳下搖尾乞賞呢，這座孤城很快就要變成第二座朝歌囉！","infLo":"權勢掉光又如何？只要我這副狐媚雪肌與九尾還在，勾勾手指就能再把這城攪翻！","ambHi":"奴家要讓整座城池、所有禮法與清流忠臣，全跪伏在九尾狐的裙擺與炮烙火光下！","rankUp":"晉位好呀，這樣奴家從國庫搬黃金釀酒鑿池就更名正言順啦～","rankDown":"（粉舌舔過紅唇妖笑）降我位分？夫君想玩懲罰小妖精的新花樣嗎？那奴家可要加倍作亂囉！","hedonHi":"酒池肉林、白晝宣淫、通宵達旦！人生苦短，不徹底墮落簡直白活一場嘛～","tyrannyHi":"聽著那些臭清流在燒紅銅柱上慘嚎下酒，比世上任何絲竹都動聽十倍呢！","bothHi":"荒淫無度配炮烙蠆盆！哈哈哈哈，夫君，咱們天生就是燒毀這世間禮法的絕世魔星！"},"xiaji":{"favHi":"夫君這副為奴家神魂顛倒的模樣真銷魂～今晚把春秋房中採補秘術全使出來報答你喔！","favLo":"冷落奴家？無妨，兵部與戶部那幾位穿著我赤紅汗衫的大人，可日日盼著進株林暖閣品酒呢。","infHi":"不需要虎符官印，只要滿朝男人都為奴家發瘋，這座燈塔便有一半歸我說了算！","infLo":"一時失勢有什麼好怕？男人永遠管不住下身，不出三旬，奴家照樣叫他們搶破頭！","ambHi":"三夫一君一子、一國兩卿……奴家倒想瞧瞧，能不能讓這座歸墟燈塔也為我顛倒眾生！","rankUp":"咯咯，位分越高，前朝那些大人盯著奴家胸臀的眼神怕是要更滾燙、更瘋狂囉～","rankDown":"降我位分就能鎖住男人的色慾嗎？天運者，你未免太天真了呢。","hedonHi":"人生苦短，除了駐顏採補、醉生夢死與看男人為我爭風吃醋，還有什麼值得留戀？","tyrannyHi":"誰敢罵我是剋夫老妖婦、誰敢擋著奴家勾魂，直接借仰慕者的刀把她全家屠光便是！","bothHi":"一面株林夜宴荒淫無度、一面看全城男人為我自相殘殺——這才配得上春秋第一禍水！"},"liji":{"favHi":"（柔婉微笑，眼底藏著冰冷算計）承蒙夫君如此信重，妾身今夜定再替您細細分辨朝中忠奸。","favLo":"（垂淚輕嘆）夫君疏遠妾身，定是旁人在耳邊進了讒言……但願沒我提醒，夫君莫遭笑面虎暗算。","infHi":"優施的暗網早已鋪滿前朝後宮，誰忠誰反，如今全憑妾身在夫君枕邊一句話定生死。","infLo":"（拭去假淚冷笑）一時失勢無妨，只要猜忌的毒根還扎在夫君骨裡，隨時能再借刀殺人。","ambHi":"妾身要除盡所有阻礙我與所出登頂的忠良與庶子，讓這座孤城只剩夫君與我這對共犯！","rankUp":"謝夫君厚愛。位分越高，妾身替您「清理」朝堂隱患時便越名正言順了。","rankDown":"（楚楚可憐落淚）妾身甘願受罰，只怕前朝野心之徒見我失勢，明早便要趁機逼宮啊……","hedonHi":"朝政太磨人了，夫君只管在晉陽暖閣飲酒享樂，前朝清洗名冊交給妾身擬定便是。","tyrannyHi":"捧殺、夜半泣、毒肉嫁禍——看著忠良一個個冤死在夫君刀下，這滋味真教人沉醉。","bothHi":"昏庸到荒廢朝綱、暴虐到殺絕忠良……夫君，這便是驪姬親手為您雕琢的末世傑作呀。"}},"inter":{"act":{"jiananfeng":{"walk":["陪本宮在禁苑散步？也好，正好順路瞧瞧哪個宮婢敢偷瞄我眉間的瘤！","把閒雜人等全清出去，本宮最厭煩走路時聽見那群狐狸精嬌笑。"],"meal":["這道炙鹿肉火候尚可——來人，先把廚子拉來試毒，沒咽氣本宮再動筷。","用膳配抄家名單才下飯，夫君快陪本宮滿飲這碗烈酒！"],"art":["附庸風雅有什麼意思？不如本宮當場擲一段短戟，教那群清流嚇破膽！","琴棋書畫全是弱者玩的把戲，矯詔殺人術才是世上最高明的技藝。"],"dress":["給本宮換那件玄黑鑲金鳳袍！別拿那些粉嫩嫩的料子來襯本宮青黑膚色！","多塗一層西域濃粉，只要殺氣壓死六宮，誰還敢多瞄本宮的臉？"],"drill":["校場這群兵太鬆懈！先斬三個偷懶偏將祭旗，保證明日個個兇如餓狼！","瞧見本宮這手擲戟準頭沒？三十步內，想砸誰的肚子就砸誰！"],"court":["議政殿那幾個老東西又在廢話，夫君別攔著，讓本宮直接矯旨夷他們三族！","這份調兵詔書本宮改過了，如此一來，中樞兵權才算真正牢靠。"],"tour":["出城巡視？多帶東宮死士，順手把城外幾個不聽話的豪強全抄家充庫！","這群流民長得真礙眼，多派苦役叫他們去扛石頭，省得閒出反心。"],"comfort":["收起這套哄小丫頭的軟話……哼，罷了，唯獨你這雙手本宮不討厭，再多抱一會兒。","本宮從不委屈，我只會記仇——你若真想哄我，明早便把{b}的月例全扣了！"]},"daji":{"walk":["陪奴家在禁苑走走，花兒見了青丘九尾都羞得低下頭呢，夫君說是罷？","只要牽著夫君的手，連這凡間小小花廊都比青丘仙境還教人流連。"],"meal":["這炙肉肥嫩流油，夫君快張嘴——唔，唇角沾了油光，讓奴家替你舔乾淨？","跟夫君同席吃肉喝酒最香甜啦，往後日日都要這樣陪奴家喔！"],"art":["想看青丘九尾的赤紗幻火舞嗎？今晚這場絕技，只跳給夫君一個人看！","別眨眼喔，奴家這雙妖瞳與腰臀擺動，保準把夫君的三魂七魄全勾走～"],"dress":["夫君替奴家畫眉時湊這麼近，呼吸好燙，教人忍不住想咬你一口呢。","這支赤金步搖真襯奴家的紅紗裙！夫君挑首飾的眼光越來越合我心意啦。"],"drill":["跟九尾狐切磋？夫君確定扛得住奴家的媚眼與狐火嗎？嘻嘻～","揮刀舞劍多乏味呀，不如咱們在榻上比比看誰先喘不過氣好不好？"],"court":["前朝那幫老頑固真囉嗦，要不要奴家暗中替夫君施點毒計全送進蠆盆？","只要是夫君想辦的事，無論正道陰招，奴家都替你辦得漂漂亮亮！"],"tour":["出城撒野最痛快啦！荒原風大靈氣足，夫君快陪我去山崗吹風！","跟著夫君踏遍這片歸墟，凡是你想佔的地方，奴家都陪你燒過去！"],"comfort":["哼，誰敢惹青丘老祖宗不痛快……不過既是夫君親自來哄，就饒這世道一回罷。","別鬆手……把臉埋在你胸膛聞著你的陽氣，奴家心裡才不會空落落的。"]},"xiaji":{"walk":["陪奴家去禁苑走走呀？小心巡邏的年輕將軍們看直了眼，忘了站崗喔～","這花廊景致雖美，可惜不及奴家輕撩紅紗時教全城男人移不開眼呢，咯咯。"],"meal":["這壺駐顏花酒奴家親口溫過了，夫君快飲盡，今夜才有力氣應付奴家這副身子呀～","用膳何必坐得那麼死板？讓奴家跨坐你腿上親口餵果子，不是更銷魂嗎？"],"art":["奴家最擅長的才藝呀，是在酒酣耳熱時撥亂男人的心弦，看他們為了我拔刀相向！","這曲《株林》唱得多勾魂，夫君要不要學陳靈公陪奴家徹夜狂歌縱慾？"],"dress":["這件赤紅絲綢衵服最襯奴家雪肌了——夫君若喜歡，脫下來賞你穿在朝服裡如何？","穿那麼厚實多悶呀，薄紗半透才最能讓全城男人夜夜睡不著覺呢。"],"drill":["校場上滿是汗水與陽剛氣息……奴家往點將臺上一站，保準三軍將士為了博我一笑拚死殺敵！","那位年輕偏將的槍法真威猛有力，待會兒散場奴家得好好「賞」他一盞酒。"],"court":["帶奴家去正殿旁聽？咯咯，只怕半朝大夫都忘了奏事，光盯著奴家領口流口水囉！","哪位大人敢頂撞夫君？讓奴家朝他拋個媚眼，明早他就乖乖跪著聽話了。"],"tour":["出城巡視順便見見外邦使節罷，聽說敵酋開出重金想一睹夏姬雪顏呢！","分城駐軍將領個個血氣方剛，奴家去巡幸一趟，包管讓他們終生難忘。"],"comfort":["哄奴家再簡單不過啦——拿出把全城情敵全踩在腳底下的霸氣，今晚別讓奴家下床！","咯咯，夫君這副又氣又恨不得把奴家揉進骨頭裡的模樣，最教人心癢難耐了。"]},"liji":{"walk":["陪夫君在林間漫步最安靜了——對了，方才路過兵部時，妾身似見兩名將軍在暗處密談呢。","這禁苑看似花團錦簇，實則陰影裡藏滿毒草，妾身得替夫君一株株認清。"],"meal":["這盤炙肉妾身已用銀針試過三遍了，夫君放心用罷——至於別殿送來的點心，還是少碰為妙。","夫君多喝口安神湯，近來朝堂暗流洶湧，您可得保重龍體呀。"],"art":["妾身撫一曲《驪山幽怨》替夫君解乏，詞裡唱的正是君王誤信笑面虎忠臣的舊事呢。","優施新編了幾段諷刺權臣尾大不掉的樂詞，改日演給夫君瞧瞧如何？"],"dress":["妾身向來偏愛素雅衣裙，免得像某些姐妹那般招搖過市、惹前朝非議。","（柔聲微笑）夫君親手替我插上這支白玉簪，妾身就算背負千古罵名也甘之如飴了。"],"drill":["校場上將士們吶喊震天，看來領兵大將極得軍心呢……夫君得此良將，真是既欣慰又該留神。","兵符如同利刃，握在自己手裡是護盾，落在外人手裡可便是懸在頭頂的鍘刀了。"],"court":["夫君今日在朝堂上對那清流太過寬厚了，妾身真怕他日後串聯宗室逼宮呀。","這卷暗中查核百官忠誠的密冊妾身理好了，夫君夜裡慢慢過目便是。"],"tour":["出城巡視正好暗察各分城守將有無異心，妾身的驪戎密探早已先行摸底了。","城外百姓頌揚那位大將的聲音竟蓋過天運者……夫君聽在耳裡，心裡安穩嗎？"],"comfort":["（靠進你懷裡無聲啜泣）妾身哪敢委屈？只是太怕哪日遭小人構陷，再沒機會替夫君辨忠奸了。","只要夫君永遠只信驪姬一人的枕邊話，外頭罵我毒婦、蛇蠍，妾身全不在乎。"]}},"ask":{"jiananfeng":[{"q":"夫君說實話，若明日城中爆發八王之亂般的大動盪，你會不會把本宮推出去謝罪？","o":[["絕不交出，誰敢逼宮我陪妳一起夷他三族",null,"（陰鷙眼底頓時迸出狂喜）甚好！這才配做我賈南風的夫君！"],["若妳自己惹出滅城大禍，我只能顧全大局",null,"呵，男人果然靠不住！那本宮只好先下手把兵符全攥死！"],["別胡思亂想，只要有我在，沒人動得了妳",null,"哼，嘴上說得好聽，本宮等著看你日後表現！"]]},{"q":"前朝那位剛直太傅屢屢上書彈劾本宮干政，夫君打算怎麼處置他？","o":[["直接矯詔伏殺並夷其三族，永絕後患",null,"哈哈哈哈！痛快！今晚本宮親自替夫君斟血酒！"],["削去官職貶為庶人，留他一條老命",null,"留著禍根太心軟，遲早本宮自己派死士送他上路。"],["人家是忠臣直諫，妳自己收斂些",null,"忠臣？我看他是想踩著本宮的屍體當權臣罷！"]]},{"q":"倘若後宮有別的賤婢搶在本宮前頭懷上龍種，夫君待如何？","o":[["這座城的繼承人只認妳點頭的，其餘留不得",null,"（冷笑撫過短戟）聰明！省得本宮親自提戟去替她落胎！"],["都是我的骨血，誰敢動胎氣我絕不輕饒",null,"好啊！那咱們就比比，是你的宿衛快，還是本宮的短戟快！"],["先顧好眼前軍政，子嗣之事順其自然",null,"敷衍本宮？哼，我自己會盯死六宮每個女人的肚子！"]]},{"q":"聽說坊間都在傳本宮用大木箱偷載洛陽少年入宮，夫君信不信？","o":[["只要妳心裡最重的是權與我，私下解悶我睜一隻眼閉一隻眼",null,"哈哈，天運者果然有氣度！那幾個不中意的少年我已經處理乾淨了。"],["妳若真敢給我戴綠帽，我親手劈了木箱再辦妳",null,"（冷笑挑眉）好大的殺氣！我倒要瞧瞧你下不下得了手！"],["流言止於智者，我相信皇后自有分寸",null,"（嗤笑）信我？夫君有時還真是天真得可愛呢。"]]}],"daji":[{"q":"天下人人罵我是亡商禍國的九尾妖狐，你卻敢把我留在枕邊夜夜相擁。夫君，你就不怕哪天我也吸乾你的精氣、迷昏你的頭？","c":[["心甘情願被妳迷昏——只要妳這隻小妖狐這輩子也只纏我一人","（她九尾歡快輕擺，妖瞳瀲灩生波）咯咯，夫君這張嘴比青丘靈果還甜呢！",{"_aff":null,"love":null,"trait":null}],["妳既能替我燒絕敵軍、又這般銷魂解悶，我高興都來不及","哈哈，果然還是夫君最識貨，比那些酸儒有趣十倍！",{"_aff":null,"love":null,"trait":null}],["有星盤在手，妳若敢亂來，我自有手段鎮住妳","（她妖瞳微瞇，尾尖騰起赤火）喔？那夫君可得日夜睜大眼睛防著奴家囉。",{"_fa":null,"love":null,"trait":null}]]},{"q":"若有一日九幽深淵開出十倍靈氣誘我離去，夫君拿什麼綁住本姑娘？","c":[["拿我這條命與滿城燈火——外頭再亮，也沒有我被窩裡燙","（她怔了半息，隨即露出毛茸狐耳鑽進你懷裡）……不走不走，哪兒也不去，就黏死在你身上！",{"_aff":null,"love":null,"trait":null}],["妳敢跑，我便帶兵踏平九幽深淵再把妳綁回床榻","（她雙眸骤亮，笑得妖冶勾魂）好霸道！奴家最愛看夫君這副兇狠強搶的模樣！",{"_aff":null,"love":null,"trait":null}],["去留隨妳心意，我從不強留無心之人","（她臉色一沉，冷哼甩袖）好呀，涼薄凡人，那本姑娘隨時都能拍屁股走人！",{"_fa":null,"love":null,"trait":null}]]},{"q":"夫君老實交代，你更愛奴家溫軟撒嬌的模樣，還是張牙舞爪放狐火燒人的模樣？","c":[["對外放火殺敵護著咱們的城，關上門只對我妖媚纏綿，兩樣我都愛","（她嬌笑著勾住你脖頸貼上胸乳）貪心鬼！好啦，兩種樣子都只給夫君獨享！",{"_aff":null,"love":null,"trait":null}],["看妳放青丘狐火把敵營燒成焦炭最痛快，威風極了","那是自然！下回出征記得頭一個點奴家上陣！",{"love":null,"trait":null}],["自然是安分乖巧些好，別老給朝堂惹是非","（她撇嘴翻了個白眼）無聊透頂，你快跟那幫清流一樣迂腐啦！",{"_fa":null,"love":null,"trait":null}]]},{"q":"凡人壽數不過區區百年，而九尾天狐能活千載。夫君可曾想過，百年後丟下奴家一人該怎麼辦？","c":[["有這方星盤在，我定陪妳活到天荒地老，絕不留妳孤單","（她罕見收起嬉笑，雙臂死死勒緊你的腰）……一言為定，敢先死我就追進黃泉把你魂魄抓回來！",{"_aff":null,"love":null,"trait":null}],["別想那麼遠，先把當下每一夜都過得酒酣耳熱再說","說得也對！今朝有酒今朝醉，快來陪奴家飲個痛快！",{"love":null,"trait":null}],["生老病死乃天道常數，屆時妳回青丘便是","（她雪尾垂落，眼底寒光一閃）……原來你從沒打算陪奴家走到盡頭。",{"_fa":null,"love":null,"trait":null}]]}],"xiaji":[{"q":"世人皆罵我「殺三夫一君一子，亡一國兩卿」，夫君把奴家迎進宮來，當真不怕這座孤城也亡在我裙下？","o":[["能與春秋第一尤物共醉銷魂，就算再亡一國又何妨",null,"（眼波流轉大笑）這才叫真雄主！今晚奴家把壓箱底的採補秘術全使出來報答你！"],["陳靈公是自己庸懦無能，我駕馭得住妳這禍水",null,"咯咯，口氣好大！奴家倒要瞧瞧夫君今晚能撐幾個回合囉～"],["妳若敢害我亡國，我會先親手斬了妳",null,"好嚇人呀……可越是冷酷狠辣的男人，採補起來越銷魂呢。"]]},{"q":"前朝那兩名實權大夫為了爭奴家一件舊紅汗衫差點拔劍，夫君打算怎麼處置？","o":[["誰贏了便賞誰升官，看男人為妳流血最下酒",null,"哈哈哈哈！夫君真是越來越懂奴家的樂趣啦！"],["把兩個蠢貨全貶去邊城，妳的貼身汗衫只能給我穿",null,"喲，吃醋啦？那這件新繡的赤紅衵服只給你一人穿囉～"],["全怪妳四處留情惹禍，自己回殿禁足思過",null,"切！男人自己管不住下半身，倒又把黑鍋往奴家頭上扣！"]]},{"q":"夫君說句實話，若城外敵酋願拿三座富城換奴家一人，你換不換？","o":[["給十座城池也不換！全天下男人都別想碰妳一根指頭",null,"（嬌笑貼進你懷裡）嘴真甜～今晚賞夫君一個最難忘的銷魂長夜！"],["先假意答應誘敵出城，再夜襲踏平敵營",null,"不愧是天運者，這手毒計連奴家都佩服呢。"],["若真能換來萬民太平，江山自然比紅顏重",null,"涼薄無情的男人！那奴家只好提前替自己物色新東家囉～"]]},{"q":"夫君覺著奴家這副不老雪肌，究竟是靠駐顏秘術，還是靠採補天下男人的慾望？","o":[["靠全城男人對妳的癡狂，而今晚便由我親手餵飽妳",null,"咯咯，夫君越發上道啦！快把殿門閂上罷～"],["管它靠什麼，只要妳這副身子留在我榻上便夠了",null,"哼，想拴住夏姬，光憑這句話可不夠喔。"],["少練那些邪門房中術，免得惹前朝非議",null,"古板無趣！難怪清流老頭都愛跟你湊一塊兒！"]]}],"liji":[{"q":"夫君，那位手握重兵的大將寬厚仁慈、甚得民心，百姓甚至只知將軍不知天運者……您覺得他是忠臣，還是大患？","o":[["功高震主必生異心，明日便削奪兵符甚至清洗",null,"（柔聲拭淚，眼底卻迸出得意冷笑）夫君英明果斷，這座城總算安穩了。"],["我自會派人暗中盯緊他，暫不動聲色",null,"夫君老謀深算，妾身也會叫驪戎密探替您盯牢的。"],["他赤膽忠心，妳別再演「夜半而泣」挑撥離間了",null,"（瞬間淚如雨下）妾身一片苦心竟被夫君當成毒計……不如早些賜死我罷！"]]},{"q":"若明日大祭胙肉驗出劇毒、線索直指{b}妹妹，夫君待如何處置？","o":[["鐵證如山絕不姑息，立刻打入冷宮或賜死",null,"（溫柔依偎進你懷裡淺笑）夫君如此明斷，妾身便徹底放心了。"],["先徹查中途經手之人，絕不冤殺無辜",null,"（眸光微沉）夫君這般謹慎，倒真教妾身「敬佩」呢。"],["別跟我耍毒肉嫁禍的舊把戲，我一眼就能看穿妳",null,"（驟然拭乾假淚冷笑）看穿了又如何？夫君心底不也早就嫌她礙眼了嗎？"]]},{"q":"外頭人人都罵我蛇蠍心腸、把你雕琢成多疑暴君，夫君自己可曾後悔留我在枕邊？","o":[["絕不後悔，咱們早沾滿同一群人的血，是天生共犯",null,"（綻出世上最溫柔也最毒辣的微笑）夫君總算肯說句掏心窩子的實話了。"],["妳的手段確實好用，但別把手伸得太長",null,"妾身自有分寸，永遠只做夫君掌裡最順手的那把毒刀。"],["確實後悔，妳害我折損了太多忠臣良將",null,"呵，若非你自己骨子裡多疑自私，我這兩滴眼淚哪撬得動你的刀？"]]},{"q":"若將來妾身為夫君誕下骨血，前頭那些庶長子與其他妃嬪勢力，夫君打算如何安排？","o":[["這座城的繼承人只認妳所出，其餘威脅盡數清除",null,"謝夫君厚愛！妾身定替咱們孩兒鋪出一條最乾淨的登頂血路。"],["立賢不立長，全看孩子日後各自造化",null,"（垂眸冷笑）既比造化，那便別怪妾身替孩兒「爭一爭」造化了。"],["後宮子嗣一視同仁，絕不許重演晉國申生之禍",null,"一視同仁？夫君這話，怕是連你自己都不信罷。"]]}]},"visit":{"jiananfeng":[{"t":"夜送密名單","d":"賈南風深夜不經通傳直接推開書房門，將一卷寫滿前朝反對派死穴的血紅名冊重重拍在你案上。","c":[["大笑收下名冊，留她半夜對飲烈酒",null],["皺眉命她少插手前朝密探之事",null]]},{"t":"怒砸銅鏡","d":"賈南風氣沖沖提戟闖進書房，只因少府工坊誤送了一面磨得極亮的西域琉璃鏡進椒房殿。","c":[["立刻下令重罰工坊，將暴怒的她按進懷裡安撫",null],["勸她別為了一面鏡子大動肝火見血",null]]},{"t":"索要禁軍令牌","d":"賈南風端來一壺關中烈酒，卻在酒過三巡時伸手向你討要調動內城禁軍的玄鐵兵符。","c":[["豪爽借她兵符「中樞防務交給妳」",null],["笑著按住她的手岔開話題拒不鬆口",null]]}],"daji":[{"t":"狐火烤果","l":[[null,"夜半書房忽飄進一陣焦甜果香，妲己赤足輕巧溜進來，赤紗鬆垮，手裡托著一盤熱騰騰的蜜漬烤果。"],[null,"夫君整晚盯著這些死氣沉沉的竹簡多悶呀～嚐嚐奴家用青丘小火烤的甜果！"],[null,"拿千年妖火烤果子，全天下也就妳幹得出來。"],[null,"嘻嘻，張嘴嘛！吃完了今晚可得留足力氣陪奴家在榻上玩喔～"]],"c":[["笑著張嘴咬下甜果，順勢將她拉坐腿上停筆溫存",null],["接過果盤誇她手藝奇絕，哄她先回暖閣等自己",null]]},{"t":"暗報流言","l":[[null,"妲己懶洋洋斜倚在你書案邊，雪白尾尖故意掃過你的手背，妖瞳閃著狡黠壞笑。"],[null,"夫君，奴家方才在禁苑樹梢打盹，聽見{a}院裡有人在背地裡怨你偏心昏庸喔～"],[null,"喔？妳這是替我巡夜，還是專程來煽風點火看熱鬧的？"],[null,"當然是心疼夫君嘛！要不要奴家半夜去她帳裡放團小狐火燒她裙子？"]],"c":[["笑著捏她粉頰制止她放火，卻誇她鬼靈精怪",null],["順著她的話逗她開心，許諾今夜只宿鹿臺暖閣",null],["板起臉斥她莫在後宮挑撥離間，惹得她甩尾冷哼離去",null]]},{"t":"撒嬌討珠","l":[[null,"妲己忽然從門外閃進來，雙手背在身後，豐胸微挺，眼巴巴盯著你案頭那匣剛入庫的夜明珠。"],[null,"夫君～那顆亮晶晶的寶珠跟奴家的狐火好襯呀，賞給奴家當玩意兒好不好？"],[null,"那可是照亮夜路的稀世奇珍，妳拿去當玩具？"],[null,"給人家嘛～只要夫君點頭，今晚隨便你怎麼揉我的胸乳和尾巴都不生氣喔！"]],"c":[["笑著大方賜下珍禮，換來九尾狐滿眼驚喜撲進懷裡",null],["答應先借她賞玩三旬，哄得她笑靨如花",null],["搖頭拒絕稱奇珍須留作城防照明，令她氣鼓鼓瞪你",null]]}],"xiaji":[{"t":"夜送赤紅汗衫","d":"夏姬披著半透紅紗輕步走進書房，笑盈盈將一件帶著滾燙體溫與濃香的貼身赤紅衵服搭在你肩頭。","c":[["一把將她抱上書案扯開紅紗，徹底拋開公文",null],["板起臉把汗衫退回，喝令她自重",null]]},{"t":"炫耀外臣貢禮","d":"夏姬端著一匣前朝大夫偷送進來的西域寶石在你面前晃悠，嬌笑問夫君要不要出更高價壓死對方。","c":[["大笑賞她十倍珍寶，當場將她按進懷裡強吻宣告主權",null],["震怒沒收寶石，派暗衛嚴查那名私通後宮的大夫",null]]},{"t":"駐顏香茶","d":"夏姬端來一盞香氣勾魂的秘製花茶，嬌笑說是專程替夫君大補陽氣、好應付今夜株林暖閣用的。","c":[["仰頭飲盡，反手攔腰抱起她直奔內室",null],["疑心裡頭摻了催情猛藥，冷靜婉拒不喝",null]]}],"liji":[{"t":"深夜泣訴密情","d":"三更時分驪姬只披素白單衣立在書房外無聲抽泣，說夢見前朝重臣聯手逼宮，哀求你連夜先下手清洗。","c":[["擁她入懷安撫，暗暗記下她口中的嫌疑名單",null],["冷靜點破她又在危言聳聽，命她回殿安歇",null]]},{"t":"呈上優施密報","d":"驪姬悄悄遞上一卷心腹樂師優施打探到的朝臣私密醜聞，柔聲細語「捏住把柄才好御下」。","c":[["笑著收下密報，誇她是最得力的枕邊暗網",null],["原封退回，冷聲警告她莫結交密探干政",null]]},{"t":"親驗晚膳毒肉","d":"驪姬親持銀針替你試查晚膳，卻故意在你面前挑出某道炙肉色澤發暗，柔聲暗指是{b}派人動的手腳。","c":[["順勢震怒訓斥{b}並重賞驪姬護主有功",null],["笑著自己先夾起咬下一口，當場戳穿她的離間計",null]]}]},"wish":{"jiananfeng":[{"t":"賜予先斬後奏權","d":"賈南風想要一道「凡敢對皇后不敬者，無須請旨即可先斬後奏」的玄鐵敕令。","eff":null},{"t":"抄斬死敵外戚","d":"賈南風點名要抄沒前朝一位屢次與她作對的世家豪門，黃金盡入椒房殿私庫。","eff":null}],"daji":[{"t":"九轉丹爐","ask":"夫君，快蓋一座煉丹房罷！奴家最愛聞晶核在丹火裡融化的香味了～","cond":null,"n":null,"days":null,"done":"嘻嘻，這爐丹火聞著真香！今晚奴家替你煉兩顆最壯陽提神的靈丹！","fail":"哼，小氣鬼，連座煉丹房都不肯蓋給奴家玩。","eff":null},{"t":"靈氣餵養","ask":"近來黑霧太討厭啦，夫君分五十點星盤能量給奴家滋養九尾好不好？","cond":null,"n":null,"days":null,"done":"唔～好暖好銷魂的靈氣！夫君快來摸摸，尾巴是不是更軟更滑了？","fail":"不給就不給，今晚休想靠著奴家的狐尾睡覺！","eff":null}],"xiaji":[{"t":"大開株林夜宴","d":"夏姬想在偏苑舉辦一場邀集前朝俊美文武與後宮眾妃共飲的銷魂株林夜宴。","eff":null},{"t":"賜封絕代尤物牌匾","d":"夏姬要你親筆題賜「傾國傾城」金匾高懸殿前，教全城男人日夜仰望垂涎。","eff":null}],"liji":[{"t":"設立驪戎暗探司","d":"驪姬盼能獲正式授權，由心腹優施統領一支專司監控前朝忠臣與後宮動態的秘密暗探。","eff":null},{"t":"清洗異己清流派","d":"驪姬想藉大祭之機，將朝堂上幾名最剛直且對她深懷敵意的清流重臣一網打盡。","eff":null}]},"bday":{"jiananfeng":{"remember":"哼，算你還記得本宮生辰！今日便先不殺人見血了——把那匣西域奇珍遞過來罷！","forget":"連本宮生辰都忘得一乾二淨？好得很！明早菜市口多滾幾顆人頭，就算替本宮賀壽了！","gift":"這份壽禮夠氣派，壓得死那群只會撒嬌的小賤人！今晚本宮賞你留在椒房殿。"},"daji":{"remember":"呀，夫君居然記得青丘九尾狐的生辰？今晚奴家可得在帳裡好好「報答」你囉～","forget":"敢忘記本姑娘生辰？哼，小心奴家用狐火把你書房的竹簡全烤成焦炭！","gift":"這份壽禮閃閃發亮真美！夫君果然最懂奴家心思！"},"xiaji":{"remember":"咯咯，夫君居然記得奴家生辰呀？別擔心，不管過了幾十載，奴家這身雪膚與花戶永遠是全城最銷魂的！","forget":"連奴家生辰都忘了？無妨，前朝那兩位大夫今早便送了三車珍寶進株林替我賀壽啦～","gift":"這份壽禮真懂女人心！今晚奴家便把這副不老胴體全交給夫君肆意採補囉！"},"liji":{"remember":"（溫婉垂淚福身）夫君萬機繁忙還記得妾身生辰……有您這份心，驪姬願替您除盡世間一切隱患。","forget":"（眼眶驟紅強顏歡笑）無妨，妾身原是卑微驪戎女子，夫君牢記著{b}妹妹生辰便好……","gift":"這份珍禮妾身收下了。今夜就讓妾身在暖帳裡，替夫君細細說說前朝最新的密報罷。"}},"anniv":{"jiananfeng":["成婚這麼久，你居然還沒被本宮嚇跑、也沒敢廢了我……看來咱們確實是天生一對的狠人。","又是一載，這座江山的生殺大權咱們攥得越發牢固——誰敢伸手搶，本宮照樣夷他三族！"],"daji":["不知不覺竟纏了夫君又一年啦～怎麼樣，被九尾妖狐吸住魂魄的滋味很上癮罷？","一年不夠、十年不夠，生生世世的紀念日你都得陪奴家醉死在紅帳裡！"],"xiaji":["居然能留住夏姬這麼久還沒亡國，天運者你確實比當年的陳靈公硬氣十倍呢～","又是一年風流歲月！只要你永遠踩得死全城情敵，奴家便繼續陪你玩這場危險遊戲。"],"liji":["相伴至今，夫君的手與妾身的心早已沾著同一批人的血——我們天生離不開彼此。","又是一年春秋。世人罵得越毒，越證明妾身把這座江山與夫君的心抓得有多牢呢。"]},"jealous":{"jiananfeng":["剛從{b}那狐狸精榻上爬起來？一身廉價脂粉與汗味燻得本宮作嘔！","你儘管寵{b}罷，捧得越高，哪天她撞在本宮短戟上時才死得越難看！","再敢當著本宮的面誇{b}生得美，今晚我就派死士去劃爛她的臉！"],"daji":["嗅嗅……呀，夫君領口沾著{a}的臭脂粉味！快把外衣剝了，奴家聞著反胃！","剛跟{a}翻雲覆雨完就來招惹九尾狐，夫君是不怕奴家吃醋燒了她的院子嗎？","哼，{a}那點死板手段哪有奴家銷魂？今晚罰你徹底忘掉她，只許喘著氣喊我的名字！"],"xiaji":["剛睡完{b}那副清湯寡水的身子？夫君玩兩日就會膩的，最後還不是得乖乖爬回株林求奴家！","去寵{b}罷！正好空出今晚，讓奴家邀前朝那位英俊侍郎進暖閣喝兩杯解悶～","敢拿{b}那種木頭女人跟夏姬比？夫君今晚若沒拿出真本事，別怪奴家換個新男人採補喔！"],"liji":["{b}妹妹真是難得的賢德之人呢，連前朝幾位握重兵的將軍都對她讚不絕口……妾身聽著總替夫君心慌。","夫君多去陪陪{b}妹妹也好，免得她怨氣積深，哪天在大祭胙肉裡做出什麼糊塗事來。","（柔聲微笑，眼底森冷如蛇）夫君越是偏寵{b}，妾身便越要替您仔細「查一查」她背後的清白呢。"]}},"edict":{"jiananfeng":{"賑":["施點稀粥吊住流民狗命，省得這群泥腿子餓極了造反耽誤本宮掌權！","開倉放糧可以，敢在粥棚吵鬧插隊者直接就地斬首示眾！"],"徵":["加徵五成脂粉與軍資稅！這座城所有的金銀，本就該先填滿椒房殿私庫！","哪戶豪強敢少繳半兩稅銀，直接派東宮死士抄他滿門！"],"截":["把前朝彈劾本宮醜毒專權的章疏全截下來，按署名一個一個夷三族！","從今日起，沒蓋本宮大印的奏報，一卷也不准送進天運者書房！"],"兵":["私調三千禁軍與東宮死士團團圍死太傅府，今日便教滿朝文武見識什麼叫血洗！","城防兵權收歸本宮節制，誰敢抗命直接拿短戟捅穿他的胸膛！"],"練":["親點校場！凡敢偷瞄笑話本宮容貌者、操練偷懶者，統統拖出來活活杖斃！","本宮親挑五百亡命死士編入貼身親衛，從此只認我賈南風一人！"],"土":["大興土木修築金墉別宮與密室暗道，方便本宮夜裡抬大木箱進出！","拆了那座礙眼的清流書院，原址替本宮起一座更森嚴的皇后行殿！"],"祭":["祭天大典由本宮親執短戟主祭！誰敢嘴碎陰盛陽衰，先砍了他當祭品！","求神不如求刀！這座高壇今日便用來祭本宮的東宮鐵血大旗！"],"刑":["大開掖庭獄與東宮刑堂！把不合本宮心意的洛陽少年與嘴碎宮婢全沉井清乾淨！","誰敢背著本宮懷上龍種？拖進刑堂，本宮親自拿短戟替她落胎！"],"官":["把賈氏外戚與懂事的太醫令全提拔進中樞要職，前朝舊臣統統滾蛋！","太醫房程據伺候本宮有功，破格升他掌管太醫署！"]},"daji":{"賑":["拿幾車發霉陳米撒給流民罷，看他們搶得頭破血流多熱鬧呀，咯咯！","施粥可以，但碗裡得摻上一半烈燒酒，讓全城窮鬼一起醉生夢死！"],"徵":["加徵三倍酒肉脂粉稅！鹿臺的酒池還沒注滿呢，全城百姓快把銀子掏出來呀～","沒錢交稅？拿家裡的金玉美酒來抵，敢抗稅的直接丟進毒蛇蠆盆！"],"截":["前朝那幫酸儒又寫萬言書罵奴家禍國啦？全截下來拿去生炭火溫酒！","別拿那些枯燥軍報掃夫君的興致，全鎖進鹿臺偏殿裡發霉罷！"],"兵":["調兩千禁軍進禁苑替奴家抓毒蛇、掛炙肉！打仗哪有逗奴家開心要緊？","派禁軍把四門關死，今晚全城陪奴家開酒池狂歡夜宴，誰敢掃興就砍誰！"],"練":["親點校場！讓這群大老粗當場捉對拿真刀真槍互砍，見血才夠刺激嘛～","贏家賞烈酒美人，輸家直接拖去餵本姑娘的青丘毒蛇！"],"土":["大興土木起一座比朝歌還壯麗的「歸墟鹿臺」！把國庫黃金全砸進去！","再鑿一座十丈寬的暖玉酒池，池邊掛滿流油炙肉，這才叫神仙日子！"],"祭":["祭天？挑幾個嘴最臭的清流諫臣綁上高壇活祭，老天爺準愛看！","今日由青丘九尾狐親自主祭，祈求這座城越亂越好、越墮落越快活！"],"刑":["架起燒紅的青銅炮烙柱、挖好毒蛇蠆盆！今晚刑堂大開，聽慘嚎下酒囉～","把那個敢偷瞄夫君的小賤婢拖進暗室，教她嚐嚐狐火炙烤雪肌的滋味！"],"官":["把最會阿諛奉承、最擅搜刮民脂民膏的奸佞全提拔進戶部替奴家撈錢！","誰進獻的西域催情奇香與烈酒最合奴家心意，明早便封他當大將軍！"]},"xiaji":{"賑":["開倉放糧收容流民呀，聽說流民裡藏著不少落魄貴冑與俊朗武夫呢，全收進城熱鬧熱鬧～","讓流民一邊喝粥一邊傳頌奴家美名，很快城外男人都會搶著來投靠囉！"],"徵":["加徵脂粉與奇香稅！沒有西域駐顏香滋養這副絕色皮囊，怎麼替夫君迷倒天下男人呀？","城中富商個個盯著奴家看直眼，多徵他們幾成脂粉稅，他們只會搶著掏錢呢！"],"截":["把前朝御史痛罵奴家「亡國妖婦」的章疏全截下來，記下名字交給我的仰慕者去收拾他！","這幾卷催夫君戒色的掃興公文，全扣在株林暖閣裡當墊茶盞的廢紙罷～"],"兵":["私調兩位素來迷戀奴家的守城大將領兵護送出遊，看他們一路互相吃醋真好玩！","調禁軍去城外替奴家截下西域商隊那批極品赤紅絲綢，不夠裁新汗衫啦！"],"練":["親點校場！誰今日演武奪得魁首，奴家親手賞他一杯溫酒外加一方貼身香帕喔～","瞧這群猛將為了博奴家一笑拚命流血的模樣，比什麼兵法都管用呢！"],"土":["大興土木在後苑重起一座「株林銷魂閣」，四面垂掛赤紅薄紗，夜夜笙歌！","把禁苑一角改鑿成香花暖玉溫泉池，方便奴家修煉採補駐顏秘術嘛～"],"祭":["今日祭天由奴家披赤紅薄紗領舞主祭，保證連天上神明看了都心神蕩漾！","祈求天下男人的色慾永不熄滅，讓我夏姬永遠立於這場權色血風暴中心！"],"刑":["把那個背地裡罵我「剋夫老妖婦」的醜宮婢鎖進刑堂，劃爛她那張嫉妒的臉！","誰敢搶奴家看上的俊美男臣？私設刑堂教她什麼叫規矩！"],"官":["朝堂上那兩位穿著奴家赤紅汗衫的大夫忠心可嘉，直接雙雙加官進爵！","把城裡最英俊、最懂憐香惜玉的年輕才俊全安插進兵部與禮部，看著才舒心嘛～"]},"liji":{"賑":["開倉賑濟流民，讓全城百姓傳頌天運者與驪姬之仁德——順便暗查有無某位大將的死士混入。","放糧施粥之際，正好叫優施派人散播幾句誇讚某忠臣「寬厚勝君」的流言呢。"],"徵":["加徵脂粉稅充實驪戎暗探經費，這筆錢花在監控百官忠誠上，最值當不過。","這筆新稅收得名正言順，清流就算想查也查不到妾身頭上。"],"截":["將那位剛直大將自證清白的血書全數截留焚毀，省得動搖夫君清洗他的決心。","這幾卷替{b}喊冤求情的章疏全扣下罷，今夜妾身再替夫君「解讀」成謀逆罪狀。"],"兵":["私調禁軍暗中盯死兩位功高震主的大將府邸，只要露出一絲怨言，即刻以謀反抄斬！","調一隊心腹宿衛把守大祭膳房，確保這盤毒胙肉能安安穩穩端上該去的地方。"],"練":["親赴校場溫婉慰勞三軍，實則暗記軍中誰只認大將號令、不認天運者。","賞賜三軍美酒，再悄悄在幾名偏將耳邊種下彼此猜忌的毒種。"],"土":["大興土木修築晉陽別館與秘密暗道，方便優施與驪戎密探深夜進出密會。","擴建祭天宗廟與暖閣，越是莊嚴肅穆之地，越適合演一場天衣無縫的毒肉殺局。"],"祭":["今日大祭由妾身親自主持並驗看胙肉——呵，這盤祭肉，可要定下不少人的生死呢。","焚香泣拜上蒼，祈求上天助夫君看穿身邊所有「笑面虎」忠良的真面目。"],"刑":["私設暗牢審訊知情的膳房雜役，撬完口供後直接賜一杯無聲毒茶滅口。","對付那些嘴硬不肯認罪嫁禍{b}的賤奴，用點溫柔卻蝕骨的慢毒酷刑最管用。"],"官":["將心腹優施與驪戎舊部安插進密探司與禮部，從此這座城的耳目盡歸妾身掌中。","把對妾身唯命是從的官員提拔上高位，至於剛直忠臣……很快就會騰出空缺的。"]}},"power":{"jiananfeng":{"veto":["（手按短戟發出陰狠冷笑）處置本宮？你睜眼瞧瞧這宮門裡外站的是你的親衛，還是我賈南風的東宮死士！","這道旨意敢蓋印，今晚本宮便矯詔先把你書房裡那幫出主意的狗賤奴全夷三族！","哼，司馬衷都不敢這樣對本宮大呼小叫，天運者你算老幾？這道旨意本宮駁回了！"],"rise":"（踏過政敵府邸斷裂的門匾狂笑）權柄既入我手，這座城從今日起，誰敢多瞄本宮眉間一眼便挖誰的眼！","regent":"（玄黑鳳袍垂簾於正殿之上，殺氣森然）天運者體弱多病，今後前朝軍政生殺大權一律由本宮稱制決斷，違者夷族！","fall":"（被繳去兵權仍死死盯著你毒笑）好啊……你敢拉本宮下馬，就別怪我點燃八王之亂，拉整座城替我陪葬！","ev":[{"t":"矯詔夷族・獨攬中樞","l":[[null,"你清晨剛醒便聞噩耗：賈南風昨夜竟趁你熟睡偷拿玉璽矯詔，親派東宮死士血洗了反對她的兩名重臣府邸，連同老小數十口雞犬不留！"],[null,"（提著尚帶血腥氣的玄金玉璽扔回你懷裡冷笑）這兩條老狗整天想廢本宮，留著過年嗎？人已經殺光了，玉璽還你——你待如何？"]],"c":[["冷笑收起玉璽默許這場血洗「殺得痛快，正好替我立威」",null,"{a}：「哈哈哈哈！這才配做我賈南風的夫君！今晚賞你共飲血酒！」"],["勃然大怒當眾斥責她矯詔濫殺，強硬收繳她的東宮死士兵符",null,"{a}：「（雙目赤紅）為了兩具死屍動我兵權？咱們走著瞧！」"],["對外宣稱叛臣謀逆替她遮掩，私下嚴厲警告她絕不可再偷玉璽",null,"{a}：「哼，只要權柄還在手裡，演這場戲本宮奉陪。」"]],"after":"菜市口的血水三日未乾，朝堂上下再無人敢直呼賈后名諱。"},{"t":"兵圍金墉・逼君二選一","l":[[null,"賈南風與手握重兵的清流大將徹底決裂！她直接調動城內親信禁軍堵死宮門，逼你當場在「將大將押送金墉城賜死」與「廢黜賈南風」之間二選一。"],[null,"（舉起短戟，雙目瘋狂如惡鬼）選罷！今日這座城裡，有他沒我、有我沒他！"]],"c":[["順從賈南風將大將押赴金墉城處死，徹底讓她獨霸朝堂",null,"{a}：「（狂笑撲進你懷裡）這座江山，從今往後徹底姓你我的姓！」"],["親率忠誠禁軍反包圍椒房殿，當場削去賈南風大半權勢",null,"{a}：「（咬牙毒笑）你今日沒殺死我，明日便是你的死期！」"],["強行將大將調往最偏遠的分城避禍，暫且穩住兩邊局勢",null,"{a}：「算他跑得快！等本宮騰出手來，遲早追殺到分城去！」"]],"after":"金墉城的冷風刮過內城，人人都明白這場權力血戰遠未結束。"}]},"daji":{"veto":["（九尾虛影在紅燭裡一閃，掩唇狂笑）處置奴家？夫君睜眼瞧瞧滿殿百官，如今誰不是喝著奴家的酒、跪在鹿臺腳下？","想動刑？來呀，先把殿外兩千名被奴家迷得神魂顛倒的禁軍殺絕再說！","這道旨意真掃興，奴家直接扔進炮烙炭盆燒成灰了，今晚咱們繼續喝酒！"],"rise":"（赤足踏上鹿臺最高處張開雙臂大笑）咯咯咯！這座燈塔的魂已經被九尾狐吞了一半，再也逃不出我的手掌心囉！","regent":"（跨坐在君座扶手上，赤紗半敞俯視發抖的百官）從今日起，早朝改在鹿臺酒池邊上！誰敢吐半句掃興的話，直接丟進蠆盆！","fall":"（粉舌舔去唇角血絲，眼中妖火絲毫不滅）失勢了？無妨，只要男人的貪婪與色慾還沒死絕，九尾狐很快就會再爬回龍床！","ev":[{"t":"鹿臺代政・炮烙審奏","l":[[null,"妲己在鹿臺私設「酒池朝堂」，將前朝章疏全數截留。凡勸諫節儉的清流官員，她直接代你下旨綁去炮烙活烤；凡獻上奇珍烈酒的奸佞，她當場蓋印升官！"],[null,"（端著一杯血紅葡萄酒餵到你唇邊，雪乳輕蹭你手臂）夫君瞧，奴家替你把朝堂裡愛嗡嗡叫的蒼蠅全烤乾淨了，現在耳根清淨多了罷？"]],"c":[["狂笑飲盡酒爵，任由她在鹿臺把持朝綱肆意荒唐",null,"{a}：「哈哈哈哈！這才配做我的商紂王！咱們把歸墟燒成極樂魔窟！」"],["一把掀翻酒案，強行叫停炮烙並奪回她手裡的印信",null,"{a}：「（妖眸微瞇冷笑）裝什麼明君？你昨夜明明也看得心癢難耐嘛！」"],["制止她繼續活烤官員，但默許她提拔進獻財寶的奸佞充實公庫",null,"{a}：「留他們一條狗命看奴家跳赤紗舞倒也不錯，咯咯。」"]],"after":"焦糊烤肉味與濃烈酒香混在一起，成了這座城揮之不去的妖異夢魘。"},{"t":"妖火退敵・魔窟立威","l":[[null,"一支兇猛荒原敵軍趁著城中奢靡兵臨城下，守軍士氣潰散。千鈞一髮之際，權勢滔天的妲己竟赤足登上城樓，祭出暗養的死士與青丘狐火迷陣，將敵軍先鋒活活燒成哀嚎火海！"],[null,"（在沖天火光中回眸妖笑，紅紗獵獵飛舞）瞧呀，那些只會罵奴家禍國的清流全嚇得尿褲子了，最後還不是靠奴家保住孤城？今晚把國庫鑰匙交進鹿臺罷！"]],"c":[["大笑把內庫鑰匙擲給她「這座城本就該供養妳這頭絕世妖狐」",null,"{a}：「太好啦！明早就把酒池再鑿大三倍！」"],["重賞她焚敵奇功，卻堅決攥緊國庫鑰匙不鬆手",null,"{a}：「小氣鬼！救了你一條命還防著奴家，今晚罰你灌十壇！」"],["忌憚她的詭異妖勢，趁機削去她在城防中的眼線",null,"{a}：「過河拆橋的男人最討厭了，小心奴家下回見死不救囉～」"]],"after":"滿城百姓既駭於她的酷虐，又不得不承認，這頭九尾妖狐確實護住了魔窟不倒。"}]},"xiaji":{"veto":["（掩唇嬌笑，殿門外立刻衝進兩位穿著她赤紅汗衫的實權將領）夫君真要處置奴家？先問問前朝這些愛慕奴家的大人答不答應嘛～","這道處置旨意太掃興了，兵部與戶部那幾位大人已經替奴家聯名壓下來囉！","咯咯，你敢動我一根手指頭，明早半個朝堂的男人都會為了奴家跟你翻臉呢！"],"rise":"（輕撫半透赤紅薄紗淺笑）三夫一君一子算什麼？如今這整座歸墟燈塔的男人，全跪在奴家裙下囉！","regent":"（斜倚在正殿珠簾後拋出一個勾魂媚眼，滿朝文武神魂顛倒）以後早朝由奴家垂簾點評——誰最討奴家歡心，這高官便歸誰！","fall":"（毫不在意地整理鬢髮輕笑）失勢罷了。只要這世上還有管不住下半身的男人，夏姬隨時能再翻天！","ev":[{"t":"群臣聯保・禍水抗旨","l":[[null,"你原打算下旨收緊內廷宮規、嚴禁夏姬與外朝大臣私下往來，誰知詔書剛出書房，竟有十餘名實權文武重臣聯名抗旨力保夏姬清白，甚至威脅集體辭官！"],[null,"（赤足踏進書房，笑盈盈將那疊聯名章疏推到你面前）瞧呀，奴家連半句話都沒說，他們便自己搶著替我出頭了。夫君，這道旨意你還蓋不蓋印呀？"]],"c":[["大笑撕碎原旨將她拽進懷裡「看來滿城男人都跟我一樣中了妳的毒」",null,"{a}：「咯咯，這才叫懂憐香惜玉的好君王嘛～」"],["震怒將聯名領頭的三名大夫當場罷官抄家，強硬壓制夏姬勢力",null,"{a}：「（美眸微冷）為了爭口氣殺這麼多大臣，夫君吃起醋來可真狠呀。」"],["暫且收回成命，暗中逐個調離這批神魂顛倒的實權官員",null,"{a}：「調走一批，很快又會冒出新的一批仰慕者呢，夫君防得完嗎？」"]],"after":"不費一兵一卒，她僅憑一身絕色皮囊便撬動了半個朝堂。"},{"t":"傾國奇計・不戰屈敵","l":[[null,"城外兩大敵酋聯軍壓境，大戰一觸即發。權勢滔天的夏姬竟私派密使給兩位敵酋各送去一件沾香赤紅汗衫與曖昧密信，一夜之間挑動兩大敵酋為搶奪她而在大營拔刀火拚、不戰自潰！"],[null,"（倚在城樓媚笑回眸）兩件貼身衣裳便替夫君省了十萬軍糧與上千條人命——這座城裡，有哪位名將比奴家更能打呀？"]],"c":[["狂笑封她為傾國第一功臣，任她執掌外朝禮賓大權",null,"{a}：「嘻嘻，往後城外哪個敵酋不聽話，都交給奴家寫封情書解決囉！」"],["重賞珍寶嘉獎她的奇功，但嚴令不許再私通城外勢力",null,"{a}：「真沒趣，明明替你立了大功還管東管西的。」"],["忌憚她連敵酋都能隨手玩弄，趁機奪去她部分外朝聯絡權",null,"{a}：「怕奴家哪天也用這招對付你？夫君心眼可真小呢。」"]],"after":"春秋第一禍水之名響徹荒原，敵軍從此聞夏姬之名既垂涎又膽寒。"}]},"liji":{"veto":["（先垂淚楚楚可憐，見你不為所動立刻冷笑）夫君要處置妾身？可惜滿朝文武的把柄全攥在優施手裡，這道旨意怕是沒人敢接呢。","夫君忘了嗎？您身邊所有忠良早被您親手殺絕了——如今除了妾身的人，誰還聽您的？","（溫柔將處置詔書摺好收入袖中）夫君今日累糊塗了，這道旨意妾身替您收著，明早再議罷。"],"rise":"（在昏暗燭光下微笑撫過密探名冊）眼淚與猜忌已結成天羅地網，這座城從今日起，再無一人逃得出妾身掌心。","regent":"（端坐珠簾之後，嗓音依舊柔婉如水卻教百官毛骨悚然）夫君龍體欠安，今後凡百官忠奸考核與軍政大權，皆由妾身代裁。","fall":"（垂眸輕嘆，眼底卻燃起更陰毒的冷火）一時失勢又如何？只要猜忌的毒種還埋在夫君骨髓裡，妾身遲早能再借刀殺人！","ev":[{"t":"毒肉清君側・逼殺重臣","l":[[null,"驪姬權勢滔天之際，大祭胙肉案再度爆發——這回她直接將「下毒弒君」的鐵證死死扣在朝中僅存的兩名核心忠臣頭上，並已命優施調集酷吏將兩人府邸團團圍死！"],[null,"（伏在你膝頭柔聲泣訴，眼底卻冰冷逼視著你）夫君，鐵證如山，他們若不死，明日躺進棺材的便是你我啊……請您現在就下旨滿門抄斬罷！"]],"c":[["徹底淪為她的共犯，冷酷下旨將兩名忠臣滿門抄斬",null,"{a}：「（拭去假淚露出完美微笑）夫君英明。這座城總算徹底乾淨了。」"],["當眾戳穿她與優施栽贓嫁禍的毒計，強硬釋放忠臣並削去她大權",null,"{a}：「（面色陰沉冷笑）夫君寧信外人也不信共犯？你很快就會後悔的。」"],["將兩名忠臣貶為庶人流放出城保其一命，勉強順了驪姬心意",null,"{a}：「放虎歸山終究是患……不過妾身自有法子在路上『送』他們一程。」"]],"after":"大祭的香煙漸散，朝堂之上再無一人敢與驪姬對視。"},{"t":"暗網反殺・先發制敵","l":[[null,"城外敵國密探與城內一名偽裝極深的叛徒將領暗約今夜裡應外合，連你親衛都毫無察覺。然而驪姬憑著遍布全城的驪戎暗網，竟搶先一步將敵探與叛將全數活捉滅口，無聲替你擋下一場滅城大禍！"],[null,"（奉上一盞溫熱安神茶，溫婉淺笑）妾身說過，這座城裡唯有驪姬永遠不會背叛夫君。如今大患已清，這密探司與兵部考核之權，便正式交由妾身掌管罷？"]],"c":[["將密探與百官考核大權正式賜予她「妳確實是我最利的暗刃」",null,"{a}：「謝夫君信重。往後任何敢對您起異心之人，都活不過天亮。」"],["重賞金銀卻堅決不交兵部考核權，防範她權勢過盛",null,"{a}：「（垂眸淺笑）夫君既防著妾身，那妾身只好更『用心』證明自己的價值了。」"],["趁機查抄優施的暗探名冊，將這張情報網收歸自己直屬",null,"{a}：「奪走我的耳目？夫君，你真以為沒了我，你能駕馭得了這群毒蛇？」"]],"after":"毒蛇護主，卻也教主人在不知不覺間徹底被毒網纏死。"}]}},"cycle":{"jiananfeng":{"p0":["（面色比平日更顯青黑陰沉，手按短戟冷笑）本宮這幾日月事見紅、小腹絞痛、火氣正旺，哪個不長眼的賤奴敢犯錯，直接杖斃！","這點血崩墜痛算什麼？把最烈的關中燒酒溫熱端來，喝暖了照樣審案殺人！","別拿那副假惺惺的同情眼神盯著本宮！滾出去！"],"p1":["（陰鷙眼底燃起赤裸的慾望與生嗣執念，鬆開衣襟透氣）這兩日身子發燙、胞宮溫熱得很——今晚把殿門鎖死，本宮要懷上只屬於我賈家的儲君！","（一把揪住你的衣領冷笑逼近）少去碰那些騷狐狸了，這幾日正是結珠的好時候，你老實留在椒房殿交差！","氣血充盈得很，連腰腿都透著勁，舞起短戟格外稱手呢！"],"p2":["（煩躁地砸碎茶盞，滿屋戾氣沖天）這兩天胸口憋得想殺人！前朝哪個老賊最近最嘴碎，報個名字上來！","把屋裡反光的銅器全撤了！本宮這兩日臉色發青難看透頂，誰敢偷瞄我眉間的瘤，挖了她的眼珠！","（冷笑盯著你）別惹本宮發瘋，否則今晚這後宮裡可有見血的好戲看了！"],"ev":[{"phase":null,"t":"腹痛見血・戾氣暴漲","l":[[null,"經期的賈南風因小腹劇痛而暴虐到了極點，只因小宮婢端來的熱水稍涼了一分，竟拔出短劍按住對方手腕準備當場剁掉！"],[null,"（捂著絞痛小腹，面容陰狠扭曲）連壺熱水都燒不燙，留著這雙賤手幹什麼？"]],"c":[["冷靜扣住她持劍的手腕，親自奉上滾燙老薑茶「別為賤奴氣壞身子」",null,"{a}：「（冷哼收劍）算這賤婢命大！滾出去！」"],["冷眼默許她斬斷宮婢手指洩火，順手把暖爐塞進她懷裡",null,"{a}：「還是夫君懂我，見了血這肚子倒沒那麼絞得慌了。」"]],"after":"椒房殿的僕婢都知道，每月這三日便是閻王點卯的日子。"},{"phase":null,"t":"強留聖駕・霸道索嗣","l":[[null,"排卵期的賈南風情慾與奪權野心同時沸騰，竟直接命東宮死士把椒房殿外圍得水洩不通，霸道地扯開你衣帶、把你按在玄黑錦榻上不准起身。"],[null,"（跨坐你身上，呼吸粗重而狂熱冷笑）司馬衷那白癡沒用，生不出好種，你可不一樣——今晚不把本宮伺候到身子發軟，休想走出這扇門！"]],"c":[["大笑反手將她翻壓進錦被「好啊，看今夜誰先喘不過氣」",null,"{a}：「哈哈哈哈！就愛你這股不怕本宮的狠勁兒！」帳幔落下後徹夜翻湧，次日宮婢收拾時見被褥一片狼藉水漬。"],["沉臉斥她竟敢調動東宮死士圍困君王",null,"{a}：「（冷笑鬆手翻下身）開個玩笑便板臉？真掃興！」"]],"after":"權力與血脈的雙重飢渴，讓這一夜充滿了危險而露骨的張力。"},{"phase":null,"t":"經前暴怒・欲砸別殿","l":[[null,"經前焦躁讓賈南風看什麼都像在挑釁，聽見鄰殿飄來一陣嬌笑聲，竟直接提著長戟衝出門要去砸人場子！"],[null,"（雙目赤紅怒極）吵死人了！那群賤婢故意笑給本宮聽的是不是？！"]],"c":[["立刻攔腰抱住她扛回椒房殿，命人端上最烈的燒酒與炙肉消火",{"love":null,"mood":null},"{a}：「（仰頭灌了一大口烈酒）哼，若非你攔著，我今晚非拆了她的屋頂、刮爛她的臉！」"],["笑著遞上她最愛看的政敵抄家名單轉移殺火",null,"{a}：「這才像話！看這幫老東西倒楣比砸別殿解氣多了！」"]],"after":"一場差點血洗鄰殿的風波，總算被一壇烈酒與抄家名冊按了下去。"}]},"daji":{"p0":["（懶洋洋窩在雪白狐裘裡小口啜飲滾燙紅棗烈酒）這幾日月事見紅真掃興……不能赤身泡進酒池，便在岸邊喝酒看戲罷～","小腹一陣陣發冷絞痛，快叫人把銀絲炭再加十盆，把鹿臺烤得像盛夏一般暖和！","（妖瞳微瞇冷笑）別以為奴家身子見血就軟了爪子，惹惱了我照樣把人推進蠆盆喔。"],"p1":["（眼底妖火流轉，赤紗下豐乳飽滿發脹、氣息灼熱勾魂）咯咯，這兩日身子燙得像燃起青丘狐火，花露都快浸透薄紗啦——夫君今晚不來滅火，奴家可要溜去禍害前朝大人囉～","氣血最旺的這兩日，連九條尾巴都發癢得緊！快來陪奴家痛痛快快荒唐到天明！","（伸出粉舌舔過紅唇媚笑）今晚的奴家可是最飢渴、最銷魂的九尾狐喔，夫君準備好被榨乾了嗎？"],"p2":["（煩躁地一把扯斷頸間明珠項鍊，珠子滾滿玉磚）這兩天心裡又癢又燥，莫名其妙就想見血聽慘叫解悶！","酒不夠烈、炙肉不夠肥、樂師彈得像出殯！這整座城怎麼都這麼教人心煩呀！","夫君快來哄哄奴家，不然今晚我就把鹿臺外那幾個嘴碎的清流拉去炮烙消火囉～"],"ev":[{"phase":null,"t":"狐裘溫酒・經期嗜暖","l":[[null,"正值經期的妲己畏寒得緊，竟命人把整張雪白狐裘鋪滿暖閣地面、炭盆燒得滾燙，正抱著一壺溫熱辛辣的薑酒慵懶等你。"],[null,"（拉過你的手按進衣襟裡貼上她微涼柔滑的小腹撒嬌）好冰呀夫君，用你滾燙的陽氣替奴家捂暖嘛～"]],"c":[["笑著將她整個人裹進懷裡貼身暖著，陪她溫酒閒聊",null,"{a}：「咯咯，夫君這個人形暖爐可比炭盆銷魂十倍！」"],["叮囑她見血期間少飲烈酒，換成滾燙赤糖老薑茶一口口餵她",null,"{a}：「切，管得真寬……不過這甜湯喝下去，肚子倒真暖和多了。」"]],"after":"九尾狐縮在暖烘烘的懷裡發出饜足輕哼，難得安分了一夜。"},{"phase":null,"t":"妖火焚夜・極致誘惑","l":[[null,"排卵期的妲己媚骨天成、妖冶逼人，只披一層半透赤紗在暖玉酒池邊點滿催情異香，豐乳肥臀曲線畢露，望著你的眼神滾燙得像要把你生吞活剝。"],[null,"（赤足跨坐上你的膝頭，玉臀輕磨，吐氣如蘭）今晚奴家身子裡濕燙得要命、最想要你了……把那些臭章疏全燒掉罷，陪我瘋到天亮！"]],"c":[["徹底沉淪於青丘妖魅，一把將她壓倒在酒池旁軟榻荒唐纏綿整夜",null,"{a}：「（仰首嬌喘，九尾緊纏你雙腿）哈哈哈哈！這才配做九尾狐最愛的昏君夫君！」紅紗帳內翻湧直鬧到日上三竿，宮婢收拾時見錦褥濕透一片。"],["笑著按住作亂的她，先批完緊急軍報再回頭狠狠收拾這隻妖狐",null,"{a}：「真會吊人胃口……那奴家就在池邊赤著身子等你喔～」"]],"after":"那一夜鹿臺的紅紗帳與酒波翻湧直至黎明。"},{"phase":null,"t":"經前嗜血・怒砸樂坊","l":[[null,"經前焦躁讓妲己徹底失了耐性，僅因樂師撥錯半個音，她竟當場砸碎琵琶、下令把整班樂師拖進刑堂活烤受刑！"],[null,"（煩躁地扯開領口露出雪白酥胸冷笑）難聽死了！這兩天我就是想聽慘叫、見點血消消心頭邪火！"]],"c":[["一把將她拽進懷裡餵她吃最愛的炙烤肥鹿肉轉移殺意，保下樂師",null,"{a}：「（咬下一口流油烤肉哼聲）算這群廢物命大！今晚你要加倍伺候奴家！」"],["縱容她的暴虐「彈錯音本就該罰，拖下去重打見血」",null,"{a}：「咯咯，果然還是夫君最懂怎麼哄我消氣！」"]],"after":"樂坊眾人撿回一條命，從此每月這幾天撫琴都嚇得雙手直抖。"}]},"xiaji":{"p0":["（慵懶倚在赤紅軟枕上掩唇輕嘆）這兩日月事見紅發冷，春秋採補秘術也得暫歇呢，夫君只能瞧著、吃不得喔～","小腹隱隱墜痛，連前朝大夫送進來的西域奇香聞著都膩味……快溫碗桂圓紅棗烈酒替奴家暖暖胞宮。","（眼波微倦卻依舊媚意橫生）這幾日奴家最需要溫柔捧著哄，夫君別因為不能上床便冷落株林暖閣喔。"],"p1":["（雪膚透出極致勾人的桃紅光澤，薄紗下豐乳飽滿微脹、花露暗湧）這兩日駐顏秘術運轉到頂點、身子燙得像燒著火，夫君今晚可得拿命來伺候奴家呀～","今早走過宮道，那兩位守城大將盯著奴家胸乳與腰臀看得眼珠子都快掉出來——這兩日的夏姬，連神仙都扛不住的！","（赤足輕輕磨蹭你的小腿）今晚暖閣點好了最烈的駐顏催情香與合巹酒，夫君快來採補奴家這副不老身子罷！"],"p2":["（煩躁地撥弄著赤紅汗衫，柳眉微蹙）這兩日胸脹心燥、悶得發慌，看誰都覺得索然無味……","嘴裡直想吃酸甜多汁的鮮果，又怕吃多了腰身發圓，真教人心煩意亂！","（挑眉冷笑）夫君這兩日說話可得討巧些，奴家快見紅了，脾氣可沒平日好哄喔。"],"ev":[{"phase":null,"t":"株林歇香・紅棗溫身","l":[[null,"經期的夏姬收起平日勾魂攝魄的張揚，裹著一件厚實赤紅狐裘蜷在暖榻上，小腹墜痛讓她難得顯出幾分慵懶脆弱。"],[null,"（懶洋洋朝你勾起纖指）夫君過來坐嘛～這兩日不能行房，你替奴家剝一盤熱烤栗子、再幫我捂暖這雙冰手好不好？"]],"c":[["笑著坐上暖榻替她剝好滿盤熱栗，順勢把她冰涼雙手揣進胸膛裡暖著",null,"{a}：「（眼波流轉淺笑）沒料到夫君除了榻上兇猛，私下竟也這般會疼女人呢～」"],["命膳房端來溫補當歸紅棗酒，陪她在暖閣聽曲閒談半日",null,"{a}：「有溫酒和夫君守著，小腹倒真沒那麼墜疼了呢。」"],["笑說既不能親熱便先回書房批章疏，起身便走",null,"{a}：「（冷哼一聲）天下男人果然一個德性，吃不到嘴就跑得比野兔還快！」"]],"after":"暫歇採補秘術的株林暖閣，難得流淌出幾分尋常溫存。"},{"phase":null,"t":"春秋絕色・極致勾魂","l":[[null,"排卵期的夏姬美得令人窒息，渾身透出濃烈勾魂的駐顏異香。她今日只著一件幾乎全透的赤紅絲綢衵服，豐乳圓臀畢露，笑吟吟反手落上暖閣門閂。"],[null,"（貼上你胸膛吐氣如蘭，花露早已濡濕紅紗下襬）夫君……這兩日奴家身子裡燒著一團邪火，外頭那些男人都太弱，今晚唯有你能滅了奴家的火！"]],"c":[["徹底被這股致命妖媚點燃，一把將她抱上暖榻徹夜銷魂採補",null,"{a}：「（仰首嬌吟，纖腰死死迎合）咯咯，我就知道夫君永遠戒不掉夏姬這具身子～」紅帳搖曳直至天明，宮婢收榻時滿床皆是濕漬與扯裂的紅紗。"],["笑著先替她斟滿駐顏花酒，細細撫遍她溫軟雪肌再共入羅帳",null,"{a}：「別急嘛，今夜還長得很，慢慢採補才夠味呢……」"],["強自定神推開她稱今晚要巡查城防",null,"{a}：「（美眸驟冷）不解風情的木頭！那這件沾香汗衫我可要賞給前朝大夫囉～」"]],"after":"那一夜株林暖閣的異香與喘息，幾乎將君王的理智徹底燒熔。"},{"phase":null,"t":"經前躁鬱・醋意挑釁","l":[[null,"經前期的夏姬莫名煩躁無聊，竟故意當著你的面展開前朝幾位仰慕者偷送的肉麻情詩大聲吟誦，眼波滿是想逼你醋火攻心的惡劣挑釁！"],[null,"（晃著錦箋冷笑）這兩日悶得心慌，瞧瞧別的男人怎麼誇我雪肌玉臀解解悶——怎麼，夫君吃醋啦？"]],"c":[["一把奪過情詩擲進炭盆，霸道將她按進懷裡重重吻住「只准看我」",{"love":null,"hedon":null,"mood":null},"{a}：「（咯咯大笑熱烈回吻）這才像話嘛！看夫君發狠吃醋，心口那股煩悶全散啦！」"],["笑著端上一碟她最愛的酸甜蜜漬梅子堵住她的紅唇",{"love":null,"food":null,"mood":null},"{a}：「（咬下一顆梅子）嗯……酸甜多汁，剛剛好解膩！」"],["氣得臉色鐵青甩袖離去「妳愛看哪個野男人便慢慢看」",{"love":null,"mood":null},"{a}：「切！半點情趣都沒有，活該氣死你！」"]],"after":"經前的小妖精最愛四處點火，只要順勢把她按上錦榻便能瞬間滅火。"}]},"liji":{"p0":["（素手輕按小腹、臉色微白，楚楚可憐地輕蹙柳眉）這兩日月事見紅發寒、小腹隱隱絞痛……夫君軍政繁忙，莫為妾身這點微恙分心。","（在昏暗燭影下啜著滾燙藥茶，眼底卻冷得像毒蛇）身子見血不適之時，最容易看清哪個蠢貨想趁機落井下石呢。","這幾日妾身氣血虛乏，前朝密報先叫優施壓著罷，夫君夜裡可要多來晉陽暖閣陪妾身說說話。"],"p1":["（雙頰浮起桃紅潮暈，柔婉眼波裡透出極致撩人的春意，素白中衣領口微鬆露出溫潤胸乳）這兩日妾身身子暖融融的、花露微湧，今夜便讓妾身在暖帳裡好好伺候夫君罷。","（柔指輕撫小腹淺笑，眼底深藏算計）這兩日胞宮溫熱最易結珠。若能替夫君懷上嫡脈，往後這座燈塔的未來便徹底穩妥了。","今日妾身親手溫了上等合歡花酒，夫君今夜定要留在晉陽暖閣，別教妾身獨守空榻喔。"],"p2":["（指尖死死攥皺絲帕，溫婉眉宇間透出壓不住的陰冷與焦躁）這兩日胸脹心悶，總覺得前朝那幾名老臣在背後密謀對夫君不利……","（眼眶驟紅、語氣卻帶刺）這幾日身子發沉睡不踏實，夫君若還往別殿跑，妾身真怕自己胡思亂想做出什麼不顧後果的事來。","這安神香點著反倒教人心火直竄，全撤了罷——這兩日看誰都像懷著鬼胎。"],"ev":[{"phase":null,"t":"病弱垂淚・借痛固寵","l":[[null,"經期的驪姬小腹絞痛、臉色蒼白如雪，她精準放大了這份楚楚可憐的病弱態，只披一件素白單衣倚窗輕咳拭淚，見你進門竟強撐著要起身福身。"],[null,"（身子微微一晃軟倒進你懷裡，嗓音柔顫惹人憐惜）夫君怎麼來了……妾身這兩日見紅身子不潔又痛得厲害，怕污了您的眼，您還是去別殿罷……"]],"c":[["心疼地一把將她打橫抱回錦被，親自熬紅糖薑茶寸步不離照料",null,"{a}：「（依偎在你胸膛綻出極致滿足的微笑）夫君這般疼惜妾身，小腹再痛也覺得甜呢。」"],["一眼看穿她三分真痛七分演戲，笑著捏她粉頰「別演了，乖乖躺好喝藥」",null,"{a}：「（先是一怔隨即輕笑靠上來）什麼都瞞不過夫君這雙利眼……那你今晚還是得陪我捂暖小腹嘛。」"],["順著她的話道「既如此妳好生歇著」，轉身便去了別殿",{"love":null,"mood":null},"{a}：「（眼底瞬間冰冷如毒蛇）真走了？好，明早便看哪位姐妹先倒大楣罷。」"]],"after":"真痛三分、演痛七分，這把溫柔毒刀連經期都能算計得滴水不漏。"},{"phase":null,"t":"晉陽密謀・枕邊求嗣","l":[[null,"排卵期的驪姬格外明豔動人，她遣退所有宮婢，在晉陽暖閣備下溫補鹿茸湯與合巹酒，素衣半解露出勝雪香肩與飽滿胸乳，柔聲細語間眼底燒著熾熱渴望。"],[null,"（十指柔滑地解開你外袍腰帶，吐氣如蘭）這兩日妾身身子滾燙得很……夫君，給妾身一個流著你我骨血的孩子罷，我會替他把世上所有絆腳石全清乾淨。"]],"c":[["將她按倒在錦被裡深吻「好，今夜就留宿晉陽暖閣」",null,"{a}：「（滿眼深情與毒計交織，輕喘迎合）夫君最好了，今夜咱們夫妻共築大業……」紅燭滅後徹夜低吟，次日宮婢收拾被褥時見榻單濕濡凌亂。"],["笑著與她共飲合巹酒，順手在枕邊套出優施最新的朝堂密報",null,"{a}：「夫君連在被窩裡都忘不了權謀，難怪妾身這般離不開你。」"],["冷靜抽身推開她「眼下朝局未穩，子嗣之事暫緩」",null,"{a}：「（柔笑驟僵，眼底掠過怨毒）夫君是在防著妾身母憑子貴嗎？」"]],"after":"溫柔吐息與嬌軟軀體之下，暗藏著決定這座城未來歸屬的致命棋局。"},{"phase":null,"t":"經前多疑・夜半進讒","l":[[null,"經前期的氣血躁動讓驪姬本就深重的疑心變得極度偏執——三更時分她赤足披衣衝進書房，紅著眼眶死死攥住你的手，咬定自己夢見某位忠臣明日便要發難謀反！"],[null,"（嬌軀微顫，聲音透出壓抑不住的焦躁）夫君，我這兩天心驚肉跳、胸口憋得發疼，一定是有人要害你我！你明早就把那人鎖進大牢好不好？！"]],"c":[["溫柔將她冰涼的身子裹進大氅安撫「別怕，只是經前做噩夢了」",{"love":null,"mood":null},"{a}：「（死死抱住你深吸一口氣）……有夫君守在身邊，這顆亂跳的心總算定下來了。」"],["順著她的焦躁記下名字「好，明早我就派暗衛盯死他」",{"love":null,"tyranny":null,"mood":null},"{a}：「就知道夫君最信妾身！這下我今晚總算能安穩闔眼了。」"],["冷臉斥她半夜神神叨叨挑撥君臣信任",{"love":null,"mood":null},"{a}：「（瞬間拭乾眼淚冷笑）好，既然夫君不信，日後出事可別後悔！」"]],"after":"連最工於心計的毒蛇，在經前脆弱之時也會被自己的猜忌反噬。"}]}},"pbuild":{"jiananfeng":{"n":null,"where":[null,null],"tile":null,"d":"建於內城暗巷深處的玄鐵石殿，高牆隔絕了一切慘嚎，唯有燒紅烙鐵、短戟與黑霧般的壓迫感教人不寒而慄。","eff":null,"self":null,"ask":"（把玩著冰冷短戟冷笑）大牢裡那群獄卒手太軟，撬不開反賊的嘴。替本宮起一座「東宮刑堂」罷——進了本宮的門，鐵打的漢子也得跪著招供！","done":"（滿意撫過牆上整排玄鐵刑具與烙鐵，發出陰狠冷笑）這才像話！這座東宮刑堂，便是本宮替你鎮壓孤城最順手的屠刀！","max":"（端坐血紅高椅俯視陰森石殿）東宮刑堂之名已能止小兒夜啼！這座城裡，再沒人敢對你我長出半根反骨！","visit":[[[null,"東宮刑堂內陰冷潮濕，炭盆卻燒得通紅發亮，賈南風正親手拿油布擦拭一柄青銅短戟。"],[null,"（斜睨你一眼冷笑）怎麼，天運者也有膽量半夜獨自踏進本宮這座鬼門關？"],[null,"「旁人怕這座刑堂，我只怕妳一個人在這冷石頭屋裡待久了手腳發寒。」"],[null,"（微怔半息，隨即勾起危險笑意拉住你衣襟）油嘴滑舌……既進來了，今晚便在偏室陪本宮喝兩碗血酒！"]],[[null,"刑堂偏閣內點著濃烈西域龍涎香，企圖壓住空氣裡濃重的鐵鏽血氣，賈南風正翻看剛逼出來的密探口供。"],[null,"（將染血供詞拍上石桌）那幾個嘴硬的敵探，撐不到半個時辰就哭著全招了。你說，仁義管用，還是本宮的烙鐵鞭子管用？"],[null,"「對付敵人，確實是妳的手段最痛快。」"],[null,"（暢快大笑，主動貼進你懷裡）哈哈，我就知道你骨子裡跟我一樣狠！"]],[[null,"深夜黑霧籠罩刑堂飛簷，賈南風卸去冰冷護甲，難得露出一絲倦意卻依舊強硬得寸步不讓。"],[null,"外頭人人都在背後罵本宮矮黑醜毒、殘暴淫亂，唯有你替我蓋了這座刑堂，還敢夜夜推門進來。"],[null,"「罵妳的人，多半是怕妳手裡那把生殺大權。」"],[null,"（眼底燒起狂熱執念，十指死死扣住你的手）記住，只要你不負我，誰敢動你，我便把誰活剝了皮掛在刑堂門前！"]]],"ev":[{"pos":null,"t":"刑堂撬口・連根拔諜","l":[[null,"一名潛伏城防營數月的敵國死士被捕後死咬牙關不吐半字，連暗衛都束手無策。賈南風將其拖進東宮刑堂不過兩炷香，拔指、火烙輪番上陣，竟直接逼出了敵軍今夜偷襲水門的絕密暗號！"],[null,"（甩去指尖血水冷笑）什麼死士？進了東宮刑堂，一樣失禁哭爹喊娘！情報在這兒，快去把敵軍先鋒全宰了吧！"]],"c":[["大喜連夜設伏全殲偷襲敵軍，回城重賞東宮刑堂",null,"賈南風：「哈哈哈哈！看前朝那幫酸儒還敢不敢說本宮的刑堂沒用！」"],["依情報擊退敵軍，嘉獎她的功勞卻未再擴張刑堂權限",null,"賈南風：「有功必賞就好，下回抓到硬骨頭繼續往我這兒送！」"],["雖靠情報打了勝仗，仍提醒她審訊手段莫太駭人聽聞",null,"賈南風：「（嗤笑）既要馬兒跑又要馬兒不吃草，真夠虛偽。」"]],"after":"東宮刑堂一戰成名，周邊敵國密探從此聞風喪膽。"},{"pos":null,"t":"刑堂冤獄・民怨沸騰","l":[[null,"賈南風在東宮刑堂大肆羅織罪名，竟僅因幾名城民在酒肆裡私下議論了她眉間贅瘤，便派死士將整間酒肆掌櫃與酒客全鎖進刑堂割舌拷打，鬧得全城人心惶惶！"],[null,"（雙目陰狠冷笑）敢在背後笑話本宮容貌的賤民，只割舌頭算便宜他們了！"]],"c":[["冷酷支持「妄議后妃本就是死罪，全交給妳處置立威」",null,"賈南風：「痛快！看明早全城還有誰敢多嚼半句舌根！」"],["震怒闖入刑堂強行釋放無辜百姓，當眾斥責賈南風濫殺無辜",null,"賈南風：「（咬牙毒笑）為了幾個泥腿子砸本宮的場子？你等著！」"],["命她放回普通酒客，只罰造謠最兇的掌櫃充軍以平民怨",null,"賈南風：「哼，饒了那幾個走運的賤民，掌櫃的雙腿我可已經打斷了。」"]],"after":"東宮刑堂的血腥氣隨風飄散，全城百姓從此談之色變。"}],"envy":"（冷笑捏緊短戟，眼神陰鷙）替{b}蓋新殿宇？好啊，蓋得越華麗越好，免得本宮將來抄她家時沒東西可砸！","ruin":"（立在東宮刑堂的斷壁殘垣前，眼中燃起瘋狂毒火）敢拆本宮的刑堂？！天運者，你若不把動手的人交出來剝皮，我就點燃整座內城！"},"daji":{"n":null,"where":[null,null],"tile":null,"d":"以黃金美玉築起的奢靡高臺，臺下酒池肉林、炮烙炭火長明，在歸墟黑霧裡散發著令人沉淪的妖異紅光。","eff":null,"self":null,"ask":"（赤足玉趾勾住你的衣擺嬌笑）這座冷石頭城悶得像棺材呀～替奴家重起一座「鹿台」罷！要有酒池、有肉林，還要高得能摸到黑霧裡的星光！","done":"（張開雙臂立於黃金高臺狂笑，紅紗翻飛）咯咯咯！這才配得上青丘九尾狐與商紂王嘛！今晚全城陪奴家一起醉生夢死囉！","max":"（俯瞰燈火通明的極樂高臺，眼底妖火熾盛）鹿台已成歸墟第一魔窟！夫君，有奴家陪你在這兒日夜銷魂，還要什麼明君虛名呀？","visit":[[[null,"鹿台頂層絲竹靡靡，妲己斜倚在酒池邊的白玉榻上，雪白長腿浸在溫熱酒波裡，指尖蘸著血紅佳釀輕晃。"],[null,"（回眸妖冶一笑）外頭那幫酸儒又在罵奴家禍國啦？來，夫君別理他們吠，喝下這杯狐仙酒。"],[null,"「妳這杯酒裡，該不會又摻了讓人忘本的催情迷香吧？」"],[null,"（湊近你唇邊吹氣輕笑）對付夫君哪用得著迷香？奴家這副身子與這雙妖眼，就夠讓你神魂顛倒一整夜了呢～"]],[[null,"深夜黑霧翻湧，鹿台炭火卻燒得滾燙通紅，妲己赤足踩在溫玉磚上，九尾虛影在紅燭裡緩緩搖曳。"],[null,"夫君瞧，這歸墟世界本就朝不保夕，守著那些死板規矩活得多累呀。"],[null,"「所以妳才起這座鹿台，想拉著我一起沉淪？」"],[null,"（主動勾住你脖頸貼上豐軟酥胸低笑）一起沉淪不好嗎？牡丹花下死，做鬼也風流嘛，咯咯～"]],[[null,"鹿台偏閣擺滿西域珍饈與烈酒，妲己把玩著一隻金爵等你入席，薄紗領口滑落半肩。"],[null,"今晚不許提城防、不許提軍糧，誰提半個字便罰灌三大壇！"],[null,"「那今晚只准說什麼？」"],[null,"（眼波瀲灩流轉，一把將你拽進層層紅紗帳裡）只准說……你有多迷戀奴家這頭吃人的小妖精呀。"]]],"ev":[{"pos":null,"t":"鹿台迷霧・誘殺敵探","l":[[null,"數名敵軍頂尖密探趁夜潛入主城刺探軍防，卻被鹿台徹夜不歇的靡靡酒香與妖異樂聲徹底迷亂心智，大搖大擺鑽進陷阱，被妲己親手灌醉活捉！"],[null,"（赤足踩在昏死敵探背上咯咯大笑）瞧瞧，你們守軍找了三天抓不著的老鼠，奴家在鹿台喝兩杯酒便全釣上來囉！"]],"c":[["大笑讚她歪打正著立了奇功，賞她十車西域極品烈酒",null,"妲己：「哈哈，我就說鹿台才是這座城最強的殺陣嘛！」"],["連夜酷刑審出敵營佈防，順便誇她這回沒白折騰",null,"妲己：「立了大功，今晚夫君可得好好在酒池裡陪奴家瘋個夠喔～」"],["收押敵探但提醒她莫把可疑外人隨意放進鹿台",null,"妲己：「切，真掃興，人家明明替你抓了細作呢。」"]],"after":"誰也沒料到，這座最荒唐的極樂魔窟竟成了叫敵探有來無回的溫柔陷阱。"},{"pos":null,"t":"鹿台炮烙・怨聲載道","l":[[null,"妲己在鹿台下私架青銅炮烙炭柱，僅因兩名運酒民夫手滑摔碎一壇西域佳釀，她便笑嘻嘻命人將兩人綁上燒紅銅柱活烤！消息傳出，全城百姓無不毛骨悚然！"],[null,"（眨著天真又殘忍的大眼）摔碎了夫君最愛的烈酒，烤焦他們的手腳配酒吃，很公道嘛～"]],"c":[["狂笑點頭任由她行刑「烤吧！這座鹿台本就該見血才夠味」",null,"妲己：「哈哈哈哈！這才配做我的商紂王！今晚咱們邊聽慘嚎邊喝酒！」"],["立刻喝止酷刑放走民夫，冷臉嚴禁鹿台私設炮烙",null,"妲己：「（撇嘴冷笑）裝什麼大善人？沒勁透了！」"],["改罰民夫做苦役抵債保命，私下拿新奇玩意兒哄住妲己",null,"妲己：「看在夫君替他們求情的份上，今晚便先不聞烤肉味囉。」"]],"after":"鹿台之上赤光沖天，在百姓眼中徹底成了恐懼與墮落的象徵。"}],"envy":"（妖瞳微瞇，雪尾輕掃玉磚冷笑）替{b}蓋新窩啦？哼，再華麗能比得上奴家的鹿台銷魂嗎？小心我半夜去放把狐火燒光喔～","ruin":"（望著焦黑崩塌的鹿台廢墟，非但沒哭反倒瘋狂大笑）燒吧、塌吧！只要男人的貪慾沒斷根，九尾狐隨時能在你心裡再蓋十座鹿台！"},"xiaji":{"n":null,"where":[null,null,null],"tile":null,"d":"掩映於幽深古林與重重赤紗中的銷魂別苑，終日駐顏奇香嫋嫋，連城外黑霧逼近林緣都似染上幾分靡靡春意。","eff":null,"self":null,"ask":"（纖指輕劃過你胸膛媚笑）深宮裡耳目太雜，修煉春秋採補駐顏術多不方便呀～夫君替奴家在林子裡起一座「株林別苑」罷，保準教夫君每次來都捨不得下床！","done":"（赤足踏過垂滿赤紅輕紗的林間長廊咯咯嬌笑）這座株林別苑比當年陳國株林還銷魂呢！夫君，今晚便由你先替奴家暖床開張囉～","max":"（倚在株林高閣欄杆上拋來一個致命媚眼）如今全城男人都對株林別苑魂牽夢縈呢——可這扇紅門，奴家終究只替夫君留著最後一道鎖。","visit":[[[null,"株林別苑內赤紗輕舞，濃郁西域駐顏香撲面而來，夏姬斜倚軟榻小口啜飲溫熱果酒，雪白長腿在紅紗間若隱若現。"],[null,"（眼波似水地望著你）夫君近來瘦了幾分，是前朝章疏太煩，還是想奴家這副身子想得睡不著呀？"],[null,"「兩種都有，不過一踏進妳這株林，章疏倒是立刻忘光了。」"],[null,"（掩唇嬌笑，伸手拉你落座榻邊）這就對啦，今晚只管讓奴家用採補秘術替夫君好好補回元氣喔～"]],[[null,"林間晚風微涼，株林別苑的溫泉湯池水汽氤氳，夏姬赤身披著薄紗坐在池畔梳理烏黑長髮，水珠順著豐滿雪乳滑落。"],[null,"外頭人人都罵我夏姬是剋夫亂國的妖婦，夫君替我起這座株林別苑，就不怕被我迷得丟了江山？"],[null,"「能守住江山又能享絕世尤物，才叫真本事。」"],[null,"（美眸驟亮，轉身貼上你胸膛低笑）咯咯，夫君這股狂氣，比春秋那群軟骨頭國君迷人一百倍呢！"]],[[null,"深夜黑霧壓過林梢，別苑裡卻紅燭搖曳、暖香四溢，夏姬親手替你斟滿一爵帶著奇香的合歡釀。"],[null,"飲下這杯酒，今晚可就不許再提任何別的女人的名字囉。"],[null,"「妳株林裡的酒，我幾時推辭過？」"],[null,"（接過空爵媚笑，纖指熟練解開你的腰帶）夫君真乖……今晚奴家定教你魂銷株林。"]]],"ev":[{"pos":null,"t":"株林策反・不戰降將","l":[[null,"城外一支極難纏的荒原游騎首領原本打算聯合敵軍攻城，卻在聽聞夏姬株林別苑豔名後偷偷遣使求見！夏姬僅隔著三層赤紗與他對飲三杯、說了幾句勾魂軟語，便迷得對方神魂顛倒，當場宣布率部歸降燈塔！"],[null,"（晃著降書得意嬌笑）兵部打了一個月啃不下的硬骨頭，奴家在株林喝兩杯酒便叫他乖乖跪下囉！夫君今晚打算怎麼賞奴家呀？"]],"c":[["大笑收編游騎並重賞株林別苑「妳這溫柔刀比千軍萬馬管用」",null,"夏姬：「嘻嘻，往後城外哪個首領不聽話，全交給奴家請進株林喝茶罷！」"],["將降騎妥善編入外城守軍，溫言誇她立了奇功",null,"夏姬：「夫君高興便好，今晚留在株林好好謝我嘛～」"],["收下降書卻吃醋警告她「下回不許離那些粗魯男人太近」",null,"夏姬：「咯咯，隔著三層赤紗呢，奴家身上可只有夫君摸得到喔！」"]],"after":"株林別苑一席酒定乾坤的豔名傳開，敵酋們既垂涎又忌憚。"},{"pos":null,"t":"株林爭風・朝臣拔刀","l":[[null,"兩名素來癡迷夏姬的年輕朝臣竟各帶厚禮在株林別苑門外狹路相逢，為了爭搶誰先獲准入內獻寶，兩人當街拔刀火拚見血，鬧得滿城皆知、禮部顏面掃地！"],[null,"（倚在二樓紅欄上掩唇看戲輕笑）男人為了奴家爭風吃醋拔刀砍人，這不是常有的事嘛，夫君何必動怒呀？"]],"c":[["大笑毫不在意「打贏的賞十兩酒錢，誰教他們迷上本王的尤物」",null,"夏姬：「哈哈哈哈！夫君真是豁達，今晚奴家加倍伺候你！」"],["震怒將兩名朝臣革職下獄，嚴令株林別苑謝絕一切外男踏入",null,"夏姬：「（嘟唇冷笑）把我的仰慕者全關進大牢？夫君心眼可真小呢。」"],["罰兩名朝臣停俸半年，私下把夏姬按上軟榻狠狠宣告主權",null,"夏姬：「哎呀，夫君吃起醋來這麼兇狠……不過奴家喜歡！」"]],"after":"株林別苑門外的刀光血跡，再度印證了春秋禍水絕非虛傳。"}],"envy":"（掩唇冷笑，眼底卻暗燒醋火）替{b}起新殿宇啦？咯咯，夫君別被她那副假清高唬住了，論銷魂蝕骨，全城誰比得上我的株林別苑？","ruin":"（望著燒焦傾頹的株林赤紗與殘垣，輕嘆一息隨即妖豔一笑）別苑塌了無妨，只要夫君這顆心與這副身子還攥在奴家掌裡，哪裡都能是株林。"},"liji":{"n":null,"where":[null,null,null],"tile":null,"d":"深藏於幽暗密林中的精緻別館，小橋流水底下掩藏無數密道暗門，正是驪戎密探與枕邊離間局的真正中樞。","eff":null,"self":null,"ask":"（垂眸輕嘆，語氣柔婉卻藏著算計）深宮裡人多耳雜，許多替夫君打探來的朝堂密辛不便當眾稟報。若能替妾身起一座清靜的「驪戎幽苑」，妾身便能更安穩地替您分憂了。","done":"（輕撫過幽苑的雕花暗門，綻出一抹滿意而冰冷的淺笑）曲徑通幽、密不透風……夫君這份心意，妾身定以滿朝清靜作報。","max":"（立於幽苑高閣俯瞰全城萬家燈火）這座驪戎幽苑如今已連通全城暗網——夫君，只要你我同心，這座孤城便無人逃得出咱們掌心。","visit":[[[null,"驪戎幽苑內靜得只餘潺潺水聲，驪姬親手替你沏上一盞帶著淡香的晉地苦丁茶，素袖輕垂。"],[null,"（雙手奉茶，眼波溫柔如水）外頭黑霧沉沉、百官各懷鬼胎，唯有在這幽苑裡，夫君才能徹底卸下防備。"],[null,"「妳這座幽苑裡，暗門比窗欞還多，真能教我卸下防備？」"],[null,"（輕笑靠進你懷裡低語）暗門是用來防外人的……對夫君，妾身從來都是敞開心扉、敞開衣襟的呀。"]],[[null,"深夜幽苑暖閣燭影搖紅，驪姬剛聽完優施在屏風外低聲回報密信，轉身便換上最柔弱迷人的微笑迎上來。"],[null,"（替你解下沉重披風）剛才又查出一位大將私下怨恨軍餉微薄……不過今夜不談這些掃興事了。"],[null,"「妳總能在最溫柔的時候，順手往我手裡遞把染血的刀。」"],[null,"（眼波微漾，纖指輕點你唇瓣）若非為了護住夫君的龍椅，妾身又何苦當這個人人咒罵的壞女人呢？"]],[[null,"雨夜打濕幽苑青苔石階，室內炭火正暖，驪姬難得卸下層層心計，安靜依偎在你肩頭聽雨。"],[null,"當年從驪戎被當作戰利品擄進晉宮，我便立誓這輩子絕不再任人魚肉……幸好今生遇見了你。"],[null,"「在這座幽苑裡，沒人能再欺妳半分。」"],[null,"（眼底掠過一絲真實動容，十指緊緊反扣你的掌心）那今夜，夫君便留在幽苑暖帳裡，哪兒也別去。"]]],"ev":[{"pos":null,"t":"幽苑密報・截殺刺客","l":[[null,"驪戎幽苑的密探網竟提前三日嗅出敵國死士偽裝商隊雜役潛入內城準備行刺你！驪姬不動聲色地將刺客引入幽苑暗巷，一夜之間全數無聲毒殺滅口！"],[null,"（遞上一枚從刺客屍身搜出的敵國令牌柔聲微笑）外頭都說幽苑陰森，可正是這座陰森小院，今晚替夫君擋下了奪命冷刃呢。"]],"c":[["感動地緊擁住她，重賞幽苑暗探並賜予她更高的密探權限",null,"驪姬：「謝夫君信重。有驪戎幽苑在，誰也傷不了夫君一根汗毛。」"],["收起敵國令牌順藤摸瓜追查幕後黑手，嘉獎她護駕奇功",null,"驪姬：「能替夫君分憂，便是妾身最大的福分。」"],["謝過救命之恩，卻暗暗記下幽苑密探的驚人實力以作防範",null,"驪姬：「（垂眸淺笑）夫君只要記牢，這把暗刃永遠只對準您的敵人便好。」"]],"after":"驪戎幽苑的密網無聲運轉，化作護衛君王最隱蔽也最陰毒的暗盾。"},{"pos":null,"t":"幽苑毒計・離間忠良","l":[[null,"你無意間在驪戎幽苑密室撞見優施正臨摹筆跡偽造一名剛直老將的「通敵密信」——原來驪姬只因那老將曾當眾批評幽苑陰森奢靡，便打算用這封假信置他於死地！"],[null,"（見事敗先是一怔，隨即楚楚可憐地跪地垂淚）那老將手握重兵又對妾身不敬，今日敢罵妾身，明日便敢犯上作亂呀！夫君難道不信妾身一片苦心？"]],"c":[["冷血默許「既對妳不敬，這封假信便當真的用，抄了他！」",null,"驪姬：「（拭乾眼淚綻出完美微笑）夫君英明！這座城終於又少了一個眼中釘。」"],["震怒當場燒毀假信、重罰優施並嚴厲警告驪姬不許再構陷忠良",null,"驪姬：「（眼底掠過一絲陰冷怨毒）……妾身知錯了，往後再不敢多管閒事。」"],["不動聲色收起假信揣進懷裡「留著當把柄牽制老將即可，不必殺他」",null,"驪姬：「（破涕為笑）還是夫君手段高明，一舉兩得。」"]],"after":"驪戎幽苑的燈火徹夜未熄，毒計與猜忌仍在暗影裡悄然蔓生。"}],"envy":"（眼眶微紅卻笑得柔婉如水）夫君替{b}起新殿宇了呀……真好。只是妾身這座冷清的驪戎幽苑，怕是以後更少見著夫君身影了呢。","ruin":"（立在化為灰燼的幽苑暗門前，平日溫婉的偽裝徹底撕碎，冷笑森然）毀了我的幽苑……很好，這座城裡誰動的土，我就拿誰的命來填坑！"}}};
function mg(t,s){if(!t||typeof t!=='object')return;for(const k in s){const v=s[k];if(v==null)continue;if(!(k in t))continue;const o=t[k];if(typeof v==='string'){if(typeof o==='string')t[k]=v}else if(typeof v==='object'&&o&&typeof o==='object'&&Array.isArray(v)===Array.isArray(o))mg(o,v)}}
if(root&&typeof root==='object'){root.GD=root.GD||{};mg(root.GD,D)}
if(typeof module!=='undefined'&&module.exports)module.exports={D,apply:function(G){mg(G,D);return G}};
})(typeof window!=='undefined'?window:null);
